#import "aljabr_metal_kernel_source.h"

// Forward declaration — defined at end of file
static void aljabr_build_ffn_gate_up_act_q6_k_mr4_src(NSMutableString *src, NSUInteger threads);
static void aljabr_build_ffn_gate_up_act_q6_k_b4_mr4_src(NSMutableString *src, NSUInteger threads);
static void aljabr_build_q6_k_softcap_src(NSMutableString *src);
static void aljabr_build_q4_k_softcap_src(NSMutableString *src);

NSString *aljabr_metal_runtime_kernel_source(void) {
  return @"#include <metal_stdlib>\n"
         @"using namespace metal;\n"
         @"constant uint ALJABR_RMS_THREADS = 256;\n"
         @"constant uint ALJABR_MATVEC_THREADS = 256;\n"
         @"static inline float aljabr_silu_gate(float g) {\n"
         @"    if (g <= -20.0f) return 0.0f;\n"
         @"    if (g >= 20.0f) return g;\n"
         @"    return g / (1.0f + exp(-g));\n"
         @"}\n"
         @"static inline float aljabr_gelu_gate(float g) {\n"
         @"    if (g <= -10.0f) return 0.0f;\n"
         @"    if (g >= 10.0f) return g;\n"
         @"    float inner = 0.79788456f * (g + 0.044715f * g * g * g);\n"
         @"    return 0.5f * g * (1.0f + tanh(inner));\n"
         @"}\n"
         @"static inline float aljabr_gated_activation(float gate, float "
         @"up, uint activation_kind) {\n"
         @"    float act = activation_kind == 1u ? aljabr_silu_gate(gate) "
         @": aljabr_gelu_gate(gate);\n"
         @"    float y = act * up;\n"
         @"    return isfinite(y) ? y : 0.0f;\n"
         @"}\n"
         @"kernel void aljabr_add_kernel(\n"
         @"    device float* C [[buffer(0)]],\n"
         @"    device const float* A [[buffer(1)]],\n"
         @"    device const float* B [[buffer(2)]],\n"
         @"    constant uint& N [[buffer(3)]],\n"
         @"    uint gid [[thread_position_in_grid]]) {\n"
         @"    if (gid < N) C[gid] = A[gid] + B[gid];\n"
         @"}\n"
         @"kernel void aljabr_silu_kernel(\n"
         @"    device float* out [[buffer(0)]],\n"
         @"    device const float* x [[buffer(1)]],\n"
         @"    constant uint& N [[buffer(2)]],\n"
         @"    uint gid [[thread_position_in_grid]]) {\n"
         @"    if (gid < N) {\n"
         @"        float g = x[gid];\n"
         @"        if (g <= -20.0f) out[gid] = 0.0f;\n"
         @"        else if (g >= 20.0f) out[gid] = g;\n"
         @"        else out[gid] = g / (1.0f + exp(-g));\n"
         @"    }\n"
         @"}\n"
         @"kernel void aljabr_gelu_kernel(\n"
         @"    device float* out [[buffer(0)]],\n"
         @"    device const float* x [[buffer(1)]],\n"
         @"    constant uint& N [[buffer(2)]],\n"
         @"    uint gid [[thread_position_in_grid]]) {\n"
         @"    if (gid < N) {\n"
         @"        float g = x[gid];\n"
         @"        if (g <= -10.0f) out[gid] = 0.0f;\n"
         @"        else if (g >= 10.0f) out[gid] = g;\n"
         @"        else {\n"
         @"            float inner = 0.79788456f * (g + 0.044715f * g * g * "
         @"g);\n"
         @"            out[gid] = 0.5f * g * (1.0f + tanh(inner));\n"
         @"        }\n"
         @"    }\n"
         @"}\n"
         @"kernel void aljabr_silu_ffn_kernel(\n"
         @"    device float* out [[buffer(0)]],\n"
         @"    device const float* gate [[buffer(1)]],\n"
         @"    device const float* up [[buffer(2)]],\n"
         @"    constant uint& N [[buffer(3)]],\n"
         @"    uint gid [[thread_position_in_grid]]) {\n"
         @"    if (gid >= N) return;\n"
         @"    float g = gate[gid];\n"
         @"    float act;\n"
         @"    if (g <= -20.0f) {\n"
         @"        act = 0.0f;\n"
         @"    } else if (g >= 20.0f) {\n"
         @"        act = g;\n"
         @"    } else {\n"
         @"        act = g / (1.0f + exp(-g));\n"
         @"    }\n"
         @"    float y = act * up[gid];\n"
         @"    out[gid] = isfinite(y) ? y : 0.0f;\n"
         @"}\n"
         @"kernel void aljabr_gelu_ffn_kernel(\n"
         @"    device float* out [[buffer(0)]],\n"
         @"    device const float* gate [[buffer(1)]],\n"
         @"    device const float* up [[buffer(2)]],\n"
         @"    constant uint& N [[buffer(3)]],\n"
         @"    uint gid [[thread_position_in_grid]]) {\n"
         @"    if (gid >= N) return;\n"
         @"    float g = gate[gid];\n"
         @"    float gelu;\n"
         @"    if (g <= -10.0f) {\n"
         @"        gelu = 0.0f;\n"
         @"    } else if (g >= 10.0f) {\n"
         @"        gelu = g;\n"
         @"    } else {\n"
         @"        float inner = 0.79788456f * (g + 0.044715f * g * g * g);\n"
         @"        gelu = 0.5f * g * (1.0f + tanh(inner));\n"
         @"    }\n"
         @"    float y = gelu * up[gid];\n"
         @"    out[gid] = isfinite(y) ? y : 0.0f;\n"
         @"}\n"
         @"kernel void aljabr_softcap_kernel(\n"
         @"    device float* x [[buffer(0)]],\n"
         @"    constant float& cap [[buffer(1)]],\n"
         @"    constant uint& N [[buffer(2)]],\n"
         @"    uint gid [[thread_position_in_grid]]) {\n"
         @"    if (gid < N) {\n"
         @"        x[gid] = cap * precise::tanh(x[gid] / cap);\n"
         @"    }\n"
         @"}\n"
         @"kernel void aljabr_scale_kernel(\n"
         @"    device float* x [[buffer(0)]],\n"
         @"    constant float& scale [[buffer(1)]],\n"
         @"    constant uint& N [[buffer(2)]],\n"
         @"    uint gid [[thread_position_in_grid]]) {\n"
         @"    if (gid < N) {\n"
         @"        x[gid] *= scale;\n"
         @"    }\n"
         @"}\n"
         @"kernel void aljabr_rmsnorm_kernel(\n"
         @"    device float* out [[buffer(0)]],\n"
         @"    device const float* x [[buffer(1)]],\n"
         @"    device const float* weight [[buffer(2)]],\n"
         @"    constant uint& N [[buffer(3)]],\n"
         @"    constant float& eps [[buffer(4)]],\n"
         @"    constant uint& addOne [[buffer(5)]],\n"
         @"    uint simd_lane_id [[thread_index_in_simdgroup]],\n"
         @"    uint simd_group_id [[simdgroup_index_in_threadgroup]],\n"
         @"    uint tid [[thread_position_in_threadgroup]]) {\n"
         @"    float ss = 0.0f;\n"
         @"    for (uint i = tid; i < N; i += ALJABR_RMS_THREADS) {\n"
         @"        float v = x[i];\n"
         @"        ss += v * v;\n"
         @"    }\n"
         @"    float simd_ss = simd_sum(ss);\n"
         @"    threadgroup float partial[32];\n"
         @"    if (simd_lane_id == 0) partial[simd_group_id] = simd_ss;\n"
         @"    threadgroup_barrier(mem_flags::mem_threadgroup);\n"
         @"    float final_ss = 0.0f;\n"
         @"    if (simd_group_id == 0) {\n"
         @"        final_ss = simd_lane_id < (ALJABR_RMS_THREADS / 32) ? "
         @"partial[simd_lane_id] : 0.0f;\n"
         @"        final_ss = simd_sum(final_ss);\n"
         @"        if (simd_lane_id == 0) partial[0] = final_ss;\n"
         @"    }\n"
         @"    threadgroup_barrier(mem_flags::mem_threadgroup);\n"
         @"    float inv = rsqrt((partial[0] / float(N)) + eps);\n"
         @"    for (uint i = tid; i < N; i += ALJABR_RMS_THREADS) {\n"
         @"        float w = weight[i] + (addOne != 0 ? 1.0f : 0.0f);\n"
         @"        out[i] = x[i] * inv * w;\n"
         @"    }\n"
         @"}\n"
         @"kernel void aljabr_rmsnorm_float4_kernel(\n"
         @"    device float* out [[buffer(0)]],\n"
         @"    device const float* x [[buffer(1)]],\n"
         @"    device const float* weight [[buffer(2)]],\n"
         @"    constant uint& N [[buffer(3)]],\n"
         @"    constant float& eps [[buffer(4)]],\n"
         @"    constant uint& addOne [[buffer(5)]],\n"
         @"    uint simd_lane_id [[thread_index_in_simdgroup]],\n"
         @"    uint simd_group_id [[simdgroup_index_in_threadgroup]],\n"
         @"    uint tid [[thread_position_in_threadgroup]]) {\n"
         @"    device const float4* x4 = (device const float4*)x;\n"
         @"    device float4* out4 = (device float4*)out;\n"
         @"    device const float4* weight4 = (device const float4*)weight;\n"
         @"    uint N4 = N / 4;\n"
         @"    float ss = 0.0f;\n"
         @"    for (uint i = tid; i < N4; i += ALJABR_RMS_THREADS) {\n"
         @"        float4 v = x4[i];\n"
         @"        ss += dot(v, v);\n"
         @"    }\n"
         @"    float simd_ss = simd_sum(ss);\n"
         @"    threadgroup float partial[32];\n"
         @"    if (simd_lane_id == 0) partial[simd_group_id] = simd_ss;\n"
         @"    threadgroup_barrier(mem_flags::mem_threadgroup);\n"
         @"    float final_ss = 0.0f;\n"
         @"    if (simd_group_id == 0) {\n"
         @"        final_ss = simd_lane_id < (ALJABR_RMS_THREADS / 32) ? "
         @"partial[simd_lane_id] : 0.0f;\n"
         @"        final_ss = simd_sum(final_ss);\n"
         @"        if (simd_lane_id == 0) partial[0] = final_ss;\n"
         @"    }\n"
         @"    threadgroup_barrier(mem_flags::mem_threadgroup);\n"
         @"    float inv = rsqrt((partial[0] / float(N)) + eps);\n"
         @"    float4 addOneVec = addOne != 0 ? float4(1.0f) : float4(0.0f);\n"
         @"    for (uint i = tid; i < N4; i += ALJABR_RMS_THREADS) {\n"
         @"        float4 w = weight4[i] + addOneVec;\n"
         @"        out4[i] = x4[i] * inv * w;\n"
         @"    }\n"
         @"}\n"
         @"kernel void aljabr_rope_kernel(\n"
         @"    device float* out [[buffer(0)]],\n"
         @"    device const float* x [[buffer(1)]],\n"
         @"    constant uint& N [[buffer(2)]],\n"
         @"    constant uint& head_dim [[buffer(3)]],\n"
         @"    constant uint& pos_offset [[buffer(4)]],\n"
         @"    constant float& freq_base [[buffer(5)]],\n"
         @"    constant uint& is_neox [[buffer(6)]],\n"
         @"    uint gid [[thread_position_in_grid]]) {\n"
         @"    if (gid >= N / 2) return;\n"
         @"    uint half_dim = head_dim / 2;\n"
         @"    uint token_head_idx = gid / half_dim;\n"
         @"    uint pos = pos_offset + token_head_idx;\n"
         @"    uint i = gid % half_dim;\n"
         @"    float freq = 1.0f / pow(freq_base, 2.0f * float(i) / "
         @"float(head_dim));\n"
         @"    float theta = float(pos) * freq;\n"
         @"    float cos_theta = cos(theta);\n"
         @"    float sin_theta = sin(theta);\n"
         @"    uint base = token_head_idx * head_dim;\n"
         @"    uint i0, i1;\n"
         @"    if (is_neox != 0) {\n"
         @"        i0 = base + i;\n"
         @"        i1 = base + i + half_dim;\n"
         @"    } else {\n"
         @"        i0 = base + 2 * i;\n"
         @"        i1 = base + 2 * i + 1;\n"
         @"    }\n"
         @"    float x0 = x[i0];\n"
         @"    float x1 = x[i1];\n"
         @"    out[i0] = x0 * cos_theta - x1 * sin_theta;\n"
         @"    out[i1] = x0 * sin_theta + x1 * cos_theta;\n"
         @"}\n"
         @"kernel void aljabr_layernorm_kernel(\n"
         @"    device float* out [[buffer(0)]],\n"
         @"    device const float* x [[buffer(1)]],\n"
         @"    device const float* weight [[buffer(2)]],\n"
         @"    device const float* bias [[buffer(3)]],\n"
         @"    constant uint& N [[buffer(4)]],\n"
         @"    constant float& eps [[buffer(5)]],\n"
         @"    uint simd_lane_id [[thread_index_in_simdgroup]],\n"
         @"    uint simd_group_id [[simdgroup_index_in_threadgroup]],\n"
         @"    uint tid [[thread_position_in_threadgroup]]) {\n"
         @"    float s = 0.0f;\n"
         @"    float ss = 0.0f;\n"
         @"    for (uint i = tid; i < N; i += ALJABR_RMS_THREADS) {\n"
         @"        float v = x[i];\n"
         @"        s += v;\n"
         @"        ss += v * v;\n"
         @"    }\n"
         @"    float simd_s = simd_sum(s);\n"
         @"    float simd_ss = simd_sum(ss);\n"
         @"    threadgroup float partial_sum[32];\n"
         @"    threadgroup float partial_sq[32];\n"
         @"    if (simd_lane_id == 0) {\n"
         @"        partial_sum[simd_group_id] = simd_s;\n"
         @"        partial_sq[simd_group_id] = simd_ss;\n"
         @"    }\n"
         @"    threadgroup_barrier(mem_flags::mem_threadgroup);\n"
         @"    float final_s = 0.0f;\n"
         @"    float final_ss = 0.0f;\n"
         @"    if (simd_group_id == 0) {\n"
         @"        final_s = simd_lane_id < (ALJABR_RMS_THREADS / 32) ? "
         @"partial_sum[simd_lane_id] : 0.0f;\n"
         @"        final_ss = simd_lane_id < (ALJABR_RMS_THREADS / 32) ? "
         @"partial_sq[simd_lane_id] : 0.0f;\n"
         @"        final_s = simd_sum(final_s);\n"
         @"        final_ss = simd_sum(final_ss);\n"
         @"        if (simd_lane_id == 0) {\n"
         @"            partial_sum[0] = final_s;\n"
         @"            partial_sq[0] = final_ss;\n"
         @"        }\n"
         @"    }\n"
         @"    threadgroup_barrier(mem_flags::mem_threadgroup);\n"
         @"    float mean = partial_sum[0] / float(N);\n"
         @"    float variance = (partial_sq[0] / float(N)) - (mean * mean);\n"
         @"    float inv = rsqrt(max(variance, 0.0f) + eps);\n"
         @"    for (uint i = tid; i < N; i += ALJABR_RMS_THREADS) {\n"
         @"        float w = weight ? weight[i] : 1.0f;\n"
         @"        float b = bias ? bias[i] : 0.0f;\n"
         @"        out[i] = (x[i] - mean) * inv * w + b;\n"
         @"    }\n"
         @"}\n"
         // ---- RoPE float2 fused kernel ----
         // Reads element pairs as float2 to halve memory transactions. Each
         // thread handles one (x0, x1) pair and writes the rotated pair back as
         // float2.
         @"kernel void aljabr_rope_float2_kernel(\n"
         @"    device float* out [[buffer(0)]],\n"
         @"    device const float* x [[buffer(1)]],\n"
         @"    constant uint& N [[buffer(2)]],\n"
         @"    constant uint& head_dim [[buffer(3)]],\n"
         @"    constant uint& pos_offset [[buffer(4)]],\n"
         @"    constant float& freq_base [[buffer(5)]],\n"
         @"    constant uint& is_neox [[buffer(6)]],\n"
         @"    uint gid [[thread_position_in_grid]]) {\n"
         @"    if (gid >= N / 2) return;\n"
         @"    uint half_dim = head_dim / 2;\n"
         @"    uint token_head_idx = gid / half_dim;\n"
         @"    uint pos = pos_offset + token_head_idx;\n"
         @"    uint i = gid % half_dim;\n"
         @"    float freq = 1.0f / pow(freq_base, 2.0f * float(i) / "
         @"float(head_dim));\n"
         @"    float theta = float(pos) * freq;\n"
         @"    float2 cs = float2(cos(theta), sin(theta));\n"
         @"    uint base = token_head_idx * head_dim;\n"
         @"    uint i0, i1;\n"
         @"    if (is_neox != 0) {\n"
         @"        i0 = base + i;\n"
         @"        i1 = base + i + half_dim;\n"
         @"    } else {\n"
         @"        i0 = base + 2 * i;\n"
         @"        i1 = base + 2 * i + 1;\n"
         @"    }\n"
         @"    // Load pair as float2 for coalesced access\n"
         @"    float2 pair = float2(x[i0], x[i1]);\n"
         @"    out[i0] = pair.x * cs.x - pair.y * cs.y;\n"
         @"    out[i1] = pair.x * cs.y + pair.y * cs.x;\n"
         @"}\n"
         // ---- float4-vectorized LayerNorm ----
         // Uses float4 for the sum/sum-of-squares reduction loops (4x fewer
         // loads), then writes the normalised output also in float4 chunks.
         @"kernel void aljabr_layernorm_float4_kernel(\n"
         @"    device float* out [[buffer(0)]],\n"
         @"    device const float* x [[buffer(1)]],\n"
         @"    device const float* weight [[buffer(2)]],\n"
         @"    device const float* bias [[buffer(3)]],\n"
         @"    constant uint& N [[buffer(4)]],\n"
         @"    constant float& eps [[buffer(5)]],\n"
         @"    uint simd_lane_id [[thread_index_in_simdgroup]],\n"
         @"    uint simd_group_id [[simdgroup_index_in_threadgroup]],\n"
         @"    uint tid [[thread_position_in_threadgroup]]) {\n"
         @"    device const float4* x4 = (device const float4*)x;\n"
         @"    device float4* out4 = (device float4*)out;\n"
         @"    device const float4* weight4 = (device const float4*)weight;\n"
         @"    device const float4* bias4   = (device const float4*)bias;\n"
         @"    uint N4 = N / 4;\n"
         @"    // Pass 1: accumulate sum and sum-of-squares with float4\n"
         @"    float4 acc_s  = float4(0.0f);\n"
         @"    float4 acc_ss = float4(0.0f);\n"
         @"    for (uint i = tid; i < N4; i += ALJABR_RMS_THREADS) {\n"
         @"        float4 v = x4[i];\n"
         @"        acc_s  += v;\n"
         @"        acc_ss += v * v;\n"
         @"    }\n"
         @"    float s  = acc_s.x  + acc_s.y  + acc_s.z  + acc_s.w;\n"
         @"    float ss = acc_ss.x + acc_ss.y + acc_ss.z + acc_ss.w;\n"
         @"    float simd_s  = simd_sum(s);\n"
         @"    float simd_ss = simd_sum(ss);\n"
         @"    threadgroup float partial_sum[32];\n"
         @"    threadgroup float partial_sq[32];\n"
         @"    if (simd_lane_id == 0) {\n"
         @"        partial_sum[simd_group_id] = simd_s;\n"
         @"        partial_sq[simd_group_id]  = simd_ss;\n"
         @"    }\n"
         @"    threadgroup_barrier(mem_flags::mem_threadgroup);\n"
         @"    float final_s = 0.0f, final_ss = 0.0f;\n"
         @"    if (simd_group_id == 0) {\n"
         @"        final_s  = simd_lane_id < (ALJABR_RMS_THREADS / 32) ? "
         @"partial_sum[simd_lane_id] : 0.0f;\n"
         @"        final_ss = simd_lane_id < (ALJABR_RMS_THREADS / 32) ? "
         @"partial_sq[simd_lane_id]  : 0.0f;\n"
         @"        final_s  = simd_sum(final_s);\n"
         @"        final_ss = simd_sum(final_ss);\n"
         @"        if (simd_lane_id == 0) {\n"
         @"            partial_sum[0] = final_s;\n"
         @"            partial_sq[0]  = final_ss;\n"
         @"        }\n"
         @"    }\n"
         @"    threadgroup_barrier(mem_flags::mem_threadgroup);\n"
         @"    float mean     = partial_sum[0] / float(N);\n"
         @"    float variance = (partial_sq[0] / float(N)) - (mean * mean);\n"
         @"    float inv      = rsqrt(max(variance, 0.0f) + eps);\n"
         @"    float4 mean4   = float4(mean);\n"
         @"    // Pass 2: normalise and scale with float4\n"
         @"    for (uint i = tid; i < N4; i += ALJABR_RMS_THREADS) {\n"
         @"        float4 w = weight ? weight4[i] : float4(1.0f);\n"
         @"        float4 b = bias   ? bias4[i]   : float4(0.0f);\n"
         @"        out4[i]  = (x4[i] - mean4) * inv * w + b;\n"
         @"    }\n"
         @"}\n"
         @"kernel void aljabr_softmax_kernel(\n"
         @"    device float* out [[buffer(0)]],\n"
         @"    device const float* x [[buffer(1)]],\n"
         @"    constant uint& N [[buffer(2)]],\n"
         @"    uint simd_lane_id [[thread_index_in_simdgroup]],\n"
         @"    uint simd_group_id [[simdgroup_index_in_threadgroup]],\n"
         @"    uint tid [[thread_position_in_threadgroup]]) {\n"
         @"    float max_val = -3.402823466e+38F;\n"
         @"    for (uint i = tid; i < N; i += ALJABR_RMS_THREADS) {\n"
         @"        max_val = max(max_val, x[i]);\n"
         @"    }\n"
         @"    float simd_max_val = simd_max(max_val);\n"
         @"    threadgroup float partial_max[32];\n"
         @"    if (simd_lane_id == 0) partial_max[simd_group_id] = "
         @"simd_max_val;\n"
         @"    threadgroup_barrier(mem_flags::mem_threadgroup);\n"
         @"    float final_max = -3.402823466e+38F;\n"
         @"    if (simd_group_id == 0) {\n"
         @"        final_max = simd_lane_id < (ALJABR_RMS_THREADS / 32) ? "
         @"partial_max[simd_lane_id] : -3.402823466e+38F;\n"
         @"        final_max = simd_max(final_max);\n"
         @"        if (simd_lane_id == 0) partial_max[0] = final_max;\n"
         @"    }\n"
         @"    threadgroup_barrier(mem_flags::mem_threadgroup);\n"
         @"    float m_val = partial_max[0];\n"
         @"    float s_val = 0.0f;\n"
         @"    for (uint i = tid; i < N; i += ALJABR_RMS_THREADS) {\n"
         @"        float e = exp(x[i] - m_val);\n"
         @"        out[i] = e;\n"
         @"        s_val += e;\n"
         @"    }\n"
         @"    float simd_s_val = simd_sum(s_val);\n"
         @"    threadgroup float partial_sum[32];\n"
         @"    if (simd_lane_id == 0) partial_sum[simd_group_id] = "
         @"simd_s_val;\n"
         @"    threadgroup_barrier(mem_flags::mem_threadgroup);\n"
         @"    float final_sum = 0.0f;\n"
         @"    if (simd_group_id == 0) {\n"
         @"        final_sum = simd_lane_id < (ALJABR_RMS_THREADS / 32) ? "
         @"partial_sum[simd_lane_id] : 0.0f;\n"
         @"        final_sum = simd_sum(final_sum);\n"
         @"        if (simd_lane_id == 0) partial_sum[0] = final_sum;\n"
         @"    }\n"
         @"    threadgroup_barrier(mem_flags::mem_threadgroup);\n"
         @"    float sum_val = partial_sum[0];\n"
         @"    for (uint i = tid; i < N; i += ALJABR_RMS_THREADS) {\n"
         @"        out[i] = out[i] / sum_val;\n"
         @"    }\n"
         @"}\n"
         @"kernel void aljabr_softmax_rows_kernel(\n"
         @"    device float* out [[buffer(0)]],\n"
         @"    device const float* x [[buffer(1)]],\n"
         @"    constant uint& N [[buffer(2)]],\n"
         @"    uint row [[threadgroup_position_in_grid]],\n"
         @"    uint simd_lane_id [[thread_index_in_simdgroup]],\n"
         @"    uint simd_group_id [[simdgroup_index_in_threadgroup]],\n"
         @"    uint tid [[thread_position_in_threadgroup]]) {\n"
         @"    device const float* rowX = x + (row * N);\n"
         @"    device float* rowOut = out + (row * N);\n"
         @"    float max_val = -3.402823466e+38F;\n"
         @"    for (uint i = tid; i < N; i += ALJABR_RMS_THREADS) {\n"
         @"        max_val = max(max_val, rowX[i]);\n"
         @"    }\n"
         @"    float simd_max_val = simd_max(max_val);\n"
         @"    threadgroup float partial_max[32];\n"
         @"    if (simd_lane_id == 0) partial_max[simd_group_id] = "
         @"simd_max_val;\n"
         @"    threadgroup_barrier(mem_flags::mem_threadgroup);\n"
         @"    float final_max = -3.402823466e+38F;\n"
         @"    if (simd_group_id == 0) {\n"
         @"        final_max = simd_lane_id < (ALJABR_RMS_THREADS / 32) ? "
         @"partial_max[simd_lane_id] : -3.402823466e+38F;\n"
         @"        final_max = simd_max(final_max);\n"
         @"        if (simd_lane_id == 0) partial_max[0] = final_max;\n"
         @"    }\n"
         @"    threadgroup_barrier(mem_flags::mem_threadgroup);\n"
         @"    float m_val = partial_max[0];\n"
         @"    float s_val = 0.0f;\n"
         @"    for (uint i = tid; i < N; i += ALJABR_RMS_THREADS) {\n"
         @"        float e = exp(rowX[i] - m_val);\n"
         @"        rowOut[i] = e;\n"
         @"        s_val += e;\n"
         @"    }\n"
         @"    float simd_s_val = simd_sum(s_val);\n"
         @"    threadgroup float partial_sum[32];\n"
         @"    if (simd_lane_id == 0) partial_sum[simd_group_id] = "
         @"simd_s_val;\n"
         @"    threadgroup_barrier(mem_flags::mem_threadgroup);\n"
         @"    float final_sum = 0.0f;\n"
         @"    if (simd_group_id == 0) {\n"
         @"        final_sum = simd_lane_id < (ALJABR_RMS_THREADS / 32) ? "
         @"partial_sum[simd_lane_id] : 0.0f;\n"
         @"        final_sum = simd_sum(final_sum);\n"
         @"        if (simd_lane_id == 0) partial_sum[0] = final_sum;\n"
         @"    }\n"
         @"    threadgroup_barrier(mem_flags::mem_threadgroup);\n"
         @"    float sum_val = partial_sum[0];\n"
         @"    for (uint i = tid; i < N; i += ALJABR_RMS_THREADS) {\n"
         @"        rowOut[i] = rowOut[i] / sum_val;\n"
         @"    }\n"
         @"}\n"
         @"kernel void aljabr_rmsnorm_rows_kernel(\n"
         @"    device float* out [[buffer(0)]],\n"
         @"    device const float* x [[buffer(1)]],\n"
         @"    device const float* weight [[buffer(2)]],\n"
         @"    constant uint& N [[buffer(3)]],\n"
         @"    constant float& eps [[buffer(4)]],\n"
         @"    constant uint& addOne [[buffer(5)]],\n"
         @"    uint row [[threadgroup_position_in_grid]],\n"
         @"    uint simd_lane_id [[thread_index_in_simdgroup]],\n"
         @"    uint simd_group_id [[simdgroup_index_in_threadgroup]],\n"
         @"    uint tid [[thread_position_in_threadgroup]]) {\n"
         @"    device const float* rowX = x + (row * N);\n"
         @"    device float* rowOut = out + (row * N);\n"
         @"    float ss = 0.0f;\n"
         @"    for (uint i = tid; i < N; i += ALJABR_RMS_THREADS) {\n"
         @"        float v = rowX[i];\n"
         @"        ss += v * v;\n"
         @"    }\n"
         @"    float simd_ss = simd_sum(ss);\n"
         @"    threadgroup float partial[32];\n"
         @"    if (simd_lane_id == 0) partial[simd_group_id] = simd_ss;\n"
         @"    threadgroup_barrier(mem_flags::mem_threadgroup);\n"
         @"    float final_ss = 0.0f;\n"
         @"    if (simd_group_id == 0) {\n"
         @"        final_ss = simd_lane_id < (ALJABR_RMS_THREADS / 32) ? "
         @"partial[simd_lane_id] : 0.0f;\n"
         @"        final_ss = simd_sum(final_ss);\n"
         @"        if (simd_lane_id == 0) partial[0] = final_ss;\n"
         @"    }\n"
         @"    threadgroup_barrier(mem_flags::mem_threadgroup);\n"
         @"    float inv = rsqrt((partial[0] / float(N)) + eps);\n"
         @"    for (uint i = tid; i < N; i += ALJABR_RMS_THREADS) {\n"
         @"        float w = weight[i] + (addOne != 0 ? 1.0f : 0.0f);\n"
         @"        rowOut[i] = rowX[i] * inv * w;\n"
         @"    }\n"
         @"}\n"
         @"kernel void aljabr_rmsnorm_unit_rows_kernel(\n"
         @"    device float* out [[buffer(0)]],\n"
         @"    device const float* x [[buffer(1)]],\n"
         @"    constant uint& N [[buffer(2)]],\n"
         @"    constant float& eps [[buffer(3)]],\n"
         @"    uint row [[threadgroup_position_in_grid]],\n"
         @"    uint simd_lane_id [[thread_index_in_simdgroup]],\n"
         @"    uint simd_group_id [[simdgroup_index_in_threadgroup]],\n"
         @"    uint tid [[thread_position_in_threadgroup]]) {\n"
         @"    device const float* rowX = x + (row * N);\n"
         @"    device float* rowOut = out + (row * N);\n"
         @"    float ss = 0.0f;\n"
         @"    for (uint i = tid; i < N; i += ALJABR_RMS_THREADS) {\n"
         @"        float v = rowX[i];\n"
         @"        ss += v * v;\n"
         @"    }\n"
         @"    float simd_ss = simd_sum(ss);\n"
         @"    threadgroup float partial[32];\n"
         @"    if (simd_lane_id == 0) partial[simd_group_id] = simd_ss;\n"
         @"    threadgroup_barrier(mem_flags::mem_threadgroup);\n"
         @"    float final_ss = 0.0f;\n"
         @"    if (simd_group_id == 0) {\n"
         @"        final_ss = simd_lane_id < (ALJABR_RMS_THREADS / 32) ? partial[simd_lane_id] : 0.0f;\n"
         @"        final_ss = simd_sum(final_ss);\n"
         @"        if (simd_lane_id == 0) partial[0] = final_ss;\n"
         @"    }\n"
         @"    threadgroup_barrier(mem_flags::mem_threadgroup);\n"
         @"    float inv = rsqrt((partial[0] / float(N)) + eps);\n"
         @"    for (uint i = tid; i < N; i += ALJABR_RMS_THREADS) {\n"
         @"        rowOut[i] = rowX[i] * inv;\n"
         @"    }\n"
         @"}\n"
         @"kernel void aljabr_layernorm_rows_kernel(\n"
         @"    device float* out [[buffer(0)]],\n"
         @"    device const float* x [[buffer(1)]],\n"
         @"    device const float* weight [[buffer(2)]],\n"
         @"    device const float* bias [[buffer(3)]],\n"
         @"    constant uint& N [[buffer(4)]],\n"
         @"    constant float& eps [[buffer(5)]],\n"
         @"    uint row [[threadgroup_position_in_grid]],\n"
         @"    uint simd_lane_id [[thread_index_in_simdgroup]],\n"
         @"    uint simd_group_id [[simdgroup_index_in_threadgroup]],\n"
         @"    uint tid [[thread_position_in_threadgroup]]) {\n"
         @"    device const float* rowX = x + (row * N);\n"
         @"    device float* rowOut = out + (row * N);\n"
         @"    float s = 0.0f;\n"
         @"    float ss = 0.0f;\n"
         @"    for (uint i = tid; i < N; i += ALJABR_RMS_THREADS) {\n"
         @"        float v = rowX[i];\n"
         @"        s += v;\n"
         @"        ss += v * v;\n"
         @"    }\n"
         @"    float simd_s = simd_sum(s);\n"
         @"    float simd_ss = simd_sum(ss);\n"
         @"    threadgroup float partial_sum[32];\n"
         @"    threadgroup float partial_sq[32];\n"
         @"    if (simd_lane_id == 0) {\n"
         @"        partial_sum[simd_group_id] = simd_s;\n"
         @"        partial_sq[simd_group_id] = simd_ss;\n"
         @"    }\n"
         @"    threadgroup_barrier(mem_flags::mem_threadgroup);\n"
         @"    float final_s = 0.0f;\n"
         @"    float final_ss = 0.0f;\n"
         @"    if (simd_group_id == 0) {\n"
         @"        final_s = simd_lane_id < (ALJABR_RMS_THREADS / 32) ? "
         @"partial_sum[simd_lane_id] : 0.0f;\n"
         @"        final_ss = simd_lane_id < (ALJABR_RMS_THREADS / 32) ? "
         @"partial_sq[simd_lane_id] : 0.0f;\n"
         @"        final_s = simd_sum(final_s);\n"
         @"        final_ss = simd_sum(final_ss);\n"
         @"        if (simd_lane_id == 0) {\n"
         @"            partial_sum[0] = final_s;\n"
         @"            partial_sq[0] = final_ss;\n"
         @"        }\n"
         @"    }\n"
         @"    threadgroup_barrier(mem_flags::mem_threadgroup);\n"
         @"    float mean = partial_sum[0] / float(N);\n"
         @"    float variance = (partial_sq[0] / float(N)) - (mean * mean);\n"
         @"    float inv = rsqrt(max(variance, 0.0f) + eps);\n"
         @"    for (uint i = tid; i < N; i += ALJABR_RMS_THREADS) {\n"
         @"        float w = weight ? weight[i] : 1.0f;\n"
         @"        float b = bias ? bias[i] : 0.0f;\n"
         @"        rowOut[i] = (rowX[i] - mean) * inv * w + b;\n"
         @"    }\n"
         @"}\n"
         @"kernel void aljabr_matvec_tb_half_kernel(\n"
         @"    device float* C [[buffer(0)]],\n"
         @"    device const float* A [[buffer(1)]],\n"
         @"    device const half* B [[buffer(2)]],\n"
         @"    constant uint& K [[buffer(3)]],\n"
         @"    constant uint& N [[buffer(4)]],\n"
         @"    uint gid [[threadgroup_position_in_grid]],\n"
         @"    uint tid [[thread_position_in_threadgroup]]) {\n"
         @"    if (gid >= N) return;\n"
         @"    uint base = gid * K;\n"
         @"    float sum = 0.0f;\n"
         @"    for (uint k = tid; k < K; k += ALJABR_MATVEC_THREADS) {\n"
         @"        sum += A[k] * float(B[base + k]);\n"
         @"    }\n"
         @"    threadgroup float partial[ALJABR_MATVEC_THREADS];\n"
         @"    partial[tid] = sum;\n"
         @"    threadgroup_barrier(mem_flags::mem_threadgroup);\n"
         @"    for (uint stride = ALJABR_MATVEC_THREADS >> 1; stride > 0; "
         @"stride >>= 1) {\n"
         @"        if (tid < stride) partial[tid] += partial[tid + stride];\n"
         @"        threadgroup_barrier(mem_flags::mem_threadgroup);\n"
         @"    }\n"
         @"    if (tid == 0) C[gid] = partial[0];\n"
         @"}\n"
         @"kernel void aljabr_matvec_tb_half_pair_kernel(\n"
         @"    device float* C0 [[buffer(0)]],\n"
         @"    device float* C1 [[buffer(1)]],\n"
         @"    device const float* A [[buffer(2)]],\n"
         @"    device const half* B0 [[buffer(3)]],\n"
         @"    device const half* B1 [[buffer(4)]],\n"
         @"    constant uint& K [[buffer(5)]],\n"
         @"    constant uint& N [[buffer(6)]],\n"
         @"    uint gid [[threadgroup_position_in_grid]],\n"
         @"    uint tid [[thread_position_in_threadgroup]]) {\n"
         @"    if (gid >= N) return;\n"
         @"    uint base = gid * K;\n"
         @"    float sum0 = 0.0f;\n"
         @"    float sum1 = 0.0f;\n"
         @"    for (uint k = tid; k < K; k += ALJABR_MATVEC_THREADS) {\n"
         @"        float av = A[k];\n"
         @"        sum0 += av * float(B0[base + k]);\n"
         @"        sum1 += av * float(B1[base + k]);\n"
         @"    }\n"
         @"    threadgroup float partial0[ALJABR_MATVEC_THREADS];\n"
         @"    threadgroup float partial1[ALJABR_MATVEC_THREADS];\n"
         @"    partial0[tid] = sum0;\n"
         @"    partial1[tid] = sum1;\n"
         @"    threadgroup_barrier(mem_flags::mem_threadgroup);\n"
         @"    for (uint stride = ALJABR_MATVEC_THREADS >> 1; stride > 0; "
         @"stride >>= 1) {\n"
         @"        if (tid < stride) {\n"
         @"            partial0[tid] += partial0[tid + stride];\n"
         @"            partial1[tid] += partial1[tid + stride];\n"
         @"        }\n"
         @"        threadgroup_barrier(mem_flags::mem_threadgroup);\n"
         @"    }\n"
         @"    if (tid == 0) {\n"
         @"        C0[gid] = partial0[0];\n"
         @"        C1[gid] = partial1[0];\n"
         @"    }\n"
         @"}\n"
         @"kernel void aljabr_matvec_tb_half_gated_pair_kernel(\n"
         @"    device float* C [[buffer(0)]],\n"
         @"    device const float* A [[buffer(1)]],\n"
         @"    device const half* gateW [[buffer(2)]],\n"
         @"    device const half* upW [[buffer(3)]],\n"
         @"    constant uint& K [[buffer(4)]],\n"
         @"    constant uint& N [[buffer(5)]],\n"
         @"    constant uint& activationKind [[buffer(6)]],\n"
         @"    uint gid [[threadgroup_position_in_grid]],\n"
         @"    uint tid [[thread_position_in_threadgroup]]) {\n"
         @"    if (gid >= N) return;\n"
         @"    uint base = gid * K;\n"
         @"    float gate = 0.0f;\n"
         @"    float up = 0.0f;\n"
         @"    for (uint k = tid; k < K; k += ALJABR_MATVEC_THREADS) {\n"
         @"        float av = A[k];\n"
         @"        gate += av * float(gateW[base + k]);\n"
         @"        up += av * float(upW[base + k]);\n"
         @"    }\n"
         @"    threadgroup float partialGate[ALJABR_MATVEC_THREADS];\n"
         @"    threadgroup float partialUp[ALJABR_MATVEC_THREADS];\n"
         @"    partialGate[tid] = gate;\n"
         @"    partialUp[tid] = up;\n"
         @"    threadgroup_barrier(mem_flags::mem_threadgroup);\n"
         @"    for (uint stride = ALJABR_MATVEC_THREADS >> 1; stride > 0; "
         @"stride >>= 1) {\n"
         @"        if (tid < stride) {\n"
         @"            partialGate[tid] += partialGate[tid + stride];\n"
         @"            partialUp[tid] += partialUp[tid + stride];\n"
         @"        }\n"
         @"        threadgroup_barrier(mem_flags::mem_threadgroup);\n"
         @"    }\n"
         @"    if (tid == 0) C[gid] = "
         @"aljabr_gated_activation(partialGate[0], partialUp[0], "
         @"activationKind);\n"
         @"}\n"
         @"kernel void aljabr_matvec_tb_half_triple_mixed_kernel(\n"
         @"    device float* C0 [[buffer(0)]],\n"
         @"    device float* C1 [[buffer(1)]],\n"
         @"    device float* C2 [[buffer(2)]],\n"
         @"    device const float* A [[buffer(3)]],\n"
         @"    device const half* B0 [[buffer(4)]],\n"
         @"    device const half* B1 [[buffer(5)]],\n"
         @"    device const half* B2 [[buffer(6)]],\n"
         @"    constant uint& K [[buffer(7)]],\n"
         @"    constant uint& N0 [[buffer(8)]],\n"
         @"    constant uint& N1 [[buffer(9)]],\n"
         @"    constant uint& N2 [[buffer(10)]],\n"
         @"    uint gid [[threadgroup_position_in_grid]],\n"
         @"    uint tid [[thread_position_in_threadgroup]]) {\n"
         @"    uint total = N0 + N1 + N2;\n"
         @"    if (gid >= total) return;\n"
         @"    device const half* B = B0;\n"
         @"    device float* C = C0;\n"
         @"    uint local = gid;\n"
         @"    if (gid >= N0 + N1) {\n"
         @"        B = B2;\n"
         @"        C = C2;\n"
         @"        local = gid - N0 - N1;\n"
         @"    } else if (gid >= N0) {\n"
         @"        B = B1;\n"
         @"        C = C1;\n"
         @"        local = gid - N0;\n"
         @"    }\n"
         @"    uint base = local * K;\n"
         @"    float sum = 0.0f;\n"
         @"    for (uint k = tid; k < K; k += ALJABR_MATVEC_THREADS) {\n"
         @"        sum += A[k] * float(B[base + k]);\n"
         @"    }\n"
         @"    threadgroup float partial[ALJABR_MATVEC_THREADS];\n"
         @"    partial[tid] = sum;\n"
         @"    threadgroup_barrier(mem_flags::mem_threadgroup);\n"
         @"    for (uint stride = ALJABR_MATVEC_THREADS >> 1; stride > 0; "
         @"stride >>= 1) {\n"
         @"        if (tid < stride) partial[tid] += partial[tid + stride];\n"
         @"        threadgroup_barrier(mem_flags::mem_threadgroup);\n"
         @"    }\n"
         @"    if (tid == 0) C[local] = partial[0];\n"
         @"}\n"
         @"kernel void aljabr_decode_attention_kernel(\n"
         @"    device float* out [[buffer(0)]],\n"
         @"    device const float* Q [[buffer(1)]],\n"
         @"    device const float* K_cache [[buffer(2)]],\n"
         @"    device const float* V_cache [[buffer(3)]],\n"
         @"    device const int* block_table [[buffer(4)]],\n"
         @"    device const int* context_lens [[buffer(5)]],\n"
         @"    constant uint& H [[buffer(6)]],\n"
         @"    constant uint& H_kv [[buffer(7)]],\n"
         @"    constant uint& D [[buffer(8)]],\n"
         @"    constant uint& block_size [[buffer(9)]],\n"
         @"    constant uint& max_blocks [[buffer(10)]],\n"
         @"    constant float& scale [[buffer(11)]],\n"
         @"    constant uint& is_causal [[buffer(12)]],\n"
         @"    constant int& query_start_pos [[buffer(13)]],\n"
         @"    constant int& sliding_window [[buffer(14)]],\n"
         @"    constant float& soft_cap [[buffer(15)]],\n"
         @"    uint group [[threadgroup_position_in_grid]],\n"
         @"    uint tid [[thread_position_in_threadgroup]]) {\n"
         @"    threadgroup float scores[4096];\n"
         @"    threadgroup float partial[256];\n"
         @"    uint b = group / H;\n"
         @"    uint h = group - b * H;\n"
         @"    int ctx_len = context_lens[b];\n"
         @"    if (ctx_len <= 0 || H_kv == 0 || D == 0) return;\n"
         @"    uint gqa_group = max(1u, H / H_kv);\n"
         @"    uint kv_h = min(H_kv - 1u, h / gqa_group);\n"
         @"    int abs_query_pos = query_start_pos;\n"
         @"    if (is_causal != 0 && sliding_window <= 0 && query_start_pos == "
         @"0) abs_query_pos = ctx_len - 1;\n"
         @"    int max_pos = (is_causal != 0) ? abs_query_pos : (ctx_len - "
         @"1);\n"
         @"    if (max_pos >= ctx_len) max_pos = ctx_len - 1;\n"
         @"    int min_pos = sliding_window > 0 ? (abs_query_pos - "
         @"sliding_window + 1) : 0;\n"
         @"    if (min_pos < 0) min_pos = 0;\n"
         @"    uint valid = max_pos >= min_pos ? uint(max_pos - min_pos + 1) : "
         @"0u;\n"
         @"    if (valid == 0u || valid > 4096u) {\n"
         @"        for (uint d = tid; d < D; d += 256u) out[(b * H + h) * D + "
         @"d] = 0.0f;\n"
         @"        return;\n"
         @"    }\n"
         @"    device const float* qh = Q + (b * H + h) * D;\n"
         @"    float local_max = -3.402823466e+38F;\n"
         @"    for (uint idx = tid; idx < valid; idx += 256u) {\n"
         @"        uint pos = uint(min_pos) + idx;\n"
         @"        uint logical_block = pos / block_size;\n"
         @"        uint block_offset = pos - logical_block * block_size;\n"
         @"        int phys_i = block_table[b * max_blocks + logical_block];\n"
         @"        uint phys = uint(max(phys_i, 0));\n"
         @"        device const float* kh = K_cache + (((phys * H_kv + kv_h) * "
         @"block_size + block_offset) * D);\n"
         @"        float dot = 0.0f;\n"
         @"        for (uint d = 0u; d < D; d++) dot += qh[d] * kh[d];\n"
         @"        float score = dot * scale;\n"
         @"        if (soft_cap > 0.0f) score = soft_cap * tanh(score / "
         @"soft_cap);\n"
         @"        scores[idx] = score;\n"
         @"        local_max = max(local_max, score);\n"
         @"    }\n"
         @"    partial[tid] = local_max;\n"
         @"    threadgroup_barrier(mem_flags::mem_threadgroup);\n"
         @"    for (uint stride = 128u; stride > 0u; stride >>= 1u) {\n"
         @"        if (tid < stride) partial[tid] = max(partial[tid], "
         @"partial[tid + stride]);\n"
         @"        threadgroup_barrier(mem_flags::mem_threadgroup);\n"
         @"    }\n"
         @"    float mx = partial[0];\n"
         @"    float local_sum = 0.0f;\n"
         @"    for (uint idx = tid; idx < valid; idx += 256u) {\n"
         @"        float w = exp(scores[idx] - mx);\n"
         @"        scores[idx] = w;\n"
         @"        local_sum += w;\n"
         @"    }\n"
         @"    partial[tid] = local_sum;\n"
         @"    threadgroup_barrier(mem_flags::mem_threadgroup);\n"
         @"    for (uint stride = 128u; stride > 0u; stride >>= 1u) {\n"
         @"        if (tid < stride) partial[tid] += partial[tid + stride];\n"
         @"        threadgroup_barrier(mem_flags::mem_threadgroup);\n"
         @"    }\n"
         @"    float inv_sum = 1.0f / (partial[0] + 1.0e-9f);\n"
         @"    threadgroup_barrier(mem_flags::mem_threadgroup);\n"
         @"    for (uint d = tid; d < D; d += 256u) {\n"
         @"        float acc = 0.0f;\n"
         @"        for (uint idx = 0u; idx < valid; idx++) {\n"
         @"            uint pos = uint(min_pos) + idx;\n"
         @"            uint logical_block = pos / block_size;\n"
         @"            uint block_offset = pos - logical_block * block_size;\n"
         @"            int phys_i = block_table[b * max_blocks + "
         @"logical_block];\n"
         @"            uint phys = uint(max(phys_i, 0));\n"
         @"            device const float* vh = V_cache + (((phys * H_kv + "
         @"kv_h) * block_size + block_offset) * D);\n"
         @"            acc += (scores[idx] * inv_sum) * vh[d];\n"
         @"        }\n"
         @"        out[(b * H + h) * D + d] = acc;\n"
         @"    }\n"
         @"}\n"
         @"kernel void aljabr_rope_single_token_kernel(\n"
         @"    device float* x [[buffer(0)]],\n"
         @"    constant uint& nHeads [[buffer(1)]],\n"
         @"    constant uint& headDim [[buffer(2)]],\n"
         @"    constant uint& pos [[buffer(3)]],\n"
         @"    constant float& freqBase [[buffer(4)]],\n"
         @"    uint gid [[thread_position_in_grid]]) {\n"
         @"    uint half_dim = headDim / 2;\n"
         @"    uint total_rotations = nHeads * half_dim;\n"
         @"    if (gid >= total_rotations) return;\n"
         @"    uint h = gid / half_dim;\n"
         @"    uint i = gid % half_dim;\n"
         @"    float freq = 1.0f / pow(freqBase, 2.0f * float(i) / float(headDim));\n"
         @"    float theta = float(pos) * freq;\n"
         @"    float cos_theta = cos(theta);\n"
         @"    float sin_theta = sin(theta);\n"
         @"    uint base = h * headDim;\n"
         @"    float x0 = x[base + i];\n"
         @"    float x1 = x[base + i + half_dim];\n"
         @"    x[base + i]            = x0 * cos_theta - x1 * sin_theta;\n"
         @"    x[base + i + half_dim] = x0 * sin_theta + x1 * cos_theta;\n"
         @"}\n"
         @"kernel void aljabr_rope_single_token_freqfact_kernel(\n"
         @"    device float* x [[buffer(0)]],\n"
         @"    constant uint& nHeads [[buffer(1)]],\n"
         @"    constant uint& headDim [[buffer(2)]],\n"
         @"    constant uint& pos [[buffer(3)]],\n"
         @"    constant float& freqBase [[buffer(4)]],\n"
         @"    device const float* freqFactors [[buffer(5)]],\n"
         @"    uint gid [[thread_position_in_grid]]) {\n"
         @"    uint half_dim = headDim / 2;\n"
         @"    uint total_rotations = nHeads * half_dim;\n"
         @"    if (gid >= total_rotations) return;\n"
         @"    uint h = gid / half_dim;\n"
         @"    uint i = gid % half_dim;\n"
         @"    float freq = 1.0f / pow(freqBase, 2.0f * float(i) / float(headDim));\n"
         @"    float ff = freqFactors[i];\n"
         @"    float theta = float(pos) * freq / (ff > 0.0f ? ff : 1.0f);\n"
         @"    float cos_theta = cos(theta);\n"
         @"    float sin_theta = sin(theta);\n"
         @"    uint base = h * headDim;\n"
         @"    float x0 = x[base + i];\n"
         @"    float x1 = x[base + i + half_dim];\n"
         @"    x[base + i]            = x0 * cos_theta - x1 * sin_theta;\n"
         @"    x[base + i + half_dim] = x0 * sin_theta + x1 * cos_theta;\n"
         @"}\n"
         @"kernel void aljabr_kv_store_flat_kernel(\n"
         @"    device float* cache [[buffer(0)]],\n"
         @"    device const float* vec [[buffer(1)]],\n"
         @"    constant uint& pos [[buffer(2)]],\n"
         @"    constant uint& stride [[buffer(3)]],\n"
         @"    uint tid [[thread_position_in_grid]]) {\n"
         @"    if (tid >= stride) return;\n"
         @"    cache[(uint)pos * stride + tid] = vec[tid];\n"
         @"}\n"
         @"kernel void aljabr_sdpa_flat_kernel(\n"
         @"    device float* out [[buffer(0)]],\n"
         @"    device const float* Q [[buffer(1)]],\n"
         @"    device const float* K_cache [[buffer(2)]],\n"
         @"    device const float* V_cache [[buffer(3)]],\n"
         @"    constant uint& H [[buffer(4)]],\n"
         @"    constant uint& H_kv [[buffer(5)]],\n"
         @"    constant uint& D [[buffer(6)]],\n"
         @"    constant uint& stride [[buffer(7)]],\n"
         @"    constant uint& pos [[buffer(8)]],\n"
         @"    constant uint& start_pos [[buffer(9)]],\n"
         @"    constant float& scale [[buffer(10)]],\n"
         @"    constant float& soft_cap [[buffer(11)]],\n"
         @"    uint group [[threadgroup_position_in_grid]],\n"
         @"    uint tid [[thread_position_in_threadgroup]]) {\n"
         @"    threadgroup float scores[4096];\n"
         @"    threadgroup float partial[256];\n"
         @"    uint h = group;\n"
         @"    if (h >= H || H_kv == 0 || D == 0) return;\n"
         @"    uint gqa_group = max(1u, H / H_kv);\n"
         @"    uint kv_h = min(H_kv - 1u, h / gqa_group);\n"
         @"    uint seq_len = pos + 1u;\n"
         @"    if (start_pos >= seq_len) return;\n"
         @"    uint valid = seq_len - start_pos;\n"
         @"    if (valid == 0u || valid > 4096u) return;\n"
         @"    device const float* qh = Q + h * D;\n"
         @"    float local_max = -3.402823466e+38F;\n"
         @"    for (uint idx = tid; idx < valid; idx += 256u) {\n"
         @"        uint t = start_pos + idx;\n"
         @"        device const float* kh = K_cache + (t * stride + kv_h * D);\n"
         @"        float dot = 0.0f;\n"
         @"        for (uint d = 0u; d < D; d++) dot += qh[d] * kh[d];\n"
         @"        float s = dot * scale;\n"
         @"        if (soft_cap > 0.0f) s = soft_cap * precise::tanh(s / soft_cap);\n"
         @"        scores[idx] = s;\n"
         @"        local_max = max(local_max, s);\n"
         @"    }\n"
         @"    partial[tid] = local_max;\n"
         @"    threadgroup_barrier(mem_flags::mem_threadgroup);\n"
         @"    for (uint s = 128u; s > 0u; s >>= 1u) {\n"
         @"        if (tid < s) partial[tid] = max(partial[tid], partial[tid + s]);\n"
         @"        threadgroup_barrier(mem_flags::mem_threadgroup);\n"
         @"    }\n"
         @"    float mx = partial[0];\n"
         @"    float local_sum = 0.0f;\n"
         @"    for (uint idx = tid; idx < valid; idx += 256u) {\n"
         @"        float w = exp(scores[idx] - mx);\n"
         @"        scores[idx] = w;\n"
         @"        local_sum += w;\n"
         @"    }\n"
         @"    partial[tid] = local_sum;\n"
         @"    threadgroup_barrier(mem_flags::mem_threadgroup);\n"
         @"    for (uint s = 128u; s > 0u; s >>= 1u) {\n"
         @"        if (tid < s) partial[tid] += partial[tid + s];\n"
         @"        threadgroup_barrier(mem_flags::mem_threadgroup);\n"
         @"    }\n"
         @"    float inv_sum = 1.0f / (partial[0] + 1.0e-9f);\n"
         @"    threadgroup_barrier(mem_flags::mem_threadgroup);\n"
         @"    for (uint d = tid; d < D; d += 256u) {\n"
         @"        float acc = 0.0f;\n"
         @"        for (uint idx = 0u; idx < valid; idx++) {\n"
         @"            uint t = start_pos + idx;\n"
         @"            device const float* vh = V_cache + (t * stride + kv_h * D);\n"
         @"            acc += (scores[idx] * inv_sum) * vh[d];\n"
         @"        }\n"
         @"        out[h * D + d] = acc;\n"
         @"    }\n"
         @"}\n"
         @"kernel void aljabr_matvec_t_half_kernel(\n"
         @"    device float* C [[buffer(0)]],\n"
         @"    device const float* A [[buffer(1)]],\n"
         @"    device const half* B [[buffer(2)]],\n"
         @"    constant uint& K [[buffer(3)]],\n"
         @"    constant uint& N [[buffer(4)]],\n"
         @"    uint gid [[threadgroup_position_in_grid]],\n"
         @"    uint tid [[thread_position_in_threadgroup]]) {\n"
         @"    if (gid >= N) return;\n"
         @"    float sum = 0.0f;\n"
         @"    for (uint k = tid; k < K; k += ALJABR_MATVEC_THREADS) {\n"
         @"        sum += A[k] * float(B[k * N + gid]);\n"
         @"    }\n"
         @"    threadgroup float partial[ALJABR_MATVEC_THREADS];\n"
         @"    partial[tid] = sum;\n"
         @"    threadgroup_barrier(mem_flags::mem_threadgroup);\n"
         @"    for (uint stride = ALJABR_MATVEC_THREADS >> 1; stride > 0; "
         @"stride >>= 1) {\n"
         @"        if (tid < stride) partial[tid] += partial[tid + stride];\n"
         @"        threadgroup_barrier(mem_flags::mem_threadgroup);\n"
         @"    }\n"
         @"    if (tid == 0) C[gid] = partial[0];\n"
         @"}\n"
         @"// "
         @"--------------------------------------------------------------------"
         @"---------\n"
         @"// FlashAttention Kernel (Basic implementation for Apple Silicon / "
         @"M-Series)\n"
         @"// "
         @"--------------------------------------------------------------------"
         @"---------\n"
         @"#define FA_Bc 32\n"
         @"#define FA_Br 32\n"
         @"\n"
         @"kernel void aljabr_flash_attention_kernel(\n"
         @"    device float* out [[buffer(0)]],\n"
         @"    device const float* q [[buffer(1)]],\n"
         @"    device const float* k [[buffer(2)]],\n"
         @"    device const float* v [[buffer(3)]],\n"
         @"    constant uint& seq_len [[buffer(4)]],\n"
         @"    constant uint& head_dim [[buffer(5)]],\n"
         @"    uint3 group_id [[threadgroup_position_in_grid]], \n"
         @"    uint3 thread_id [[thread_position_in_threadgroup]]) {\n"
         @"    \n"
         @"    uint q_block_idx = group_id.x;\n"
         @"    uint head_idx = group_id.y;\n"
         @"    uint batch_idx = group_id.z;\n"
         @"    \n"
         @"    uint tid = thread_id.x;\n"
         @"    \n"
         @"    uint q_idx = q_block_idx * FA_Br + tid;\n"
         @"    bool valid_q = q_idx < seq_len;\n"
         @"    \n"
         @"    uint head_offset = head_idx * head_dim;\n"
         @"    \n"
         @"    threadgroup float S[FA_Br][FA_Bc];\n"
         @"    \n"
         @"    float m_i = -INFINITY;\n"
         @"    float l_i = 0.0f;\n"
         @"    \n"
         @"    float O_i[128]; // max head_dim 128\n"
         @"    for(uint d=0; d<head_dim; d++) O_i[d] = 0.0f;\n"
         @"    \n"
         @"    float q_i[128];\n"
         @"    if (valid_q) {\n"
         @"        for(uint d=0; d<head_dim; d++) q_i[d] = q[q_idx * head_dim "
         @"+ head_offset + d];\n"
         @"    }\n"
         @"    \n"
         @"    float scale = 1.0f / sqrt((float)head_dim);\n"
         @"    uint num_k_blocks = (seq_len + FA_Bc - 1) / FA_Bc;\n"
         @"    \n"
         @"    for (uint k_block = 0; k_block < num_k_blocks; k_block++) {\n"
         @"        uint k_idx_base = k_block * FA_Bc;\n"
         @"        \n"
         @"        // Compute S = Q K^T\n"
         @"        for (uint j = 0; j < FA_Bc; j++) {\n"
         @"            uint k_idx = k_idx_base + j;\n"
         @"            float score = 0.0f;\n"
         @"            if (valid_q && k_idx < seq_len) {\n"
         @"                for (uint d=0; d<head_dim; d++) {\n"
         @"                    score += q_i[d] * k[k_idx * head_dim + "
         @"head_offset + d];\n"
         @"                }\n"
         @"                score *= scale;\n"
         @"            } else {\n"
         @"                score = -INFINITY;\n"
         @"            }\n"
         @"            S[tid][j] = score;\n"
         @"        }\n"
         @"        \n"
         @"        // Row max\n"
         @"        float m_ij = -INFINITY;\n"
         @"        for (uint j = 0; j < FA_Bc; j++) {\n"
         @"            m_ij = max(m_ij, S[tid][j]);\n"
         @"        }\n"
         @"        \n"
         @"        float m_new = max(m_i, m_ij);\n"
         @"        float exp_m_diff = exp(m_i - m_new);\n"
         @"        \n"
         @"        float l_ij = 0.0f;\n"
         @"        for (uint j = 0; j < FA_Bc; j++) {\n"
         @"            float p = exp(S[tid][j] - m_new);\n"
         @"            S[tid][j] = p;\n"
         @"            l_ij += p;\n"
         @"        }\n"
         @"        \n"
         @"        float l_new = exp_m_diff * l_i + l_ij;\n"
         @"        \n"
         @"        // Update O\n"
         @"        for (uint d = 0; d < head_dim; d++) {\n"
         @"            float pv = 0.0f;\n"
         @"            for (uint j = 0; j < FA_Bc; j++) {\n"
         @"                uint k_idx = k_idx_base + j;\n"
         @"                if (k_idx < seq_len) {\n"
         @"                    pv += S[tid][j] * v[k_idx * head_dim + "
         @"head_offset + d];\n"
         @"                }\n"
         @"            }\n"
         @"            O_i[d] = exp_m_diff * O_i[d] + pv;\n"
         @"        }\n"
         @"        \n"
         @"        m_i = m_new;\n"
         @"        l_i = l_new;\n"
         @"    }\n"
         @"    \n"
         @"    // Write out\n"
         @"    if (valid_q) {\n"
         @"        for (uint d = 0; d < head_dim; d++) {\n"
         @"            out[q_idx * head_dim + head_offset + d] = O_i[d] / "
         @"l_i;\n"
         @"        }\n"
         @"    }\n"
         @"}\n"
         @"\n";
}

NSString *aljabr_metal_matvec_kernel_source(NSUInteger threads) {
  NSString *base = [NSString
      stringWithFormat:
          @"#include <metal_stdlib>\n"
          @"using namespace metal;\n"
          @"constant uint ALJABR_MATVEC_THREADS = %lu;\n"
          @"static inline float aljabr_bf16_to_float(ushort v) {\n"
          @"    return as_type<float>(uint(v) << 16);\n"
          @"}\n"
          @"static inline float aljabr_silu_gate(float g) {\n"
          @"    if (g <= -20.0f) return 0.0f;\n"
          @"    if (g >= 20.0f) return g;\n"
          @"    return g / (1.0f + exp(-g));\n"
          @"}\n"
          @"static inline float aljabr_gelu_gate(float g) {\n"
          @"    if (g <= -10.0f) return 0.0f;\n"
          @"    if (g >= 10.0f) return g;\n"
          @"    float inner = 0.79788456f * (g + 0.044715f * g * g * g);\n"
          @"    return 0.5f * g * (1.0f + tanh(inner));\n"
          @"}\n"
          @"static inline float aljabr_gated_activation(float gate, float "
          @"up, uint activation_kind) {\n"
          @"    float act = activation_kind == 1u ? "
          @"aljabr_silu_gate(gate) : aljabr_gelu_gate(gate);\n"
          @"    float y = act * up;\n"
          @"    return isfinite(y) ? y : 0.0f;\n"
          @"}\n"
          @"kernel void aljabr_matvec_tb_half_kernel(\n"
          @"    device float* C [[buffer(0)]],\n"
          @"    device const float* A [[buffer(1)]],\n"
          @"    device const half* B [[buffer(2)]],\n"
          @"    constant uint& K [[buffer(3)]],\n"
          @"    constant uint& N [[buffer(4)]],\n"
          @"    uint gid [[threadgroup_position_in_grid]],\n"
          @"    uint tid [[thread_position_in_threadgroup]]) {\n"
          @"    if (gid >= N) return;\n"
          @"    uint base = gid * K;\n"
          @"    float sum = 0.0f;\n"
          @"    for (uint k = tid; k < K; k += ALJABR_MATVEC_THREADS) {\n"
          @"        sum += A[k] * float(B[base + k]);\n"
          @"    }\n"
          @"    threadgroup float partial[ALJABR_MATVEC_THREADS];\n"
          @"    partial[tid] = sum;\n"
          @"    threadgroup_barrier(mem_flags::mem_threadgroup);\n"
          @"    for (uint stride = ALJABR_MATVEC_THREADS >> 1; stride > "
          @"0; stride >>= 1) {\n"
          @"        if (tid < stride) partial[tid] += partial[tid + stride];\n"
          @"        threadgroup_barrier(mem_flags::mem_threadgroup);\n"
          @"    }\n"
          @"    if (tid == 0) C[gid] = partial[0];\n"
          @"}\n"
          @"kernel void aljabr_matvec_tb_half_pair_kernel(\n"
          @"    device float* C0 [[buffer(0)]],\n"
          @"    device float* C1 [[buffer(1)]],\n"
          @"    device const float* A [[buffer(2)]],\n"
          @"    device const half* B0 [[buffer(3)]],\n"
          @"    device const half* B1 [[buffer(4)]],\n"
          @"    constant uint& K [[buffer(5)]],\n"
          @"    constant uint& N [[buffer(6)]],\n"
          @"    uint gid [[threadgroup_position_in_grid]],\n"
          @"    uint tid [[thread_position_in_threadgroup]]) {\n"
          @"    if (gid >= N) return;\n"
          @"    uint base = gid * K;\n"
          @"    float sum0 = 0.0f;\n"
          @"    float sum1 = 0.0f;\n"
          @"    for (uint k = tid; k < K; k += ALJABR_MATVEC_THREADS) {\n"
          @"        float av = A[k];\n"
          @"        sum0 += av * float(B0[base + k]);\n"
          @"        sum1 += av * float(B1[base + k]);\n"
          @"    }\n"
          @"    threadgroup float partial0[ALJABR_MATVEC_THREADS];\n"
          @"    threadgroup float partial1[ALJABR_MATVEC_THREADS];\n"
          @"    partial0[tid] = sum0;\n"
          @"    partial1[tid] = sum1;\n"
          @"    threadgroup_barrier(mem_flags::mem_threadgroup);\n"
          @"    for (uint stride = ALJABR_MATVEC_THREADS >> 1; stride > "
          @"0; stride >>= 1) {\n"
          @"        if (tid < stride) {\n"
          @"            partial0[tid] += partial0[tid + stride];\n"
          @"            partial1[tid] += partial1[tid + stride];\n"
          @"        }\n"
          @"        threadgroup_barrier(mem_flags::mem_threadgroup);\n"
          @"    }\n"
          @"    if (tid == 0) {\n"
          @"        C0[gid] = partial0[0];\n"
          @"        C1[gid] = partial1[0];\n"
          @"    }\n"
          @"}\n"
          @"kernel void aljabr_matvec_tb_half_gated_pair_kernel(\n"
          @"    device float* C [[buffer(0)]],\n"
          @"    device const float* A [[buffer(1)]],\n"
          @"    device const half* gateW [[buffer(2)]],\n"
          @"    device const half* upW [[buffer(3)]],\n"
          @"    constant uint& K [[buffer(4)]],\n"
          @"    constant uint& N [[buffer(5)]],\n"
          @"    constant uint& activationKind [[buffer(6)]],\n"
          @"    uint gid [[threadgroup_position_in_grid]],\n"
          @"    uint tid [[thread_position_in_threadgroup]]) {\n"
          @"    if (gid >= N) return;\n"
          @"    uint base = gid * K;\n"
          @"    float gate = 0.0f;\n"
          @"    float up = 0.0f;\n"
          @"    for (uint k = tid; k < K; k += ALJABR_MATVEC_THREADS) {\n"
          @"        float av = A[k];\n"
          @"        gate += av * float(gateW[base + k]);\n"
          @"        up += av * float(upW[base + k]);\n"
          @"    }\n"
          @"    threadgroup float partialGate[ALJABR_MATVEC_THREADS];\n"
          @"    threadgroup float partialUp[ALJABR_MATVEC_THREADS];\n"
          @"    partialGate[tid] = gate;\n"
          @"    partialUp[tid] = up;\n"
          @"    threadgroup_barrier(mem_flags::mem_threadgroup);\n"
          @"    for (uint stride = ALJABR_MATVEC_THREADS >> 1; stride > "
          @"0; stride >>= 1) {\n"
          @"        if (tid < stride) {\n"
          @"            partialGate[tid] += partialGate[tid + stride];\n"
          @"            partialUp[tid] += partialUp[tid + stride];\n"
          @"        }\n"
          @"        threadgroup_barrier(mem_flags::mem_threadgroup);\n"
          @"    }\n"
          @"    if (tid == 0) C[gid] = "
          @"aljabr_gated_activation(partialGate[0], partialUp[0], "
          @"activationKind);\n"
          @"}\n"
          @"kernel void aljabr_matvec_tb_half_triple_mixed_kernel(\n"
          @"    device float* C0 [[buffer(0)]],\n"
          @"    device float* C1 [[buffer(1)]],\n"
          @"    device float* C2 [[buffer(2)]],\n"
          @"    device const float* A [[buffer(3)]],\n"
          @"    device const half* B0 [[buffer(4)]],\n"
          @"    device const half* B1 [[buffer(5)]],\n"
          @"    device const half* B2 [[buffer(6)]],\n"
          @"    constant uint& K [[buffer(7)]],\n"
          @"    constant uint& N0 [[buffer(8)]],\n"
          @"    constant uint& N1 [[buffer(9)]],\n"
          @"    constant uint& N2 [[buffer(10)]],\n"
          @"    uint gid [[threadgroup_position_in_grid]],\n"
          @"    uint tid [[thread_position_in_threadgroup]]) {\n"
          @"    uint total = N0 + N1 + N2;\n"
          @"    if (gid >= total) return;\n"
          @"    device const half* B = B0;\n"
          @"    device float* C = C0;\n"
          @"    uint local = gid;\n"
          @"    if (gid >= N0 + N1) {\n"
          @"        B = B2;\n"
          @"        C = C2;\n"
          @"        local = gid - N0 - N1;\n"
          @"    } else if (gid >= N0) {\n"
          @"        B = B1;\n"
          @"        C = C1;\n"
          @"        local = gid - N0;\n"
          @"    }\n"
          @"    uint base = local * K;\n"
          @"    float sum = 0.0f;\n"
          @"    for (uint k = tid; k < K; k += ALJABR_MATVEC_THREADS) {\n"
          @"        sum += A[k] * float(B[base + k]);\n"
          @"    }\n"
          @"    threadgroup float partial[ALJABR_MATVEC_THREADS];\n"
          @"    partial[tid] = sum;\n"
          @"    threadgroup_barrier(mem_flags::mem_threadgroup);\n"
          @"    for (uint stride = ALJABR_MATVEC_THREADS >> 1; stride > "
          @"0; stride >>= 1) {\n"
          @"        if (tid < stride) partial[tid] += partial[tid + stride];\n"
          @"        threadgroup_barrier(mem_flags::mem_threadgroup);\n"
          @"    }\n"
          @"    if (tid == 0) C[local] = partial[0];\n"
          @"}\n"
          @"kernel void aljabr_matvec_tb_bf16_kernel(\n"
          @"    device float* C [[buffer(0)]],\n"
          @"    device const float* A [[buffer(1)]],\n"
          @"    device const ushort* B [[buffer(2)]],\n"
          @"    constant uint& K [[buffer(3)]],\n"
          @"    constant uint& N [[buffer(4)]],\n"
          @"    uint gid [[threadgroup_position_in_grid]],\n"
          @"    uint tid [[thread_position_in_threadgroup]]) {\n"
          @"    if (gid >= N) return;\n"
          @"    uint base = gid * K;\n"
          @"    float sum = 0.0f;\n"
          @"    for (uint k = tid; k < K; k += ALJABR_MATVEC_THREADS) {\n"
          @"        sum += A[k] * aljabr_bf16_to_float(B[base + k]);\n"
          @"    }\n"
          @"    threadgroup float partial[ALJABR_MATVEC_THREADS];\n"
          @"    partial[tid] = sum;\n"
          @"    threadgroup_barrier(mem_flags::mem_threadgroup);\n"
          @"    for (uint stride = ALJABR_MATVEC_THREADS >> 1; stride > "
          @"0; stride >>= 1) {\n"
          @"        if (tid < stride) partial[tid] += partial[tid + stride];\n"
          @"        threadgroup_barrier(mem_flags::mem_threadgroup);\n"
          @"    }\n"
          @"    if (tid == 0) C[gid] = partial[0];\n"
          @"}\n"
          @"kernel void aljabr_matvec_tb_bf16_x4_kernel(\n"
          @"    device float* C [[buffer(0)]],\n"
          @"    device const float* A [[buffer(1)]],\n"
          @"    device const ushort* B [[buffer(2)]],\n"
          @"    constant uint& K [[buffer(3)]],\n"
          @"    constant uint& N [[buffer(4)]],\n"
          @"    uint group [[threadgroup_position_in_grid]],\n"
          @"    uint tid [[thread_position_in_threadgroup]]) {\n"
          @"    uint row0 = group * 4u;\n"
          @"    uint row1 = row0 + 1u;\n"
          @"    uint row2 = row0 + 2u;\n"
          @"    uint row3 = row0 + 3u;\n"
          @"    if (row0 >= N) return;\n"
          @"    uint base0 = row0 * K;\n"
          @"    uint base1 = row1 * K;\n"
          @"    uint base2 = row2 * K;\n"
          @"    uint base3 = row3 * K;\n"
          @"    bool has1 = row1 < N;\n"
          @"    bool has2 = row2 < N;\n"
          @"    bool has3 = row3 < N;\n"
          @"    float sum0 = 0.0f;\n"
          @"    float sum1 = 0.0f;\n"
          @"    float sum2 = 0.0f;\n"
          @"    float sum3 = 0.0f;\n"
          @"    for (uint k = tid; k < K; k += ALJABR_MATVEC_THREADS) {\n"
          @"        float av = A[k];\n"
          @"        sum0 += av * aljabr_bf16_to_float(B[base0 + k]);\n"
