          @"        float vu0 = lane < groups ? pu0[lane] : 0.0f;\n"
          @"        float vu1 = lane < groups ? pu1[lane] : 0.0f;\n"
          @"        float vu2 = lane < groups ? pu2[lane] : 0.0f;\n"
          @"        float vu3 = lane < groups ? pu3[lane] : 0.0f;\n"
          @"        vg0 = simd_sum(vg0); vg1 = simd_sum(vg1); vg2 = "
          @"simd_sum(vg2); vg3 = simd_sum(vg3);\n"
          @"        vu0 = simd_sum(vu0); vu1 = simd_sum(vu1); vu2 = "
          @"simd_sum(vu2); vu3 = simd_sum(vu3);\n"
          @"        if (lane == 0u) {\n"
          @"            C0[row0] = vg0; C1[row0] = vu0;\n"
          @"            if (has1) { C0[row1] = vg1; C1[row1] = vu1; }\n"
          @"            if (has2) { C0[row2] = vg2; C1[row2] = vu2; }\n"
          @"            if (has3) { C0[row3] = vg3; C1[row3] = vu3; }\n"
          @"        }\n"
          @"    }\n"
          @"}\n"
          @"kernel void aljabr_matvec_tb_bf16_gated_pair_kernel(\n"
          @"    device float* C [[buffer(0)]],\n"
          @"    device const float* A [[buffer(1)]],\n"
          @"    device const ushort* gateW [[buffer(2)]],\n"
          @"    device const ushort* upW [[buffer(3)]],\n"
          @"    constant uint& K [[buffer(4)]],\n"
          @"    constant uint& N [[buffer(5)]],\n"
          @"    constant uint& activationKind [[buffer(6)]],\n"
          @"    uint gid [[threadgroup_position_in_grid]],\n"
          @"    uint tid [[thread_position_in_threadgroup]]) {\n"
          @"    if (gid >= N) return;\n"
          @"    uint base = gid * K;\n"
          @"    float gate = 0.0f;\n"
          @"    float up = 0.0f;\n"
          @"    for (uint k = tid; k < K; k += ALJABR_MATVEC_THREADS) {\n"
          @"        float av = A[k];\n"
          @"        gate += av * aljabr_bf16_to_float(gateW[base + k]);\n"
          @"        up += av * aljabr_bf16_to_float(upW[base + k]);\n"
          @"    }\n"
          @"    threadgroup float partialGate[ALJABR_MATVEC_THREADS];\n"
          @"    threadgroup float partialUp[ALJABR_MATVEC_THREADS];\n"
          @"    partialGate[tid] = gate;\n"
          @"    partialUp[tid] = up;\n"
          @"    threadgroup_barrier(mem_flags::mem_threadgroup);\n"
          @"    for (uint stride = ALJABR_MATVEC_THREADS >> 1; stride > "
          @"0; stride >>= 1) {\n"
          @"        if (tid < stride) {\n"
          @"            partialGate[tid] += partialGate[tid + stride];\n"
          @"            partialUp[tid] += partialUp[tid + stride];\n"
          @"        }\n"
          @"        threadgroup_barrier(mem_flags::mem_threadgroup);\n"
          @"    }\n"
          @"    if (tid == 0) C[gid] = "
          @"aljabr_gated_activation(partialGate[0], partialUp[0], "
          @"activationKind);\n"
          @"}\n"
          @"kernel void aljabr_matvec_tb_bf16_gated_pair_x4_kernel(\n"
          @"    device float* C [[buffer(0)]],\n"
          @"    device const float* A [[buffer(1)]],\n"
          @"    device const ushort* gateW [[buffer(2)]],\n"
          @"    device const ushort* upW [[buffer(3)]],\n"
          @"    constant uint& K [[buffer(4)]],\n"
          @"    constant uint& N [[buffer(5)]],\n"
          @"    constant uint& activationKind [[buffer(6)]],\n"
          @"    uint group [[threadgroup_position_in_grid]],\n"
          @"    uint tid [[thread_position_in_threadgroup]]) {\n"
          @"    uint row0 = group * 4u;\n"
          @"    uint row1 = row0 + 1u;\n"
          @"    uint row2 = row0 + 2u;\n"
          @"    uint row3 = row0 + 3u;\n"
          @"    if (row0 >= N) return;\n"
          @"    bool has1 = row1 < N;\n"
          @"    bool has2 = row2 < N;\n"
          @"    bool has3 = row3 < N;\n"
          @"    uint base0 = row0 * K;\n"
          @"    uint base1 = row1 * K;\n"
          @"    uint base2 = row2 * K;\n"
          @"    uint base3 = row3 * K;\n"
          @"    float g0 = 0.0f, g1 = 0.0f, g2 = 0.0f, g3 = 0.0f;\n"
          @"    float u0 = 0.0f, u1 = 0.0f, u2 = 0.0f, u3 = 0.0f;\n"
          @"    for (uint k = tid; k < K; k += ALJABR_MATVEC_THREADS) {\n"
          @"        float av = A[k];\n"
          @"        g0 += av * aljabr_bf16_to_float(gateW[base0 + k]);\n"
          @"        u0 += av * aljabr_bf16_to_float(upW[base0 + k]);\n"
          @"        if (has1) {\n"
          @"            g1 += av * aljabr_bf16_to_float(gateW[base1 + "
          @"k]);\n"
          @"            u1 += av * aljabr_bf16_to_float(upW[base1 + k]);\n"
          @"        }\n"
          @"        if (has2) {\n"
          @"            g2 += av * aljabr_bf16_to_float(gateW[base2 + "
          @"k]);\n"
          @"            u2 += av * aljabr_bf16_to_float(upW[base2 + k]);\n"
          @"        }\n"
          @"        if (has3) {\n"
          @"            g3 += av * aljabr_bf16_to_float(gateW[base3 + "
          @"k]);\n"
          @"            u3 += av * aljabr_bf16_to_float(upW[base3 + k]);\n"
          @"        }\n"
          @"    }\n"
          @"    threadgroup float pg0[ALJABR_MATVEC_THREADS];\n"
          @"    threadgroup float pg1[ALJABR_MATVEC_THREADS];\n"
          @"    threadgroup float pg2[ALJABR_MATVEC_THREADS];\n"
          @"    threadgroup float pg3[ALJABR_MATVEC_THREADS];\n"
          @"    threadgroup float pu0[ALJABR_MATVEC_THREADS];\n"
          @"    threadgroup float pu1[ALJABR_MATVEC_THREADS];\n"
          @"    threadgroup float pu2[ALJABR_MATVEC_THREADS];\n"
          @"    threadgroup float pu3[ALJABR_MATVEC_THREADS];\n"
          @"    pg0[tid] = g0; pg1[tid] = g1; pg2[tid] = g2; pg3[tid] = g3;\n"
          @"    pu0[tid] = u0; pu1[tid] = u1; pu2[tid] = u2; pu3[tid] = u3;\n"
          @"    threadgroup_barrier(mem_flags::mem_threadgroup);\n"
          @"    for (uint stride = ALJABR_MATVEC_THREADS >> 1; stride > "
          @"0; stride >>= 1) {\n"
          @"        if (tid < stride) {\n"
          @"            pg0[tid] += pg0[tid + stride]; pg1[tid] += pg1[tid + "
          @"stride];\n"
          @"            pg2[tid] += pg2[tid + stride]; pg3[tid] += pg3[tid + "
          @"stride];\n"
          @"            pu0[tid] += pu0[tid + stride]; pu1[tid] += pu1[tid + "
          @"stride];\n"
          @"            pu2[tid] += pu2[tid + stride]; pu3[tid] += pu3[tid + "
          @"stride];\n"
          @"        }\n"
          @"        threadgroup_barrier(mem_flags::mem_threadgroup);\n"
          @"    }\n"
          @"    if (tid == 0) {\n"
          @"        C[row0] = aljabr_gated_activation(pg0[0], pu0[0], "
          @"activationKind);\n"
          @"        if (has1) C[row1] = aljabr_gated_activation(pg1[0], "
          @"pu1[0], activationKind);\n"
          @"        if (has2) C[row2] = aljabr_gated_activation(pg2[0], "
          @"pu2[0], activationKind);\n"
          @"        if (has3) C[row3] = aljabr_gated_activation(pg3[0], "
          @"pu3[0], activationKind);\n"
          @"    }\n"
          @"}\n"
          @"kernel void aljabr_matvec_tb_bf16_gated_pair_simd_kernel(\n"
          @"    device float* C [[buffer(0)]],\n"
          @"    device const float* A [[buffer(1)]],\n"
          @"    device const ushort* gateW [[buffer(2)]],\n"
          @"    device const ushort* upW [[buffer(3)]],\n"
          @"    constant uint& K [[buffer(4)]],\n"
          @"    constant uint& N [[buffer(5)]],\n"
          @"    constant uint& activationKind [[buffer(6)]],\n"
          @"    uint gid [[threadgroup_position_in_grid]],\n"
          @"    uint tid [[thread_position_in_threadgroup]],\n"
          @"    uint lane [[thread_index_in_simdgroup]],\n"
          @"    uint sg [[simdgroup_index_in_threadgroup]]) {\n"
          @"    if (gid >= N) return;\n"
          @"    uint base = gid * K;\n"
          @"    float gate = 0.0f;\n"
          @"    float up = 0.0f;\n"
          @"    for (uint k = tid; k < K; k += ALJABR_MATVEC_THREADS) {\n"
          @"        float av = A[k];\n"
          @"        gate += av * aljabr_bf16_to_float(gateW[base + k]);\n"
          @"        up += av * aljabr_bf16_to_float(upW[base + k]);\n"
          @"    }\n"
          @"    threadgroup float partialGate[8];\n"
          @"    threadgroup float partialUp[8];\n"
          @"    float rowGate = simd_sum(gate);\n"
          @"    float rowUp = simd_sum(up);\n"
          @"    if (lane == 0u) {\n"
          @"        partialGate[sg] = rowGate;\n"
          @"        partialUp[sg] = rowUp;\n"
          @"    }\n"
          @"    threadgroup_barrier(mem_flags::mem_threadgroup);\n"
          @"    if (sg == 0u) {\n"
          @"        uint groups = ALJABR_MATVEC_THREADS / 32u;\n"
          @"        float g = lane < groups ? partialGate[lane] : 0.0f;\n"
          @"        float u = lane < groups ? partialUp[lane] : 0.0f;\n"
          @"        g = simd_sum(g);\n"
          @"        u = simd_sum(u);\n"
          @"        if (lane == 0u) C[gid] = aljabr_gated_activation(g, "
          @"u, activationKind);\n"
          @"    }\n"
          @"}\n"
          @"kernel void aljabr_matvec_rows_tb_bf16_gated_pair_kernel(\n"
          @"    device float* C [[buffer(0)]],\n"
          @"    device const float* A [[buffer(1)]],\n"
          @"    device const ushort* gateW [[buffer(2)]],\n"
          @"    device const ushort* upW [[buffer(3)]],\n"
          @"    constant uint& K [[buffer(4)]],\n"
          @"    constant uint& N [[buffer(5)]],\n"
          @"    constant uint& activationKind [[buffer(6)]],\n"
          @"    constant uint& M [[buffer(7)]],\n"
          @"    uint3 gid [[threadgroup_position_in_grid]],\n"
          @"    uint3 threadPosition [[thread_position_in_threadgroup]]) {\n"
          @"    uint tid = threadPosition.x;\n"
          @"    uint col = gid.x;\n"
          @"    uint row = gid.y;\n"
          @"    if (col >= N || row >= M) return;\n"
          @"    uint inputBase = row * K;\n"
          @"    uint weightBase = col * K;\n"
          @"    float gate = 0.0f;\n"
          @"    float up = 0.0f;\n"
          @"    for (uint k = tid; k < K; k += ALJABR_MATVEC_THREADS) {\n"
          @"        float av = A[inputBase + k];\n"
          @"        gate += av * aljabr_bf16_to_float(gateW[weightBase + "
          @"k]);\n"
          @"        up += av * aljabr_bf16_to_float(upW[weightBase + "
          @"k]);\n"
          @"    }\n"
          @"    threadgroup float partialGate[ALJABR_MATVEC_THREADS];\n"
          @"    threadgroup float partialUp[ALJABR_MATVEC_THREADS];\n"
          @"    partialGate[tid] = gate;\n"
          @"    partialUp[tid] = up;\n"
          @"    threadgroup_barrier(mem_flags::mem_threadgroup);\n"
          @"    for (uint stride = ALJABR_MATVEC_THREADS >> 1; stride > "
          @"0; stride >>= 1) {\n"
          @"        if (tid < stride) {\n"
          @"            partialGate[tid] += partialGate[tid + stride];\n"
          @"            partialUp[tid] += partialUp[tid + stride];\n"
          @"        }\n"
          @"        threadgroup_barrier(mem_flags::mem_threadgroup);\n"
          @"    }\n"
          @"    if (tid == 0) C[row * N + col] = "
          @"aljabr_gated_activation(partialGate[0], partialUp[0], "
          @"activationKind);\n"
          @"}\n"
          @"kernel void aljabr_matvec_rows_tb_bf16_kernel(\n"
          @"    device float* C [[buffer(0)]],\n"
          @"    device const float* A [[buffer(1)]],\n"
          @"    device const ushort* B [[buffer(2)]],\n"
          @"    constant uint& K [[buffer(3)]],\n"
          @"    constant uint& N [[buffer(4)]],\n"
          @"    constant uint& M [[buffer(5)]],\n"
          @"    uint3 gid [[threadgroup_position_in_grid]],\n"
          @"    uint3 threadPosition [[thread_position_in_threadgroup]]) {\n"
          @"    uint tid = threadPosition.x;\n"
          @"    uint col = gid.x;\n"
          @"    uint row = gid.y;\n"
          @"    if (col >= N || row >= M) return;\n"
          @"    uint inputBase = row * K;\n"
          @"    uint weightBase = col * K;\n"
          @"    float sum = 0.0f;\n"
          @"    for (uint k = tid; k < K; k += ALJABR_MATVEC_THREADS) {\n"
          @"        sum += A[inputBase + k] * "
          @"aljabr_bf16_to_float(B[weightBase + k]);\n"
          @"    }\n"
          @"    threadgroup float partial[ALJABR_MATVEC_THREADS];\n"
          @"    partial[tid] = sum;\n"
          @"    threadgroup_barrier(mem_flags::mem_threadgroup);\n"
          @"    for (uint stride = ALJABR_MATVEC_THREADS >> 1; stride > "
          @"0; stride >>= 1) {\n"
          @"        if (tid < stride) partial[tid] += partial[tid + stride];\n"
          @"        threadgroup_barrier(mem_flags::mem_threadgroup);\n"
          @"    }\n"
          @"    if (tid == 0) C[row * N + col] = partial[0];\n"
          @"}\n"
          @"kernel void aljabr_matvec_rows_tb_bf16_gated_pair_x4_kernel(\n"
          @"    device float* C [[buffer(0)]],\n"
