          @"        if (has1) s1 += av * aljabr_bf16_to_float(B[base1 + "
          @"k]);\n"
          @"        if (has2) s2 += av * aljabr_bf16_to_float(B[base2 + "
          @"k]);\n"
          @"        if (has3) s3 += av * aljabr_bf16_to_float(B[base3 + "
          @"k]);\n"
          @"    }\n"
