          @"    threadgroup float p1[ALJABR_MATVEC_THREADS];\n"
          @"    threadgroup float p2[ALJABR_MATVEC_THREADS];\n"
          @"    threadgroup float p3[ALJABR_MATVEC_THREADS];\n"
          @"    p0[tid] = s0; p1[tid] = s1; p2[tid] = s2; p3[tid] = s3;\n"
          @"    threadgroup_barrier(mem_flags::mem_threadgroup);\n"
          @"    for (uint stride = ALJABR_MATVEC_THREADS >> 1; stride > "
          @"0; stride >>= 1) {\n"
