          @"    if (tid == 0) {\n"
          @"        C[outBase + col0] = p0[0];\n"
          @"        if (has1) C[outBase + col1] = p1[0];\n"
          @"        if (has2) C[outBase + col2] = p2[0];\n"
          @"        if (has3) C[outBase + col3] = p3[0];\n"
          @"    }\n"
          @"}\n"
          @"kernel void aljabr_matvec_tb_bf16_triple_mixed_kernel(\n"
          @"    device float* C0 [[buffer(0)]],\n"
          @"    device float* C1 [[buffer(1)]],\n"
          @"    device float* C2 [[buffer(2)]],\n"
          @"    device const float* A [[buffer(3)]],\n"
          @"    device const ushort* B0 [[buffer(4)]],\n"
          @"    device const ushort* B1 [[buffer(5)]],\n"
          @"    device const ushort* B2 [[buffer(6)]],\n"
          @"    constant uint& K [[buffer(7)]],\n"
          @"    constant uint& N0 [[buffer(8)]],\n"
          @"    constant uint& N1 [[buffer(9)]],\n"
          @"    constant uint& N2 [[buffer(10)]],\n"
          @"    uint gid [[threadgroup_position_in_grid]],\n"
          @"    uint tid [[thread_position_in_threadgroup]]) {\n"
          @"    uint total = N0 + N1 + N2;\n"
          @"    if (gid >= total) return;\n"
          @"    device const ushort* B = B0;\n"
          @"    device float* C = C0;\n"
          @"    uint local = gid;\n"
          @"    if (gid >= N0 + N1) {\n"
          @"        B = B2;\n"
          @"        C = C2;\n"
          @"        local = gid - N0 - N1;\n"
          @"    } else if (gid >= N0) {\n"
          @"        B = B1;\n"
          @"        C = C1;\n"
          @"        local = gid - N0;\n"
          @"    }\n"
          @"    uint base = local * K;\n"
          @"    float sum = 0.0f;\n"
          @"    for (uint k = tid; k < K; k += ALJABR_MATVEC_THREADS) {\n"
          @"        sum += A[k] * aljabr_bf16_to_float(B[base + k]);\n"
          @"    }\n"
          @"    threadgroup float partial[ALJABR_MATVEC_THREADS];\n"
          @"    partial[tid] = sum;\n"
          @"    threadgroup_barrier(mem_flags::mem_threadgroup);\n"
          @"    for (uint stride = ALJABR_MATVEC_THREADS >> 1; stride > "
          @"0; stride >>= 1) {\n"
          @"        if (tid < stride) partial[tid] += partial[tid + stride];\n"
          @"        threadgroup_barrier(mem_flags::mem_threadgroup);\n"
          @"    }\n"
          @"    if (tid == 0) C[local] = partial[0];\n"
          @"}\n"
          @"kernel void aljabr_matvec_tb_bf16_triple_mixed_x4_kernel(\n"
          @"    device float* C0 [[buffer(0)]],\n"
          @"    device float* C1 [[buffer(1)]],\n"
          @"    device float* C2 [[buffer(2)]],\n"
          @"    device const float* A [[buffer(3)]],\n"
          @"    device const ushort* B0 [[buffer(4)]],\n"
          @"    device const ushort* B1 [[buffer(5)]],\n"
          @"    device const ushort* B2 [[buffer(6)]],\n"
          @"    constant uint& K [[buffer(7)]],\n"
          @"    constant uint& N0 [[buffer(8)]],\n"
          @"    constant uint& N1 [[buffer(9)]],\n"
          @"    constant uint& N2 [[buffer(10)]],\n"
          @"    uint group [[threadgroup_position_in_grid]],\n"
          @"    uint tid [[thread_position_in_threadgroup]]) {\n"
          @"    uint total = N0 + N1 + N2;\n"
          @"    uint row0 = group * 4u;\n"
          @"    uint row1 = row0 + 1u;\n"
          @"    uint row2 = row0 + 2u;\n"
          @"    uint row3 = row0 + 3u;\n"
          @"    if (row0 >= total) return;\n"
          @"    bool has1 = row1 < total;\n"
          @"    bool has2 = row2 < total;\n"
          @"    bool has3 = row3 < total;\n"
          @"    device const ushort* W0 = B0;\n"
          @"    device const ushort* W1 = B0;\n"
          @"    device const ushort* W2 = B0;\n"
          @"    device const ushort* W3 = B0;\n"
          @"    device float* O0 = C0;\n"
          @"    device float* O1 = C0;\n"
          @"    device float* O2 = C0;\n"
          @"    device float* O3 = C0;\n"
          @"    uint local0 = row0;\n"
          @"    uint local1 = row1;\n"
          @"    uint local2 = row2;\n"
          @"    uint local3 = row3;\n"
          @"    if (row0 >= N0 + N1) { W0 = B2; O0 = C2; local0 = row0 - N0 - "
          @"N1; }\n"
          @"    else if (row0 >= N0) { W0 = B1; O0 = C1; local0 = row0 - N0; "
          @"}\n"
          @"    if (has1) {\n"
          @"        if (row1 >= N0 + N1) { W1 = B2; O1 = C2; local1 = row1 - "
          @"N0 - N1; }\n"
          @"        else if (row1 >= N0) { W1 = B1; O1 = C1; local1 = row1 - "
          @"N0; }\n"
          @"    }\n"
          @"    if (has2) {\n"
          @"        if (row2 >= N0 + N1) { W2 = B2; O2 = C2; local2 = row2 - "
          @"N0 - N1; }\n"
          @"        else if (row2 >= N0) { W2 = B1; O2 = C1; local2 = row2 - "
          @"N0; }\n"
          @"    }\n"
          @"    if (has3) {\n"
          @"        if (row3 >= N0 + N1) { W3 = B2; O3 = C2; local3 = row3 - "
          @"N0 - N1; }\n"
          @"        else if (row3 >= N0) { W3 = B1; O3 = C1; local3 = row3 - "
          @"N0; }\n"
          @"    }\n"
          @"    uint base0 = local0 * K;\n"
          @"    uint base1 = local1 * K;\n"
          @"    uint base2 = local2 * K;\n"
          @"    uint base3 = local3 * K;\n"
          @"    float sum0 = 0.0f;\n"
          @"    float sum1 = 0.0f;\n"
          @"    float sum2 = 0.0f;\n"
          @"    float sum3 = 0.0f;\n"
          @"    for (uint k = tid; k < K; k += ALJABR_MATVEC_THREADS) {\n"
          @"        float av = A[k];\n"
          @"        sum0 += av * aljabr_bf16_to_float(W0[base0 + k]);\n"
          @"        if (has1) sum1 += av * aljabr_bf16_to_float(W1[base1 "
          @"+ k]);\n"
          @"        if (has2) sum2 += av * aljabr_bf16_to_float(W2[base2 "
          @"+ k]);\n"
          @"        if (has3) sum3 += av * aljabr_bf16_to_float(W3[base3 "
          @"+ k]);\n"
          @"    }\n"
          @"    threadgroup float p0[ALJABR_MATVEC_THREADS];\n"
          @"    threadgroup float p1[ALJABR_MATVEC_THREADS];\n"
          @"    threadgroup float p2[ALJABR_MATVEC_THREADS];\n"
          @"    threadgroup float p3[ALJABR_MATVEC_THREADS];\n"
          @"    p0[tid] = sum0;\n"
          @"    p1[tid] = sum1;\n"
          @"    p2[tid] = sum2;\n"
          @"    p3[tid] = sum3;\n"
          @"    threadgroup_barrier(mem_flags::mem_threadgroup);\n"
          @"    for (uint stride = ALJABR_MATVEC_THREADS >> 1; stride > "
          @"0; stride >>= 1) {\n"
          @"        if (tid < stride) {\n"
          @"            p0[tid] += p0[tid + stride];\n"
          @"            p1[tid] += p1[tid + stride];\n"
          @"            p2[tid] += p2[tid + stride];\n"
          @"            p3[tid] += p3[tid + stride];\n"
          @"        }\n"
          @"        threadgroup_barrier(mem_flags::mem_threadgroup);\n"
          @"    }\n"
          @"    if (tid == 0) {\n"
          @"        O0[local0] = p0[0];\n"
          @"        if (has1) O1[local1] = p1[0];\n"
          @"        if (has2) O2[local2] = p2[0];\n"
          @"        if (has3) O3[local3] = p3[0];\n"
          @"    }\n"
          @"}\n"
          @"kernel void aljabr_matvec_t_half_kernel(\n"
          @"    device float* C [[buffer(0)]],\n"
          @"    device const float* A [[buffer(1)]],\n"
          @"    device const half* B [[buffer(2)]],\n"
          @"    constant uint& K [[buffer(3)]],\n"
          @"    constant uint& N [[buffer(4)]],\n"
          @"    uint gid [[threadgroup_position_in_grid]],\n"
          @"    uint tid [[thread_position_in_threadgroup]]) {\n"
          @"    if (gid >= N) return;\n"
          @"    float sum = 0.0f;\n"
          @"    for (uint k = tid; k < K; k += ALJABR_MATVEC_THREADS) {\n"
          @"        sum += A[k] * float(B[k * N + gid]);\n"
          @"    }\n"
          @"    threadgroup float partial[ALJABR_MATVEC_THREADS];\n"
          @"    partial[tid] = sum;\n"
          @"    threadgroup_barrier(mem_flags::mem_threadgroup);\n"
          @"    for (uint stride = ALJABR_MATVEC_THREADS >> 1; stride > "
          @"0; stride >>= 1) {\n"
          @"        if (tid < stride) partial[tid] += partial[tid + stride];\n"
          @"        threadgroup_barrier(mem_flags::mem_threadgroup);\n"
          @"    }\n"
          @"    if (tid == 0) C[gid] = partial[0];\n"
          @"}\n"
          @"constant float nf4_lut[16] = {\n"
          @"    -1.0f, -0.6961928009986877f, -0.5250730514526367f, "
          @"-0.39491748809814453f,\n"
          @"    -0.28444138169288635f, -0.18477343022823334f, "
          @"-0.09105003625154495f, 0.0f,\n"
          @"    0.07958029955625534f, 0.16093020141124725f, "
          @"0.24611230194568634f, 0.33791524171829224f,\n"
          @"    0.44070982933044434f, 0.5626170039176941f, "
          @"0.7229568362236023f, 1.0f\n"
          @"};\n"
          @"kernel void aljabr_matvec_tb_int4_kernel(\n"
          @"    device float* C [[buffer(0)]],\n"
          @"    device const float* A [[buffer(1)]],\n"
          @"    device const uint* B [[buffer(2)]],\n"
          @"    device const float* scales [[buffer(3)]],\n"
          @"    constant uint& K [[buffer(4)]],\n"
          @"    constant uint& N [[buffer(5)]],\n"
          @"    constant uint& blockSize [[buffer(6)]],\n" // blockSize =
                                                           // groupSize
          @"    uint gid [[threadgroup_position_in_grid]],\n"
          @"    uint tid [[thread_position_in_threadgroup]]) {\n"
          @"    if (gid >= N) return;\n"
          @"    float sum = 0.0f;\n"
          @"    uint scale_stride = K / blockSize;\n"
          @"    for (uint k = tid; k < K; k += ALJABR_MATVEC_THREADS) {\n"
          @"        uint b_idx = gid * K + k;\n"
          @"        uint packed_val = B[b_idx / 8];\n"
          @"        uint shift = (b_idx %% 8) * 4;\n"
          @"        uint val = (packed_val >> shift) & 0xF;\n"
          @"        float w = (float)(int(val) - 8) * scales[gid * "
          @"scale_stride + (k / blockSize)];\n"
          @"        sum += A[k] * w;\n"
          @"    }\n"
          @"    threadgroup float partial[ALJABR_MATVEC_THREADS];\n"
          @"    partial[tid] = sum;\n"
          @"    threadgroup_barrier(mem_flags::mem_threadgroup);\n"
          @"    for (uint stride = ALJABR_MATVEC_THREADS >> 1; stride > "
          @"0; stride >>= 1) {\n"
          @"        if (tid < stride) partial[tid] += partial[tid + stride];\n"
          @"        threadgroup_barrier(mem_flags::mem_threadgroup);\n"
          @"    }\n"
          @"    if (tid == 0) C[gid] = partial[0];\n"
          @"}\n"
          @"kernel void aljabr_matvec_tb_nf4_kernel(\n"
          @"    device float* C [[buffer(0)]],\n"
          @"    device const float* A [[buffer(1)]],\n"
          @"    device const uchar* B [[buffer(2)]],\n"
          @"    device const float* absmax [[buffer(3)]],\n"
          @"    constant uint& K [[buffer(4)]],\n"
          @"    constant uint& N [[buffer(5)]],\n"
          @"    constant uint& blockSize [[buffer(6)]],\n"
          @"    uint gid [[threadgroup_position_in_grid]],\n"
          @"    uint tid [[thread_position_in_threadgroup]]) {\n"
          @"    if (gid >= N) return;\n"
          @"    float sum = 0.0f;\n"
          @"    for (uint k = tid; k < K; k += ALJABR_MATVEC_THREADS) {\n"
          @"        // Weight is stored row-major [N_out, K_in]: element [gid, "
          @"k] at linear index gid*K+k\n"
          @"        uint b_idx = gid * K + k;\n"
          @"        uint byte_idx = b_idx / 2;\n"
          @"        uint nibble_idx = b_idx & 1;\n"
          @"        uchar byte_val = B[byte_idx];\n"
          @"        // BNB NF4 packs high nibble first (even index=high, odd "
          @"index=low)\n"
          @"        uchar nibble = (nibble_idx == 0) ? (byte_val >> 4) : "
          @"(byte_val & 0x0F);\n"
          @"        float w = nf4_lut[nibble] * absmax[b_idx / blockSize];\n"
          @"        sum += A[k] * w;\n"
          @"    }\n"
          @"    threadgroup float partial[ALJABR_MATVEC_THREADS];\n"
          @"    partial[tid] = sum;\n"
          @"    threadgroup_barrier(mem_flags::mem_threadgroup);\n"
          @"    for (uint stride = ALJABR_MATVEC_THREADS >> 1; stride > "
          @"0; stride >>= 1) {\n"
          @"        if (tid < stride) partial[tid] += partial[tid + stride];\n"
          @"        threadgroup_barrier(mem_flags::mem_threadgroup);\n"
          @"    }\n"
          @"    if (tid == 0) C[gid] = partial[0];\n"
          @"}\n"
          @"typedef struct {\n"
          @"    half d;\n"
          @"    int8_t qs[32];\n"
          @"} block_q8_0;\n"
          @"\n"
          @"typedef struct {\n"
          @"    half2 dm;\n"
          @"    uint8_t scales[12];\n"
          @"    uint8_t qs[128];\n"
          @"} block_q4_K;\n"
          @"\n"
          @"typedef struct {\n"
          @"    uint8_t ql[128];\n"
          @"    uint8_t qh[64];\n"
          @"    int8_t  scales[16];\n"
          @"    half    d;\n"
          @"} block_q6_K;\n"
          @"\n"
          @"static inline float block_q6_K_dot_f32(device const block_q6_K* b, device const float* a) {\n"
          @"    float sum = 0.0f;\n"
          @"    float d = (float)b->d;\n"
          @"    for (int n = 0; n < 2; ++n) {\n"
          @"        device const uint8_t* ql = b->ql + n * 64;\n"
          @"        device const uint8_t* qh = b->qh + n * 32;\n"
          @"        device const int8_t* sc = b->scales + n * 8;\n"
          @"        device const float* av = a + n * 128;\n"
          @"        for (int l = 0; l < 32; l += 8) {\n"
          @"            int is = l / 16;\n"
          @"            float s0 = d * (float)sc[is + 0];\n"
          @"            float s1 = d * (float)sc[is + 2];\n"
          @"            float s2 = d * (float)sc[is + 4];\n"
          @"            float s3 = d * (float)sc[is + 6];\n"
          @"            for (int i = 0; i < 8; ++i) {\n"
          @"                int idx = l + i;\n"
          @"                uint8_t low0 = ql[idx];\n"
          @"                uint8_t low1 = ql[idx + 32];\n"
          @"                uint8_t high = qh[idx];\n"
          @"                int q0 = ((low0 & 0x0F) | (((high >> 0) & 0x03) << 4)) - 32;\n"
          @"                int q1 = ((low1 & 0x0F) | (((high >> 2) & 0x03) << 4)) - 32;\n"
          @"                int q2 = ((low0 >> 4)   | (((high >> 4) & 0x03) << 4)) - 32;\n"
          @"                int q3 = ((low1 >> 4)   | (((high >> 6) & 0x03) << 4)) - 32;\n"
          @"                sum += s0 * q0 * av[idx]\n"
          @"                     + s1 * q1 * av[idx + 32]\n"
          @"                     + s2 * q2 * av[idx + 64]\n"
          @"                     + s3 * q3 * av[idx + 96];\n"
          @"            }\n"
          @"        }\n"
          @"    }\n"
          @"    return sum;\n"
          @"}\n"
          @"\n"
          @"static inline float block_q8_0_dot_f32(device const block_q8_0* b, "
          @"device const float* a) {\n"
          @"    float sum = 0.0;\n"
          @"    float d = (float)b->d;\n"
          @"    for (int i = 0; i < 32; ++i) {\n"
          @"        sum += d * b->qs[i] * a[i];\n"
          @"    }\n"
          @"    return sum;\n"
          @"}\n"
          @"\n"
          @"static inline float block_q4_K_dot_f32(device const block_q4_K* b, "
          @"device const float* a) {\n"
          @"    float sum = 0.0;\n"
          @"    for (int il = 0; il < 16; ++il) {\n"
          @"        short is = (il/4) * 2;\n"
          @"        device const uchar * q = b->qs + (il/4) * 32 + 16 * "
          @"(il&1);\n"
          @"        int sub_il = il & 3;\n"
          @"        \n"
          @"        uchar sc0, sc1;\n"
          @"        int j = is;\n"
          @"        int k = sub_il/2;\n"
          @"        if (j < 4) {\n"
          @"            sc0 = b->scales[j+0+k] & 63;\n"
          @"            sc1 = b->scales[j+4+k] & 63;\n"
          @"        } else {\n"
          @"            sc0 = (b->scales[j+4+k] & 0xF) | ((b->scales[j-4+k] & "
          @"0xc0) >> 2);\n"
          @"            sc1 = (b->scales[j+4+k] >> 4)  | ((b->scales[j-0+k] & "
          @"0xc0) >> 2);\n"
          @"        }\n"
          @"        \n"
          @"        float d   = sub_il < 2 ? (float)b->dm[0] : (float)b->dm[0] "
          @"/ 16.0f;\n"
          @"        float min = (float)b->dm[1];\n"
          @"        float dl = d * sc0;\n"
          @"        float ml = min * sc1;\n"
          @"        \n"
          @"        ushort mask = sub_il < 2 ? 0x0F : 0xF0;\n"
          @"        for (int i = 0; i < 16; ++i) {\n"
          @"            float v = dl * (q[i] & mask) - ml;\n"
          @"            sum += v * a[il * 16 + i];\n"
          @"        }\n"
          @"    }\n"
          @"    return sum;\n"
          @"}\n"
          @"\n"
          @"kernel void aljabr_matvec_tb_q8_0_kernel(\n"
          @"    device float* C [[buffer(0)]],\n"
          @"    device const float* A [[buffer(1)]],\n"
          @"    device const block_q8_0* B [[buffer(2)]],\n"
          @"    constant uint& K [[buffer(3)]],\n"
          @"    constant uint& N [[buffer(4)]],\n"
          @"    uint gid [[threadgroup_position_in_grid]],\n"
          @"    ushort tid [[thread_position_in_threadgroup]]) {\n"
          @"    if (gid >= N) return;\n"
          @"    float sum = 0.0f;\n"
          @"    uint nb = K / 32;\n"
          @"    device const block_q8_0* x = B + gid * nb;\n"
          @"    for (uint ib = 0; ib < nb; ++ib) {\n"
          @"        sum += float(x[ib].d) * float(x[ib].qs[tid]) * A[ib * 32 + tid];\n"
          @"    }\n"
          @"    sum = simd_sum(sum);\n"
          @"    if (tid == 0) C[gid] = sum;\n"
          @"}\n"
          @"\n"
          @"kernel void aljabr_matvec_tb_q4_k_kernel(\n"
          @"    device float* C [[buffer(0)]],\n"
          @"    device const float* A [[buffer(1)]],\n"
          @"    device const block_q4_K* B [[buffer(2)]],\n"
          @"    constant uint& K [[buffer(3)]],\n"
          @"    constant uint& N [[buffer(4)]],\n"
          @"    uint gid [[threadgroup_position_in_grid]],\n"
          @"    ushort tid [[thread_position_in_threadgroup]]) {\n"
          @"    if (gid >= N) return;\n"
          @"    const uint nb = K >> 8u;\n"
          @"    device const block_q4_K* x = B + gid * nb;\n"
          @"    float sum = 0.0f;\n"
          @"    const uint elem_start = tid << 3u;\n"
          @"    const uint sb = elem_start >> 5u;\n"
          @"    const uint chunk = elem_start >> 6u;\n"
          @"    const bool is_low = (elem_start & 32u) == 0u;\n"
          @"    const uint base_b = (chunk << 5u) + (elem_start & 31u);\n"
          @"\n"
          @"    for (uint ib = 0; ib < nb; ++ib) {\n"
          @"        const float d    = float(x[ib].dm[0]);\n"
          @"        const float dmin = float(x[ib].dm[1]);\n"
          @"        device const float* a = A + (ib << 8u) + elem_start;\n"
          @"        uint8_t sc_raw, mn_raw;\n"
          @"        if (sb < 4u) {\n"
          @"            sc_raw = x[ib].scales[sb] & 0x3Fu;\n"
          @"            mn_raw = x[ib].scales[sb + 4u] & 0x3Fu;\n"
          @"        } else {\n"
          @"            sc_raw = (x[ib].scales[sb + 4u] & 0x0Fu) | ((x[ib].scales[sb - 4u] >> 6u) << 4u);\n"
          @"            mn_raw = (x[ib].scales[sb + 4u] >> 4u)   | ((x[ib].scales[sb]      >> 6u) << 4u);\n"
          @"        }\n"
          @"        const float sc = float(sc_raw);\n"
          @"        const float mn = float(mn_raw);\n"
          @"\n"
          @"        float block_sum = 0.0f;\n"
          @"        float sum_y = 0.0f;\n"
          @"        for (uint i = 0; i < 8u; ++i) {\n"
          @"            const uint8_t qbyte = x[ib].qs[base_b + i];\n"
          @"            const uint8_t q = is_low ? (qbyte & 0x0Fu) : (qbyte >> 4u);\n"
          @"            block_sum += float(q) * a[i];\n"
          @"            sum_y += a[i];\n"
          @"        }\n"
          @"        sum += d * sc * block_sum - dmin * mn * sum_y;\n"
          @"    }\n"
          @"    sum = simd_sum(sum);\n"
          @"    if (tid == 0) C[gid] = sum;\n"
          @"}\n"
          @"\n"
          // ── Multi-row Q4_K: 4 output rows per threadgroup, A cached in threadgroup memory ──
          // Each threadgroup = 4 rows × 32 lanes = 128 threads.
          // For every 256-element block:
          //   • 128 threads cooperatively load 256 floats of A into sA[] (2 floats/thread).
          //   • Each row's 32 lanes independently dot-product against its own Q4_K block row.
          // Result: A is read from device memory once per (4×32) thread wave instead of
          // once per 32-thread wave → 4× reduction in A bandwidth.
          @"kernel void aljabr_matvec_tb_q4_k_mr4_kernel(\n"
          @"    device float* C [[buffer(0)]],\n"
          @"    device const float* A [[buffer(1)]],\n"
          @"    device const block_q4_K* B [[buffer(2)]],\n"
          @"    constant uint& K [[buffer(3)]],\n"
          @"    constant uint& N [[buffer(4)]],\n"
          @"    uint2 tgid [[threadgroup_position_in_grid]],\n"
          @"    ushort2 tid [[thread_position_in_threadgroup]]) {\n"
          @"    const uint nb = K >> 8u;\n"
          @"    const uint sgitg = (uint)tid.x >> 5u;\n"
          @"    const ushort tiisg = tid.x & 31u;\n"
          @"    const uint first_row = tgid.x * 4u + sgitg * 2u;\n"
          @"    if (first_row >= N) return;\n"
          @"    device const float* A_t = A + (uint)tgid.y * K;\n"
          @"    device const block_q4_K* blk_row0 = B + first_row * nb;\n"
          @"    device const block_q4_K* blk_row1 = (first_row + 1u < N) ? (blk_row0 + nb) : nullptr;\n"
          @"    constexpr uint16_t kmask1 = 0x3f3f;\n"
          @"    constexpr uint16_t kmask2 = 0x0f0f;\n"
          @"    constexpr uint16_t kmask3 = 0xc0c0;\n"
          @"    const ushort ix = tiisg / 8u;\n"
          @"    const ushort it = tiisg %% 8u;\n"
          @"    const ushort iq = it / 4u;\n"
          @"    const ushort ir = it %% 4u;\n"
          @"    device const float* y4 = A_t + (uint)ix * 256u + 64u * (uint)iq + 8u * (uint)ir;\n"
          @"    uint16_t sc16_0[4];\n"
          @"    thread const uint8_t* sc8_0 = (thread const uint8_t*)sc16_0;\n"
          @"    uint16_t sc16_1[4];\n"
          @"    thread const uint8_t* sc8_1 = (thread const uint8_t*)sc16_1;\n"
          @"    float sum0 = 0.0f;\n"
          @"    float sum1 = 0.0f;\n"
          @"    for (uint ib = ix; ib < nb; ib += 4u) {\n"
          @"        const float4 yl_even = { y4[0], y4[2], y4[4], y4[6] };\n"
          @"        const float4 yl_odd  = { y4[1], y4[3], y4[5], y4[7] };\n"
          @"        const float4 yl_m8   = { y4[32], y4[34], y4[36], y4[38] };\n"
          @"        const float4 yl_h8   = { y4[33], y4[35], y4[37], y4[39] };\n"
