          @"\n"
          @"kernel void aljabr_ffn_gate_up_act_q4_k_mr4_kernel(\n"
          @"    device float* hb [[buffer(0)]],\n"
          @"    device const float* A [[buffer(1)]],\n"
          @"    device const block_q4_K* B_gate [[buffer(2)]],\n"
          @"    device const block_q4_K* B_up [[buffer(3)]],\n"
          @"    constant uint& K [[buffer(4)]],\n"
          @"    constant uint& N [[buffer(5)]],\n"
          @"    constant uint& activationKind [[buffer(6)]],\n"
          @"    uint2 tgid [[threadgroup_position_in_grid]],\n"
          @"    ushort2 tid [[thread_position_in_threadgroup]]) {\n"
          @"    const uint nb = K >> 8u;\n"
          @"    const uint sgitg = (uint)tid.x >> 5u;\n"
          @"    const ushort tiisg = tid.x & 31u;\n"
          @"    const uint first_row = tgid.x * 4u + sgitg * 2u;\n"
          @"    if (first_row >= N) return;\n"
          @"    device const float* A_t = A + (uint)tgid.y * K;\n"
          @"    device const block_q4_K* blk_g0 = B_gate + first_row * nb;\n"
          @"    device const block_q4_K* blk_u0 = B_up   + first_row * nb;\n"
          @"    device const block_q4_K* blk_g1 = (first_row + 1u < N) ? (blk_g0 + nb) : nullptr;\n"
          @"    device const block_q4_K* blk_u1 = (first_row + 1u < N) ? (blk_u0 + nb) : nullptr;\n"
          @"    constexpr uint16_t kmask1 = 0x3f3f;\n"
          @"    constexpr uint16_t kmask2 = 0x0f0f;\n"
          @"    constexpr uint16_t kmask3 = 0xc0c0;\n"
          @"    const ushort ix = tiisg / 8u;\n"
          @"    const ushort it = tiisg %% 8u;\n"
          @"    const ushort iq = it / 4u;\n"
          @"    const ushort ir = it %% 4u;\n"
          @"    device const float* y4 = A_t + (uint)ix * 256u + 64u * (uint)iq + 8u * (uint)ir;\n"
          @"    uint16_t sc16_g0[4], sc16_u0[4];\n"
          @"    thread const uint8_t* sc8_g0 = (thread const uint8_t*)sc16_g0;\n"
          @"    thread const uint8_t* sc8_u0 = (thread const uint8_t*)sc16_u0;\n"
          @"    uint16_t sc16_g1[4], sc16_u1[4];\n"
          @"    thread const uint8_t* sc8_g1 = (thread const uint8_t*)sc16_g1;\n"
          @"    thread const uint8_t* sc8_u1 = (thread const uint8_t*)sc16_u1;\n"
          @"    float sum_gate0 = 0.0f;\n"
          @"    float sum_up0   = 0.0f;\n"
          @"    float sum_gate1 = 0.0f;\n"
          @"    float sum_up1   = 0.0f;\n"
          @"    for (uint ib = ix; ib < nb; ib += 4u) {\n"
          @"        float yl[16];\n"
          @"        float yh[16];\n"
          @"        float4 sumy = {0.f, 0.f, 0.f, 0.f};\n"
          @"        yl[0] = y4[0];   sumy[0] += yl[0];  yl[8]  = y4[32];  sumy[1] += yl[8];\n"
          @"        yl[1] = y4[1];   sumy[0] += yl[1];  yl[9]  = y4[33];  sumy[1] += yl[9];\n"
          @"        yl[2] = y4[2];   sumy[0] += yl[2];  yl[10] = y4[34];  sumy[1] += yl[10];\n"
          @"        yl[3] = y4[3];   sumy[0] += yl[3];  yl[11] = y4[35];  sumy[1] += yl[11];\n"
          @"        yl[4] = y4[4];   sumy[0] += yl[4];  yl[12] = y4[36];  sumy[1] += yl[12];\n"
          @"        yl[5] = y4[5];   sumy[0] += yl[5];  yl[13] = y4[37];  sumy[1] += yl[13];\n"
          @"        yl[6] = y4[6];   sumy[0] += yl[6];  yl[14] = y4[38];  sumy[1] += yl[14];\n"
          @"        yl[7] = y4[7];   sumy[0] += yl[7];  yl[15] = y4[39];  sumy[1] += yl[15];\n"
          @"        yh[0] = y4[128]; sumy[2] += yh[0];  yh[8]  = y4[160]; sumy[3] += yh[8];\n"
          @"        yh[1] = y4[129]; sumy[2] += yh[1];  yh[9]  = y4[161]; sumy[3] += yh[9];\n"
          @"        yh[2] = y4[130]; sumy[2] += yh[2];  yh[10] = y4[162]; sumy[3] += yh[10];\n"
          @"        yh[3] = y4[131]; sumy[2] += yh[3];  yh[11] = y4[163]; sumy[3] += yh[11];\n"
          @"        yh[4] = y4[132]; sumy[2] += yh[4];  yh[12] = y4[164]; sumy[3] += yh[12];\n"
          @"        yh[5] = y4[133]; sumy[2] += yh[5];  yh[13] = y4[165]; sumy[3] += yh[13];\n"
          @"        yh[6] = y4[134]; sumy[2] += yh[6];  yh[14] = y4[166]; sumy[3] += yh[14];\n"
          @"        yh[7] = y4[135]; sumy[2] += yh[7];  yh[15] = y4[167]; sumy[3] += yh[15];\n"
          @"        device const block_q4_K* bg0 = blk_g0 + ib;\n"
          @"        device const uint16_t* sc_g0 = (device const uint16_t*)bg0->scales + iq;\n"
          @"        device const uint16_t* q1_g0 = (device const uint16_t*)bg0->qs + 16u * iq + 4u * ir;\n"
          @"        device const half* dh_g0 = (device const half*)&bg0->dm;\n"
          @"        sc16_g0[0] = sc_g0[0] & kmask1;\n"
          @"        sc16_g0[1] = sc_g0[2] & kmask1;\n"
          @"        sc16_g0[2] = ((sc_g0[4] >> 0) & kmask2) | ((sc_g0[0] & kmask3) >> 2);\n"
          @"        sc16_g0[3] = ((sc_g0[4] >> 4) & kmask2) | ((sc_g0[2] & kmask3) >> 2);\n"
          @"        device const uint16_t* q2_g0 = q1_g0 + 32;\n"
          @"        float4 acc1_g0 = {0.f, 0.f, 0.f, 0.f};\n"
          @"        float4 acc2_g0 = {0.f, 0.f, 0.f, 0.f};\n"
          @"        acc1_g0[0] = yl[0]*float(q1_g0[0]&0x000Fu) + yl[2]*float(q1_g0[1]&0x000Fu) + yl[4]*float(q1_g0[2]&0x000Fu) + yl[6]*float(q1_g0[3]&0x000Fu);\n"
          @"        acc1_g0[1] = yl[1]*float(q1_g0[0]&0x0F00u) + yl[3]*float(q1_g0[1]&0x0F00u) + yl[5]*float(q1_g0[2]&0x0F00u) + yl[7]*float(q1_g0[3]&0x0F00u);\n"
          @"        acc1_g0[2] = yl[8]*float(q1_g0[0]&0x00F0u) + yl[10]*float(q1_g0[1]&0x00F0u) + yl[12]*float(q1_g0[2]&0x00F0u) + yl[14]*float(q1_g0[3]&0x00F0u);\n"
          @"        acc1_g0[3] = yl[9]*float(q1_g0[0]&0xF000u) + yl[11]*float(q1_g0[1]&0xF000u) + yl[13]*float(q1_g0[2]&0xF000u) + yl[15]*float(q1_g0[3]&0xF000u);\n"
          @"        acc2_g0[0] = yh[0]*float(q2_g0[0]&0x000Fu) + yh[2]*float(q2_g0[1]&0x000Fu) + yh[4]*float(q2_g0[2]&0x000Fu) + yh[6]*float(q2_g0[3]&0x000Fu);\n"
          @"        acc2_g0[1] = yh[1]*float(q2_g0[0]&0x0F00u) + yh[3]*float(q2_g0[1]&0x0F00u) + yh[5]*float(q2_g0[2]&0x0F00u) + yh[7]*float(q2_g0[3]&0x0F00u);\n"
          @"        acc2_g0[2] = yh[8]*float(q2_g0[0]&0x00F0u) + yh[10]*float(q2_g0[1]&0x00F0u) + yh[12]*float(q2_g0[2]&0x00F0u) + yh[14]*float(q2_g0[3]&0x00F0u);\n"
          @"        acc2_g0[3] = yh[9]*float(q2_g0[0]&0xF000u) + yh[11]*float(q2_g0[1]&0xF000u) + yh[13]*float(q2_g0[2]&0xF000u) + yh[15]*float(q2_g0[3]&0xF000u);\n"
          @"        sum_gate0 += float(dh_g0[0]) * ((acc1_g0[0] + (1.f/256.f) * acc1_g0[1]) * float(sc8_g0[0]) +\n"
          @"                                        (acc1_g0[2] + (1.f/256.f) * acc1_g0[3]) * float(sc8_g0[1]) * (1.f/16.f) +\n"
          @"                                        (acc2_g0[0] + (1.f/256.f) * acc2_g0[1]) * float(sc8_g0[4]) +\n"
          @"                                        (acc2_g0[2] + (1.f/256.f) * acc2_g0[3]) * float(sc8_g0[5]) * (1.f/16.f)) -\n"
          @"                     float(dh_g0[1]) * (sumy[0] * float(sc8_g0[2]) + sumy[1] * float(sc8_g0[3]) + sumy[2] * float(sc8_g0[6]) + sumy[3] * float(sc8_g0[7]));\n"
          @"        device const block_q4_K* bu0 = blk_u0 + ib;\n"
          @"        device const uint16_t* sc_u0 = (device const uint16_t*)bu0->scales + iq;\n"
          @"        device const uint16_t* q1_u0 = (device const uint16_t*)bu0->qs + 16u * iq + 4u * ir;\n"
          @"        device const half* dh_u0 = (device const half*)&bu0->dm;\n"
          @"        sc16_u0[0] = sc_u0[0] & kmask1;\n"
          @"        sc16_u0[1] = sc_u0[2] & kmask1;\n"
          @"        sc16_u0[2] = ((sc_u0[4] >> 0) & kmask2) | ((sc_u0[0] & kmask3) >> 2);\n"
          @"        sc16_u0[3] = ((sc_u0[4] >> 4) & kmask2) | ((sc_u0[2] & kmask3) >> 2);\n"
          @"        device const uint16_t* q2_u0 = q1_u0 + 32;\n"
          @"        float4 acc1_u0 = {0.f, 0.f, 0.f, 0.f};\n"
          @"        float4 acc2_u0 = {0.f, 0.f, 0.f, 0.f};\n"
          @"        acc1_u0[0] = yl[0]*float(q1_u0[0]&0x000Fu) + yl[2]*float(q1_u0[1]&0x000Fu) + yl[4]*float(q1_u0[2]&0x000Fu) + yl[6]*float(q1_u0[3]&0x000Fu);\n"
          @"        acc1_u0[1] = yl[1]*float(q1_u0[0]&0x0F00u) + yl[3]*float(q1_u0[1]&0x0F00u) + yl[5]*float(q1_u0[2]&0x0F00u) + yl[7]*float(q1_u0[3]&0x0F00u);\n"
          @"        acc1_u0[2] = yl[8]*float(q1_u0[0]&0x00F0u) + yl[10]*float(q1_u0[1]&0x00F0u) + yl[12]*float(q1_u0[2]&0x00F0u) + yl[14]*float(q1_u0[3]&0x00F0u);\n"
          @"        acc1_u0[3] = yl[9]*float(q1_u0[0]&0xF000u) + yl[11]*float(q1_u0[1]&0xF000u) + yl[13]*float(q1_u0[2]&0xF000u) + yl[15]*float(q1_u0[3]&0xF000u);\n"
          @"        acc2_u0[0] = yh[0]*float(q2_u0[0]&0x000Fu) + yh[2]*float(q2_u0[1]&0x000Fu) + yh[4]*float(q2_u0[2]&0x000Fu) + yh[6]*float(q2_u0[3]&0x000Fu);\n"
          @"        acc2_u0[1] = yh[1]*float(q2_u0[0]&0x0F00u) + yh[3]*float(q2_u0[1]&0x0F00u) + yh[5]*float(q2_u0[2]&0x0F00u) + yh[7]*float(q2_u0[3]&0x0F00u);\n"
          @"        acc2_u0[2] = yh[8]*float(q2_u0[0]&0x00F0u) + yh[10]*float(q2_u0[1]&0x00F0u) + yh[12]*float(q2_u0[2]&0x00F0u) + yh[14]*float(q2_u0[3]&0x00F0u);\n"
          @"        acc2_u0[3] = yh[9]*float(q2_u0[0]&0xF000u) + yh[11]*float(q2_u0[1]&0xF000u) + yh[13]*float(q2_u0[2]&0xF000u) + yh[15]*float(q2_u0[3]&0xF000u);\n"
          @"        sum_up0 += float(dh_u0[0]) * ((acc1_u0[0] + (1.f/256.f) * acc1_u0[1]) * float(sc8_u0[0]) +\n"
          @"                                      (acc1_u0[2] + (1.f/256.f) * acc1_u0[3]) * float(sc8_u0[1]) * (1.f/16.f) +\n"
          @"                                      (acc2_u0[0] + (1.f/256.f) * acc2_u0[1]) * float(sc8_u0[4]) +\n"
          @"                                      (acc2_u0[2] + (1.f/256.f) * acc2_u0[3]) * float(sc8_u0[5]) * (1.f/16.f)) -\n"
          @"                   float(dh_u0[1]) * (sumy[0] * float(sc8_u0[2]) + sumy[1] * float(sc8_u0[3]) + sumy[2] * float(sc8_u0[6]) + sumy[3] * float(sc8_u0[7]));\n"
          @"        if (blk_g1 != nullptr) {\n"
          @"            device const block_q4_K* bg1 = blk_g1 + ib;\n"
          @"            device const uint16_t* sc_g1 = (device const uint16_t*)bg1->scales + iq;\n"
          @"            device const uint16_t* q1_g1 = (device const uint16_t*)bg1->qs + 16u * iq + 4u * ir;\n"
          @"            device const half* dh_g1 = (device const half*)&bg1->dm;\n"
          @"            sc16_g1[0] = sc_g1[0] & kmask1;\n"
          @"            sc16_g1[1] = sc_g1[2] & kmask1;\n"
          @"            sc16_g1[2] = ((sc_g1[4] >> 0) & kmask2) | ((sc_g1[0] & kmask3) >> 2);\n"
          @"            sc16_g1[3] = ((sc_g1[4] >> 4) & kmask2) | ((sc_g1[2] & kmask3) >> 2);\n"
          @"            device const uint16_t* q2_g1 = q1_g1 + 32;\n"
          @"            float4 acc1_g1 = {0.f, 0.f, 0.f, 0.f};\n"
          @"            float4 acc2_g1 = {0.f, 0.f, 0.f, 0.f};\n"
          @"            acc1_g1[0] = yl[0]*float(q1_g1[0]&0x000Fu) + yl[2]*float(q1_g1[1]&0x000Fu) + yl[4]*float(q1_g1[2]&0x000Fu) + yl[6]*float(q1_g1[3]&0x000Fu);\n"
          @"            acc1_g1[1] = yl[1]*float(q1_g1[0]&0x0F00u) + yl[3]*float(q1_g1[1]&0x0F00u) + yl[5]*float(q1_g1[2]&0x0F00u) + yl[7]*float(q1_g1[3]&0x0F00u);\n"
          @"            acc1_g1[2] = yl[8]*float(q1_g1[0]&0x00F0u) + yl[10]*float(q1_g1[1]&0x00F0u) + yl[12]*float(q1_g1[2]&0x00F0u) + yl[14]*float(q1_g1[3]&0x00F0u);\n"
          @"            acc1_g1[3] = yl[9]*float(q1_g1[0]&0xF000u) + yl[11]*float(q1_g1[1]&0xF000u) + yl[13]*float(q1_g1[2]&0xF000u) + yl[15]*float(q1_g1[3]&0xF000u);\n"
          @"            acc2_g1[0] = yh[0]*float(q2_g1[0]&0x000Fu) + yh[2]*float(q2_g1[1]&0x000Fu) + yh[4]*float(q2_g1[2]&0x000Fu) + yh[6]*float(q2_g1[3]&0x000Fu);\n"
          @"            acc2_g1[1] = yh[1]*float(q2_g1[0]&0x0F00u) + yh[3]*float(q2_g1[1]&0x0F00u) + yh[5]*float(q2_g1[2]&0x0F00u) + yh[7]*float(q2_g1[3]&0x0F00u);\n"
          @"            acc2_g1[2] = yh[8]*float(q2_g1[0]&0x00F0u) + yh[10]*float(q2_g1[1]&0x00F0u) + yh[12]*float(q2_g1[2]&0x00F0u) + yh[14]*float(q2_g1[3]&0x00F0u);\n"
          @"            acc2_g1[3] = yh[9]*float(q2_g1[0]&0xF000u) + yh[11]*float(q2_g1[1]&0xF000u) + yh[13]*float(q2_g1[2]&0xF000u) + yh[15]*float(q2_g1[3]&0xF000u);\n"
          @"            sum_gate1 += float(dh_g1[0]) * ((acc1_g1[0] + (1.f/256.f) * acc1_g1[1]) * float(sc8_g1[0]) +\n"
          @"                                            (acc1_g1[2] + (1.f/256.f) * acc1_g1[3]) * float(sc8_g1[1]) * (1.f/16.f) +\n"
          @"                                            (acc2_g1[0] + (1.f/256.f) * acc2_g1[1]) * float(sc8_g1[4]) +\n"
          @"                                            (acc2_g1[2] + (1.f/256.f) * acc2_g1[3]) * float(sc8_g1[5]) * (1.f/16.f)) -\n"
          @"                         float(dh_g1[1]) * (sumy[0] * float(sc8_g1[2]) + sumy[1] * float(sc8_g1[3]) + sumy[2] * float(sc8_g1[6]) + sumy[3] * float(sc8_g1[7]));\n"
          @"            device const block_q4_K* bu1 = blk_u1 + ib;\n"
          @"            device const uint16_t* sc_u1 = (device const uint16_t*)bu1->scales + iq;\n"
          @"            device const uint16_t* q1_u1 = (device const uint16_t*)bu1->qs + 16u * iq + 4u * ir;\n"
          @"            device const half* dh_u1 = (device const half*)&bu1->dm;\n"
          @"            sc16_u1[0] = sc_u1[0] & kmask1;\n"
          @"            sc16_u1[1] = sc_u1[2] & kmask1;\n"
          @"            sc16_u1[2] = ((sc_u1[4] >> 0) & kmask2) | ((sc_u1[0] & kmask3) >> 2);\n"
          @"            sc16_u1[3] = ((sc_u1[4] >> 4) & kmask2) | ((sc_u1[2] & kmask3) >> 2);\n"
          @"            device const uint16_t* q2_u1 = q1_u1 + 32;\n"
          @"            float4 acc1_u1 = {0.f, 0.f, 0.f, 0.f};\n"
          @"            float4 acc2_u1 = {0.f, 0.f, 0.f, 0.f};\n"
          @"            acc1_u1[0] = yl[0]*float(q1_u1[0]&0x000Fu) + yl[2]*float(q1_u1[1]&0x000Fu) + yl[4]*float(q1_u1[2]&0x000Fu) + yl[6]*float(q1_u1[3]&0x000Fu);\n"
          @"            acc1_u1[1] = yl[1]*float(q1_u1[0]&0x0F00u) + yl[3]*float(q1_u1[1]&0x0F00u) + yl[5]*float(q1_u1[2]&0x0F00u) + yl[7]*float(q1_u1[3]&0x0F00u);\n"
          @"            acc1_u1[2] = yl[8]*float(q1_u1[0]&0x00F0u) + yl[10]*float(q1_u1[1]&0x00F0u) + yl[12]*float(q1_u1[2]&0x00F0u) + yl[14]*float(q1_u1[3]&0x00F0u);\n"
          @"            acc1_u1[3] = yl[9]*float(q1_u1[0]&0xF000u) + yl[11]*float(q1_u1[1]&0xF000u) + yl[13]*float(q1_u1[2]&0xF000u) + yl[15]*float(q1_u1[3]&0xF000u);\n"
          @"            acc2_u1[0] = yh[0]*float(q2_u1[0]&0x000Fu) + yh[2]*float(q2_u1[1]&0x000Fu) + yh[4]*float(q2_u1[2]&0x000Fu) + yh[6]*float(q2_u1[3]&0x000Fu);\n"
          @"            acc2_u1[1] = yh[1]*float(q2_u1[0]&0x0F00u) + yh[3]*float(q2_u1[1]&0x0F00u) + yh[5]*float(q2_u1[2]&0x0F00u) + yh[7]*float(q2_u1[3]&0x0F00u);\n"
          @"            acc2_u1[2] = yh[8]*float(q2_u1[0]&0x00F0u) + yh[10]*float(q2_u1[1]&0x00F0u) + yh[12]*float(q2_u1[2]&0x00F0u) + yh[14]*float(q2_u1[3]&0x00F0u);\n"
          @"            acc2_u1[3] = yh[9]*float(q2_u1[0]&0xF000u) + yh[11]*float(q2_u1[1]&0xF000u) + yh[13]*float(q2_u1[2]&0xF000u) + yh[15]*float(q2_u1[3]&0xF000u);\n"
          @"            sum_up1 += float(dh_u1[0]) * ((acc1_u1[0] + (1.f/256.f) * acc1_u1[1]) * float(sc8_u1[0]) +\n"
          @"                                          (acc1_u1[2] + (1.f/256.f) * acc1_u1[3]) * float(sc8_u1[1]) * (1.f/16.f) +\n"
          @"                                          (acc2_u1[0] + (1.f/256.f) * acc2_u1[1]) * float(sc8_u1[4]) +\n"
          @"                                          (acc2_u1[2] + (1.f/256.f) * acc2_u1[3]) * float(sc8_u1[5]) * (1.f/16.f)) -\n"
          @"                       float(dh_u1[1]) * (sumy[0] * float(sc8_u1[2]) + sumy[1] * float(sc8_u1[3]) + sumy[2] * float(sc8_u1[6]) + sumy[3] * float(sc8_u1[7]));\n"
          @"        }\n"
          @"        y4 += 4u * 256u;\n"

          @"    }\n"
          @"    sum_gate0 = simd_sum(sum_gate0);\n"
          @"    sum_up0   = simd_sum(sum_up0);\n"
          @"    sum_gate1 = simd_sum(sum_gate1);\n"
          @"    sum_up1   = simd_sum(sum_up1);\n"
          @"    if (tiisg == 0) {\n"
          @"        float act0;\n"
          @"        if (activationKind == 2u) {\n"
          @"            constexpr float kGelu = 0.7978845608f;\n"
          @"            float g3 = sum_gate0 * sum_gate0 * sum_gate0;\n"
          @"            act0 = 0.5f * sum_gate0 * (1.0f + precise::tanh(kGelu * (sum_gate0 + 0.044715f * g3)));\n"
          @"        } else {\n"
          @"            act0 = sum_gate0 / (1.0f + precise::exp(-sum_gate0));\n"
          @"        }\n"
          @"        hb[(uint)tgid.y * N + first_row] = act0 * sum_up0;\n"
          @"        if (first_row + 1u < N) {\n"
          @"            float act1;\n"
          @"            if (activationKind == 2u) {\n"
          @"                constexpr float kGelu = 0.7978845608f;\n"
          @"                float g3 = sum_gate1 * sum_gate1 * sum_gate1;\n"
          @"                act1 = 0.5f * sum_gate1 * (1.0f + precise::tanh(kGelu * (sum_gate1 + 0.044715f * g3)));\n"
          @"            } else {\n"
          @"                act1 = sum_gate1 / (1.0f + precise::exp(-sum_gate1));\n"
          @"            }\n"
          @"            hb[(uint)tgid.y * N + first_row + 1u] = act1 * sum_up1;\n"
          @"        }\n"
          @"    }\n"
          @"}\n"
          @"\n"
          @"kernel void aljabr_ffn_gate_up_act_q4_k_mr8_kernel(\n"
          @"    device float* hb [[buffer(0)]],\n"
          @"    device const float* A [[buffer(1)]],\n"
          @"    device const block_q4_K* B_gate [[buffer(2)]],\n"
          @"    device const block_q4_K* B_up [[buffer(3)]],\n"
          @"    constant uint& K [[buffer(4)]],\n"
          @"    constant uint& N [[buffer(5)]],\n"
          @"    constant uint& activationKind [[buffer(6)]],\n"
          @"    uint2 tgid [[threadgroup_position_in_grid]],\n"
          @"    ushort2 tid [[thread_position_in_threadgroup]]) {\n"
          @"    const uint nb = K >> 8u;\n"
          @"    const uint sgitg = (uint)tid.x >> 5u;\n"
