          @"            acc2_u1[0] = yh[0]*float(q2_u1[0]&0x000Fu) + yh[2]*float(q2_u1[1]&0x000Fu) + yh[4]*float(q2_u1[2]&0x000Fu) + yh[6]*float(q2_u1[3]&0x000Fu);\n"
          @"            acc2_u1[1] = yh[1]*float(q2_u1[0]&0x0F00u) + yh[3]*float(q2_u1[1]&0x0F00u) + yh[5]*float(q2_u1[2]&0x0F00u) + yh[7]*float(q2_u1[3]&0x0F00u);\n"
          @"            acc2_u1[2] = yh[8]*float(q2_u1[0]&0x00F0u) + yh[10]*float(q2_u1[1]&0x00F0u) + yh[12]*float(q2_u1[2]&0x00F0u) + yh[14]*float(q2_u1[3]&0x00F0u);\n"
          @"            acc2_u1[3] = yh[9]*float(q2_u1[0]&0xF000u) + yh[11]*float(q2_u1[1]&0xF000u) + yh[13]*float(q2_u1[2]&0xF000u) + yh[15]*float(q2_u1[3]&0xF000u);\n"
          @"            sum_up1 += float(dh_u1[0]) * ((acc1_u1[0] + (1.f/256.f) * acc1_u1[1]) * float(sc8_u1[0]) +\n"
          @"                                          (acc1_u1[2] + (1.f/256.f) * acc1_u1[3]) * float(sc8_u1[1]) * (1.f/16.f) +\n"
          @"                                          (acc2_u1[0] + (1.f/256.f) * acc2_u1[1]) * float(sc8_u1[4]) +\n"
          @"                                          (acc2_u1[2] + (1.f/256.f) * acc2_u1[3]) * float(sc8_u1[5]) * (1.f/16.f)) -\n"
          @"                       float(dh_u1[1]) * (sumy[0] * float(sc8_u1[2]) + sumy[1] * float(sc8_u1[3]) + sumy[2] * float(sc8_u1[6]) + sumy[3] * float(sc8_u1[7]));\n"
          @"        }\n"
          @"        y4 += 4u * 256u;\n"
          @"    }\n"
          @"    sum_gate0 = simd_sum(sum_gate0);\n"
          @"    sum_up0   = simd_sum(sum_up0);\n"
          @"    sum_gate1 = simd_sum(sum_gate1);\n"
          @"    sum_up1   = simd_sum(sum_up1);\n"
          @"    if (tiisg == 0) {\n"
          @"        float act0;\n"
          @"        if (activationKind == 2u) {\n"
          @"            constexpr float kGelu = 0.7978845608f;\n"
          @"            float g3 = sum_gate0 * sum_gate0 * sum_gate0;\n"
          @"            act0 = 0.5f * sum_gate0 * (1.0f + precise::tanh(kGelu * (sum_gate0 + 0.044715f * g3)));\n"
          @"        } else {\n"
          @"            act0 = sum_gate0 / (1.0f + precise::exp(-sum_gate0));\n"
          @"        }\n"
          @"        hb[(uint)tgid.y * N + first_row] = act0 * sum_up0;\n"
          @"        if (first_row + 1u < N) {\n"
          @"            float act1;\n"
          @"            if (activationKind == 2u) {\n"
          @"                constexpr float kGelu = 0.7978845608f;\n"
          @"                float g3 = sum_gate1 * sum_gate1 * sum_gate1;\n"
          @"                act1 = 0.5f * sum_gate1 * (1.0f + precise::tanh(kGelu * (sum_gate1 + 0.044715f * g3)));\n"
          @"            } else {\n"
          @"                act1 = sum_gate1 / (1.0f + precise::exp(-sum_gate1));\n"
          @"            }\n"
          @"            hb[(uint)tgid.y * N + first_row + 1u] = act1 * sum_up1;\n"
          @"        }\n"
          @"    }\n"
          @"}\n"
          @"\n"
          @"/// ── 2-Token Batched Multi-row Q4_K: Tiled weight reuse across 2 tokens (zero-stack-spill, 100%% occupancy) ──\n"
          @"kernel void aljabr_matvec_tb_q4_k_b4_mr4_kernel(\n"
          @"    device float* C [[buffer(0)]],\n"
          @"    device const float* A [[buffer(1)]],\n"
          @"    device const block_q4_K* B [[buffer(2)]],\n"
          @"    constant uint& K [[buffer(3)]],\n"
          @"    constant uint& N [[buffer(4)]],\n"
          @"    constant uint& bSz [[buffer(5)]],\n"
          @"    uint2 tgid [[threadgroup_position_in_grid]],\n"
          @"    ushort2 tid [[thread_position_in_threadgroup]]) {\n"
          @"    const uint nb = K >> 8u;\n"
          @"    const uint sgitg = (uint)tid.x >> 5u;\n"
          @"    const ushort tiisg = tid.x & 31u;\n"
          @"    const uint first_row = tgid.x * 4u + sgitg * 2u;\n"
          @"    if (first_row >= N) return;\n"
          @"    const uint t_base = (uint)tgid.y * 2u;\n"
          @"    if (t_base >= bSz) return;\n"
          @"    const uint t0 = min(t_base + 0u, bSz - 1u);\n"
          @"    const uint t1 = min(t_base + 1u, bSz - 1u);\n"
          @"    device const float* A_0 = A + (uint)t0 * K;\n"
          @"    device const float* A_1 = A + (uint)t1 * K;\n"
          @"    device const block_q4_K* blk_row0 = B + first_row * nb;\n"
          @"    device const block_q4_K* blk_row1 = (first_row + 1u < N) ? (blk_row0 + nb) : nullptr;\n"
          @"    constexpr uint16_t kmask1 = 0x3f3f;\n"
          @"    constexpr uint16_t kmask2 = 0x0f0f;\n"
          @"    constexpr uint16_t kmask3 = 0xc0c0;\n"
          @"    const ushort ix = tiisg / 8u;\n"
          @"    const ushort it = tiisg %% 8u;\n"
          @"    const ushort iq = it / 4u;\n"
          @"    const ushort ir = it %% 4u;\n"
          @"    const uint y_off = (uint)ix * 256u + 64u * (uint)iq + 8u * (uint)ir;\n"
          @"    device const float* y4_0 = A_0 + y_off;\n"
          @"    device const float* y4_1 = A_1 + y_off;\n"
          @"    uint16_t sc16_0[4];\n"
          @"    thread const uint8_t* sc8_0 = (thread const uint8_t*)sc16_0;\n"
          @"    uint16_t sc16_1[4];\n"
          @"    thread const uint8_t* sc8_1 = (thread const uint8_t*)sc16_1;\n"
          @"    float sum0_0 = 0.0f, sum0_1 = 0.0f;\n"
          @"    float sum1_0 = 0.0f, sum1_1 = 0.0f;\n"
          @"    for (uint ib = ix; ib < nb; ib += 4u) {\n"
          @"        const float4 yl0_even = { y4_0[0], y4_0[2], y4_0[4], y4_0[6] };\n"
          @"        const float4 yl0_odd  = { y4_0[1], y4_0[3], y4_0[5], y4_0[7] };\n"
          @"        const float4 yl0_m8   = { y4_0[32], y4_0[34], y4_0[36], y4_0[38] };\n"
          @"        const float4 yl0_h8   = { y4_0[33], y4_0[35], y4_0[37], y4_0[39] };\n"
          @"        const float4 yh0_even = { y4_0[128], y4_0[130], y4_0[132], y4_0[134] };\n"
          @"        const float4 yh0_odd  = { y4_0[129], y4_0[131], y4_0[133], y4_0[135] };\n"
          @"        const float4 yh0_m8   = { y4_0[160], y4_0[162], y4_0[164], y4_0[166] };\n"
          @"        const float4 yh0_h8   = { y4_0[161], y4_0[163], y4_0[165], y4_0[167] };\n"
          @"        const float4 sumy0 = {\n"
          @"            yl0_even[0] + yl0_even[1] + yl0_even[2] + yl0_even[3] + yl0_odd[0] + yl0_odd[1] + yl0_odd[2] + yl0_odd[3],\n"
          @"            yl0_m8[0] + yl0_m8[1] + yl0_m8[2] + yl0_m8[3] + yl0_h8[0] + yl0_h8[1] + yl0_h8[2] + yl0_h8[3],\n"
          @"            yh0_even[0] + yh0_even[1] + yh0_even[2] + yh0_even[3] + yh0_odd[0] + yh0_odd[1] + yh0_odd[2] + yh0_odd[3],\n"
          @"            yh0_m8[0] + yh0_m8[1] + yh0_m8[2] + yh0_m8[3] + yh0_h8[0] + yh0_h8[1] + yh0_h8[2] + yh0_h8[3]\n"
          @"        };\n"
          @"        const float4 yl1_even = { y4_1[0], y4_1[2], y4_1[4], y4_1[6] };\n"
          @"        const float4 yl1_odd  = { y4_1[1], y4_1[3], y4_1[5], y4_1[7] };\n"
          @"        const float4 yl1_m8   = { y4_1[32], y4_1[34], y4_1[36], y4_1[38] };\n"
          @"        const float4 yl1_h8   = { y4_1[33], y4_1[35], y4_1[37], y4_1[39] };\n"
          @"        const float4 yh1_even = { y4_1[128], y4_1[130], y4_1[132], y4_1[134] };\n"
          @"        const float4 yh1_odd  = { y4_1[129], y4_1[131], y4_1[133], y4_1[135] };\n"
          @"        const float4 yh1_m8   = { y4_1[160], y4_1[162], y4_1[164], y4_1[166] };\n"
          @"        const float4 yh1_h8   = { y4_1[161], y4_1[163], y4_1[165], y4_1[167] };\n"
          @"        const float4 sumy1 = {\n"
          @"            yl1_even[0] + yl1_even[1] + yl1_even[2] + yl1_even[3] + yl1_odd[0] + yl1_odd[1] + yl1_odd[2] + yl1_odd[3],\n"
          @"            yl1_m8[0] + yl1_m8[1] + yl1_m8[2] + yl1_m8[3] + yl1_h8[0] + yl1_h8[1] + yl1_h8[2] + yl1_h8[3],\n"
          @"            yh1_even[0] + yh1_even[1] + yh1_even[2] + yh1_even[3] + yh1_odd[0] + yh1_odd[1] + yh1_odd[2] + yh1_odd[3],\n"
          @"            yh1_m8[0] + yh1_m8[1] + yh1_m8[2] + yh1_m8[3] + yh1_h8[0] + yh1_h8[1] + yh1_h8[2] + yh1_h8[3]\n"
          @"        };\n"
          @"        device const block_q4_K* blk0 = blk_row0 + ib;\n"
          @"        device const uint16_t* sc0 = (device const uint16_t*)blk0->scales + iq;\n"
          @"        device const uint16_t* q1_0 = (device const uint16_t*)blk0->qs + 16u * iq + 4u * ir;\n"
          @"        device const half* dh0 = (device const half*)&blk0->dm;\n"
          @"        sc16_0[0] = sc0[0] & kmask1;\n"
          @"        sc16_0[1] = sc0[2] & kmask1;\n"
          @"        sc16_0[2] = ((sc0[4] >> 0) & kmask2) | ((sc0[0] & kmask3) >> 2);\n"
          @"        sc16_0[3] = ((sc0[4] >> 4) & kmask2) | ((sc0[2] & kmask3) >> 2);\n"
          @"        device const uint16_t* q2_0 = q1_0 + 32;\n"
          @"        float4 q1_0_lo = {float(q1_0[0]&0x000Fu), float(q1_0[1]&0x000Fu), float(q1_0[2]&0x000Fu), float(q1_0[3]&0x000Fu)};\n"
          @"        float4 q1_0_hi = {float(q1_0[0]&0x0F00u), float(q1_0[1]&0x0F00u), float(q1_0[2]&0x0F00u), float(q1_0[3]&0x0F00u)};\n"
          @"        float4 q1_0_m8 = {float(q1_0[0]&0x00F0u), float(q1_0[1]&0x00F0u), float(q1_0[2]&0x00F0u), float(q1_0[3]&0x00F0u)};\n"
          @"        float4 q1_0_h8 = {float(q1_0[0]&0xF000u), float(q1_0[1]&0xF000u), float(q1_0[2]&0xF000u), float(q1_0[3]&0xF000u)};\n"
          @"        float4 q2_0_lo = {float(q2_0[0]&0x000Fu), float(q2_0[1]&0x000Fu), float(q2_0[2]&0x000Fu), float(q2_0[3]&0x000Fu)};\n"
          @"        float4 q2_0_hi = {float(q2_0[0]&0x0F00u), float(q2_0[1]&0x0F00u), float(q2_0[2]&0x0F00u), float(q2_0[3]&0x0F00u)};\n"
          @"        float4 q2_0_m8 = {float(q2_0[0]&0x00F0u), float(q2_0[1]&0x00F0u), float(q2_0[2]&0x00F0u), float(q2_0[3]&0x00F0u)};\n"
          @"        float4 q2_0_h8 = {float(q2_0[0]&0xF000u), float(q2_0[1]&0xF000u), float(q2_0[2]&0xF000u), float(q2_0[3]&0xF000u)};\n"
          @"        float d0_0 = float(dh0[0]);\n"
          @"        float d0_1 = float(dh0[1]);\n"
          @"        float sc8_0_0 = float(sc8_0[0]);\n"
          @"        float sc8_0_1 = float(sc8_0[1]) * (1.f/16.f);\n"
          @"        float sc8_0_4 = float(sc8_0[4]);\n"
          @"        float sc8_0_5 = float(sc8_0[5]) * (1.f/16.f);\n"
          @"        float sc8_0_2 = float(sc8_0[2]);\n"
          @"        float sc8_0_3 = float(sc8_0[3]);\n"
          @"        float sc8_0_6 = float(sc8_0[6]);\n"
          @"        float sc8_0_7 = float(sc8_0[7]);\n"
          @"        float4 a1_0_0 = {\n"
          @"            dot(yl0_even, q1_0_lo), dot(yl0_odd, q1_0_hi), dot(yl0_m8, q1_0_m8), dot(yl0_h8, q1_0_h8)\n"
          @"        };\n"
          @"        float4 a2_0_0 = {\n"
          @"            dot(yh0_even, q2_0_lo), dot(yh0_odd, q2_0_hi), dot(yh0_m8, q2_0_m8), dot(yh0_h8, q2_0_h8)\n"
          @"        };\n"
          @"        sum0_0 += d0_0 * ((a1_0_0[0] + (1.f/256.f) * a1_0_0[1]) * sc8_0_0 +\n"
          @"                          (a1_0_0[2] + (1.f/256.f) * a1_0_0[3]) * sc8_0_1 +\n"
          @"                          (a2_0_0[0] + (1.f/256.f) * a2_0_0[1]) * sc8_0_4 +\n"
          @"                          (a2_0_0[2] + (1.f/256.f) * a2_0_0[3]) * sc8_0_5) -\n"
          @"                  d0_1 * (sumy0[0] * sc8_0_2 + sumy0[1] * sc8_0_3 + sumy0[2] * sc8_0_6 + sumy0[3] * sc8_0_7);\n"
          @"        float4 a1_0_1 = {\n"
          @"            dot(yl1_even, q1_0_lo), dot(yl1_odd, q1_0_hi), dot(yl1_m8, q1_0_m8), dot(yl1_h8, q1_0_h8)\n"
          @"        };\n"
          @"        float4 a2_0_1 = {\n"
          @"            dot(yh1_even, q2_0_lo), dot(yh1_odd, q2_0_hi), dot(yh1_m8, q2_0_m8), dot(yh1_h8, q2_0_h8)\n"
          @"        };\n"
          @"        sum0_1 += d0_0 * ((a1_0_1[0] + (1.f/256.f) * a1_0_1[1]) * sc8_0_0 +\n"
          @"                          (a1_0_1[2] + (1.f/256.f) * a1_0_1[3]) * sc8_0_1 +\n"
          @"                          (a2_0_1[0] + (1.f/256.f) * a2_0_1[1]) * sc8_0_4 +\n"
          @"                          (a2_0_1[2] + (1.f/256.f) * a2_0_1[3]) * sc8_0_5) -\n"
          @"                  d0_1 * (sumy1[0] * sc8_0_2 + sumy1[1] * sc8_0_3 + sumy1[2] * sc8_0_6 + sumy1[3] * sc8_0_7);\n"
          @"        if (blk_row1 != nullptr) {\n"
          @"            device const block_q4_K* blk1 = blk_row1 + ib;\n"
          @"            device const uint16_t* sc1 = (device const uint16_t*)blk1->scales + iq;\n"
          @"            device const uint16_t* q1_1 = (device const uint16_t*)blk1->qs + 16u * iq + 4u * ir;\n"
          @"            device const half* dh1 = (device const half*)&blk1->dm;\n"
          @"            sc16_1[0] = sc1[0] & kmask1;\n"
          @"            sc16_1[1] = sc1[2] & kmask1;\n"
          @"            sc16_1[2] = ((sc1[4] >> 0) & kmask2) | ((sc1[0] & kmask3) >> 2);\n"
          @"            sc16_1[3] = ((sc1[4] >> 4) & kmask2) | ((sc1[2] & kmask3) >> 2);\n"
          @"            device const uint16_t* q2_1 = q1_1 + 32;\n"
          @"            float4 q1_1_lo = {float(q1_1[0]&0x000Fu), float(q1_1[1]&0x000Fu), float(q1_1[2]&0x000Fu), float(q1_1[3]&0x000Fu)};\n"
          @"            float4 q1_1_hi = {float(q1_1[0]&0x0F00u), float(q1_1[1]&0x0F00u), float(q1_1[2]&0x0F00u), float(q1_1[3]&0x0F00u)};\n"
          @"            float4 q1_1_m8 = {float(q1_1[0]&0x00F0u), float(q1_1[1]&0x00F0u), float(q1_1[2]&0x00F0u), float(q1_1[3]&0x00F0u)};\n"
          @"            float4 q1_1_h8 = {float(q1_1[0]&0xF000u), float(q1_1[1]&0xF000u), float(q1_1[2]&0xF000u), float(q1_1[3]&0xF000u)};\n"
          @"            float4 q2_1_lo = {float(q2_1[0]&0x000Fu), float(q2_1[1]&0x000Fu), float(q2_1[2]&0x000Fu), float(q2_1[3]&0x000Fu)};\n"
          @"            float4 q2_1_hi = {float(q2_1[0]&0x0F00u), float(q2_1[1]&0x0F00u), float(q2_1[2]&0x0F00u), float(q2_1[3]&0x0F00u)};\n"
          @"            float4 q2_1_m8 = {float(q2_1[0]&0x00F0u), float(q2_1[1]&0x00F0u), float(q2_1[2]&0x00F0u), float(q2_1[3]&0x00F0u)};\n"
          @"            float4 q2_1_h8 = {float(q2_1[0]&0xF000u), float(q2_1[1]&0xF000u), float(q2_1[2]&0xF000u), float(q2_1[3]&0xF000u)};\n"
          @"            float d1_0 = float(dh1[0]);\n"
          @"            float d1_1 = float(dh1[1]);\n"
          @"            float sc8_1_0 = float(sc8_1[0]);\n"
          @"            float sc8_1_1 = float(sc8_1[1]) * (1.f/16.f);\n"
          @"            float sc8_1_4 = float(sc8_1[4]);\n"
          @"            float sc8_1_5 = float(sc8_1[5]) * (1.f/16.f);\n"
          @"            float sc8_1_2 = float(sc8_1[2]);\n"
          @"            float sc8_1_3 = float(sc8_1[3]);\n"
          @"            float sc8_1_6 = float(sc8_1[6]);\n"
          @"            float sc8_1_7 = float(sc8_1[7]);\n"
          @"            float4 a1_1_0 = {\n"
          @"                dot(yl0_even, q1_1_lo), dot(yl0_odd, q1_1_hi), dot(yl0_m8, q1_1_m8), dot(yl0_h8, q1_1_h8)\n"
          @"            };\n"
          @"            float4 a2_1_0 = {\n"
          @"                dot(yh0_even, q2_1_lo), dot(yh0_odd, q2_1_hi), dot(yh0_m8, q2_1_m8), dot(yh0_h8, q2_1_h8)\n"
          @"            };\n"
          @"            sum1_0 += d1_0 * ((a1_1_0[0] + (1.f/256.f) * a1_1_0[1]) * sc8_1_0 +\n"
          @"                              (a1_1_0[2] + (1.f/256.f) * a1_1_0[3]) * sc8_1_1 +\n"
          @"                              (a2_1_0[0] + (1.f/256.f) * a2_1_0[1]) * sc8_1_4 +\n"
          @"                              (a2_1_0[2] + (1.f/256.f) * a2_1_0[3]) * sc8_1_5) -\n"
          @"                      d1_1 * (sumy0[0] * sc8_1_2 + sumy0[1] * sc8_1_3 + sumy0[2] * sc8_1_6 + sumy0[3] * sc8_1_7);\n"
          @"            float4 a1_1_1 = {\n"
          @"                dot(yl1_even, q1_1_lo), dot(yl1_odd, q1_1_hi), dot(yl1_m8, q1_1_m8), dot(yl1_h8, q1_1_h8)\n"
          @"            };\n"
          @"            float4 a2_1_1 = {\n"
          @"                dot(yh1_even, q2_1_lo), dot(yh1_odd, q2_1_hi), dot(yh1_m8, q2_1_m8), dot(yh1_h8, q2_1_h8)\n"
          @"            };\n"
          @"            sum1_1 += d1_0 * ((a1_1_1[0] + (1.f/256.f) * a1_1_1[1]) * sc8_1_0 +\n"
          @"                              (a1_1_1[2] + (1.f/256.f) * a1_1_1[3]) * sc8_1_1 +\n"
          @"                              (a2_1_1[0] + (1.f/256.f) * a2_1_1[1]) * sc8_1_4 +\n"
          @"                              (a2_1_1[2] + (1.f/256.f) * a2_1_1[3]) * sc8_1_5) -\n"
          @"                      d1_1 * (sumy1[0] * sc8_1_2 + sumy1[1] * sc8_1_3 + sumy1[2] * sc8_1_6 + sumy1[3] * sc8_1_7);\n"
          @"        }\n"
          @"        y4_0 += 4u * 256u;\n"
          @"        y4_1 += 4u * 256u;\n"
          @"    }\n"
          @"    sum0_0 = simd_sum(sum0_0);\n"
          @"    sum0_1 = simd_sum(sum0_1);\n"
          @"    sum1_0 = simd_sum(sum1_0);\n"
          @"    sum1_1 = simd_sum(sum1_1);\n"
          @"    if (tiisg == 0) {\n"
          @"        if (t_base + 0u < bSz) {\n"
          @"            C[(t_base + 0u) * N + first_row] = sum0_0;\n"
          @"            if (first_row + 1u < N) C[(t_base + 0u) * N + first_row + 1u] = sum1_0;\n"
          @"        }\n"
          @"        if (t_base + 1u < bSz) {\n"
          @"            C[(t_base + 1u) * N + first_row] = sum0_1;\n"
          @"            if (first_row + 1u < N) C[(t_base + 1u) * N + first_row + 1u] = sum1_1;\n"
          @"        }\n"
          @"    }\n"
          @"}\n"
          @"\n"
          @"// ── 2-Token Batched Fused Gate + Up + Activation Q4_K MR4 ──\n"
          @"kernel void aljabr_ffn_gate_up_act_q4_k_b4_mr4_kernel(\n"
          @"    device float* hb [[buffer(0)]],\n"
          @"    device const float* A [[buffer(1)]],\n"
          @"    device const block_q4_K* B_gate [[buffer(2)]],\n"
          @"    device const block_q4_K* B_up [[buffer(3)]],\n"
          @"    constant uint& K [[buffer(4)]],\n"
          @"    constant uint& N [[buffer(5)]],\n"
          @"    constant uint& activationKind [[buffer(6)]],\n"
          @"    constant uint& bSz [[buffer(7)]],\n"
          @"    uint2 tgid [[threadgroup_position_in_grid]],\n"
          @"    ushort2 tid [[thread_position_in_threadgroup]]) {\n"
          @"    const uint nb = K >> 8u;\n"
          @"    const uint sgitg = (uint)tid.x >> 5u;\n"
          @"    const ushort tiisg = tid.x & 31u;\n"
          @"    const uint first_row = tgid.x * 4u + sgitg * 2u;\n"
          @"    if (first_row >= N) return;\n"
          @"    const uint t_base = (uint)tgid.y * 2u;\n"
          @"    if (t_base >= bSz) return;\n"
          @"    const uint t0 = min(t_base + 0u, bSz - 1u);\n"
          @"    const uint t1 = min(t_base + 1u, bSz - 1u);\n"
          @"    device const float* A_0 = A + (uint)t0 * K;\n"
          @"    device const float* A_1 = A + (uint)t1 * K;\n"
          @"    device const block_q4_K* blk_g0 = B_gate + first_row * nb;\n"
          @"    device const block_q4_K* blk_u0 = B_up   + first_row * nb;\n"
          @"    device const block_q4_K* blk_g1 = (first_row + 1u < N) ? (blk_g0 + nb) : nullptr;\n"
          @"    device const block_q4_K* blk_u1 = (first_row + 1u < N) ? (blk_u0 + nb) : nullptr;\n"
          @"    constexpr uint16_t kmask1 = 0x3f3f;\n"
          @"    constexpr uint16_t kmask2 = 0x0f0f;\n"
          @"    constexpr uint16_t kmask3 = 0xc0c0;\n"
          @"    const ushort ix = tiisg / 8u;\n"
          @"    const ushort it = tiisg %% 8u;\n"
          @"    const ushort iq = it / 4u;\n"
          @"    const ushort ir = it %% 4u;\n"
          @"    const uint y_off = (uint)ix * 256u + 64u * (uint)iq + 8u * (uint)ir;\n"
          @"    device const float* y4_0 = A_0 + y_off;\n"
          @"    device const float* y4_1 = A_1 + y_off;\n"
          @"    uint16_t sc16_g0[4], sc16_u0[4];\n"
          @"    thread const uint8_t* sc8_g0 = (thread const uint8_t*)sc16_g0;\n"
          @"    thread const uint8_t* sc8_u0 = (thread const uint8_t*)sc16_u0;\n"
          @"    uint16_t sc16_g1[4], sc16_u1[4];\n"
          @"    thread const uint8_t* sc8_g1 = (thread const uint8_t*)sc16_g1;\n"
          @"    thread const uint8_t* sc8_u1 = (thread const uint8_t*)sc16_u1;\n"
          @"    float sum_gate0_0 = 0.0f, sum_gate0_1 = 0.0f;\n"
          @"    float sum_up0_0   = 0.0f, sum_up0_1   = 0.0f;\n"
          @"    float sum_gate1_0 = 0.0f, sum_gate1_1 = 0.0f;\n"
          @"    float sum_up1_0   = 0.0f, sum_up1_1   = 0.0f;\n"
          @"    for (uint ib = ix; ib < nb; ib += 4u) {\n"
          @"        const float4 yl0_even = { y4_0[0], y4_0[2], y4_0[4], y4_0[6] };\n"
          @"        const float4 yl0_odd  = { y4_0[1], y4_0[3], y4_0[5], y4_0[7] };\n"
          @"        const float4 yl0_m8   = { y4_0[32], y4_0[34], y4_0[36], y4_0[38] };\n"
          @"        const float4 yl0_h8   = { y4_0[33], y4_0[35], y4_0[37], y4_0[39] };\n"
          @"        const float4 yh0_even = { y4_0[128], y4_0[130], y4_0[132], y4_0[134] };\n"
          @"        const float4 yh0_odd  = { y4_0[129], y4_0[131], y4_0[133], y4_0[135] };\n"
          @"        const float4 yh0_m8   = { y4_0[160], y4_0[162], y4_0[164], y4_0[166] };\n"
          @"        const float4 yh0_h8   = { y4_0[161], y4_0[163], y4_0[165], y4_0[167] };\n"
          @"        const float4 sumy0 = {\n"
          @"            yl0_even[0] + yl0_even[1] + yl0_even[2] + yl0_even[3] + yl0_odd[0] + yl0_odd[1] + yl0_odd[2] + yl0_odd[3],\n"
          @"            yl0_m8[0] + yl0_m8[1] + yl0_m8[2] + yl0_m8[3] + yl0_h8[0] + yl0_h8[1] + yl0_h8[2] + yl0_h8[3],\n"
          @"            yh0_even[0] + yh0_even[1] + yh0_even[2] + yh0_even[3] + yh0_odd[0] + yh0_odd[1] + yh0_odd[2] + yh0_odd[3],\n"
          @"            yh0_m8[0] + yh0_m8[1] + yh0_m8[2] + yh0_m8[3] + yh0_h8[0] + yh0_h8[1] + yh0_h8[2] + yh0_h8[3]\n"
          @"        };\n"
          @"        const float4 yl1_even = { y4_1[0], y4_1[2], y4_1[4], y4_1[6] };\n"
          @"        const float4 yl1_odd  = { y4_1[1], y4_1[3], y4_1[5], y4_1[7] };\n"
          @"        const float4 yl1_m8   = { y4_1[32], y4_1[34], y4_1[36], y4_1[38] };\n"
          @"        const float4 yl1_h8   = { y4_1[33], y4_1[35], y4_1[37], y4_1[39] };\n"
          @"        const float4 yh1_even = { y4_1[128], y4_1[130], y4_1[132], y4_1[134] };\n"
          @"        const float4 yh1_odd  = { y4_1[129], y4_1[131], y4_1[133], y4_1[135] };\n"
          @"        const float4 yh1_m8   = { y4_1[160], y4_1[162], y4_1[164], y4_1[166] };\n"
          @"        const float4 yh1_h8   = { y4_1[161], y4_1[163], y4_1[165], y4_1[167] };\n"
          @"        const float4 sumy1 = {\n"
          @"            yl1_even[0] + yl1_even[1] + yl1_even[2] + yl1_even[3] + yl1_odd[0] + yl1_odd[1] + yl1_odd[2] + yl1_odd[3],\n"
          @"            yl1_m8[0] + yl1_m8[1] + yl1_m8[2] + yl1_m8[3] + yl1_h8[0] + yl1_h8[1] + yl1_h8[2] + yl1_h8[3],\n"
          @"            yh1_even[0] + yh1_even[1] + yh1_even[2] + yh1_even[3] + yh1_odd[0] + yh1_odd[1] + yh1_odd[2] + yh1_odd[3],\n"
          @"            yh1_m8[0] + yh1_m8[1] + yh1_m8[2] + yh1_m8[3] + yh1_h8[0] + yh1_h8[1] + yh1_h8[2] + yh1_h8[3]\n"
          @"        };\n"
          @"        // Gate Row 0\n"
          @"        device const block_q4_K* bg0 = blk_g0 + ib;\n"
          @"        device const uint16_t* sc_g0 = (device const uint16_t*)bg0->scales + iq;\n"
          @"        device const uint16_t* q1_g0 = (device const uint16_t*)bg0->qs + 16u * iq + 4u * ir;\n"
          @"        device const half* dh_g0 = (device const half*)&bg0->dm;\n"
          @"        sc16_g0[0] = sc_g0[0] & kmask1;\n"
          @"        sc16_g0[1] = sc_g0[2] & kmask1;\n"
          @"        sc16_g0[2] = ((sc_g0[4] >> 0) & kmask2) | ((sc_g0[0] & kmask3) >> 2);\n"
          @"        sc16_g0[3] = ((sc_g0[4] >> 4) & kmask2) | ((sc_g0[2] & kmask3) >> 2);\n"
          @"        device const uint16_t* q2_g0 = q1_g0 + 32;\n"
          @"        float4 q1_g0_lo = {float(q1_g0[0]&0x000Fu), float(q1_g0[1]&0x000Fu), float(q1_g0[2]&0x000Fu), float(q1_g0[3]&0x000Fu)};\n"
          @"        float4 q1_g0_hi = {float(q1_g0[0]&0x0F00u), float(q1_g0[1]&0x0F00u), float(q1_g0[2]&0x0F00u), float(q1_g0[3]&0x0F00u)};\n"
          @"        float4 q1_g0_m8 = {float(q1_g0[0]&0x00F0u), float(q1_g0[1]&0x00F0u), float(q1_g0[2]&0x00F0u), float(q1_g0[3]&0x00F0u)};\n"
          @"        float4 q1_g0_h8 = {float(q1_g0[0]&0xF000u), float(q1_g0[1]&0xF000u), float(q1_g0[2]&0xF000u), float(q1_g0[3]&0xF000u)};\n"
          @"        float4 q2_g0_lo = {float(q2_g0[0]&0x000Fu), float(q2_g0[1]&0x000Fu), float(q2_g0[2]&0x000Fu), float(q2_g0[3]&0x000Fu)};\n"
          @"        float4 q2_g0_hi = {float(q2_g0[0]&0x0F00u), float(q2_g0[1]&0x0F00u), float(q2_g0[2]&0x0F00u), float(q2_g0[3]&0x0F00u)};\n"
          @"        float4 q2_g0_m8 = {float(q2_g0[0]&0x00F0u), float(q2_g0[1]&0x00F0u), float(q2_g0[2]&0x00F0u), float(q2_g0[3]&0x00F0u)};\n"
          @"        float4 q2_g0_h8 = {float(q2_g0[0]&0xF000u), float(q2_g0[1]&0xF000u), float(q2_g0[2]&0xF000u), float(q2_g0[3]&0xF000u)};\n"
          @"        float dg0_0 = float(dh_g0[0]);\n"
          @"        float dg0_1 = float(dh_g0[1]);\n"
          @"        float sc8_g0_0 = float(sc8_g0[0]);\n"
          @"        float sc8_g0_1 = float(sc8_g0[1]) * (1.f/16.f);\n"
          @"        float sc8_g0_4 = float(sc8_g0[4]);\n"
          @"        float sc8_g0_5 = float(sc8_g0[5]) * (1.f/16.f);\n"
          @"        float sc8_g0_2 = float(sc8_g0[2]);\n"
          @"        float sc8_g0_3 = float(sc8_g0[3]);\n"
          @"        float sc8_g0_6 = float(sc8_g0[6]);\n"
          @"        float sc8_g0_7 = float(sc8_g0[7]);\n"
          @"        float4 a1_g0_0 = {\n"
          @"            dot(yl0_even, q1_g0_lo), dot(yl0_odd, q1_g0_hi), dot(yl0_m8, q1_g0_m8), dot(yl0_h8, q1_g0_h8)\n"
          @"        };\n"
          @"        float4 a2_g0_0 = {\n"
          @"            dot(yh0_even, q2_g0_lo), dot(yh0_odd, q2_g0_hi), dot(yh0_m8, q2_g0_m8), dot(yh0_h8, q2_g0_h8)\n"
          @"        };\n"
          @"        sum_gate0_0 += dg0_0 * ((a1_g0_0[0] + (1.f/256.f) * a1_g0_0[1]) * sc8_g0_0 +\n"
          @"                                (a1_g0_0[2] + (1.f/256.f) * a1_g0_0[3]) * sc8_g0_1 +\n"
          @"                                (a2_g0_0[0] + (1.f/256.f) * a2_g0_0[1]) * sc8_g0_4 +\n"
          @"                                (a2_g0_0[2] + (1.f/256.f) * a2_g0_0[3]) * sc8_g0_5) -\n"
          @"                       dg0_1 * (sumy0[0] * sc8_g0_2 + sumy0[1] * sc8_g0_3 + sumy0[2] * sc8_g0_6 + sumy0[3] * sc8_g0_7);\n"
          @"        float4 a1_g0_1 = {\n"
          @"            dot(yl1_even, q1_g0_lo), dot(yl1_odd, q1_g0_hi), dot(yl1_m8, q1_g0_m8), dot(yl1_h8, q1_g0_h8)\n"
          @"        };\n"
          @"        float4 a2_g0_1 = {\n"
          @"            dot(yh1_even, q2_g0_lo), dot(yh1_odd, q2_g0_hi), dot(yh1_m8, q2_g0_m8), dot(yh1_h8, q2_g0_h8)\n"
          @"        };\n"
          @"        sum_gate0_1 += dg0_0 * ((a1_g0_1[0] + (1.f/256.f) * a1_g0_1[1]) * sc8_g0_0 +\n"
          @"                                (a1_g0_1[2] + (1.f/256.f) * a1_g0_1[3]) * sc8_g0_1 +\n"
          @"                                (a2_g0_1[0] + (1.f/256.f) * a2_g0_1[1]) * sc8_g0_4 +\n"
          @"                                (a2_g0_1[2] + (1.f/256.f) * a2_g0_1[3]) * sc8_g0_5) -\n"
          @"                       dg0_1 * (sumy1[0] * sc8_g0_2 + sumy1[1] * sc8_g0_3 + sumy1[2] * sc8_g0_6 + sumy1[3] * sc8_g0_7);\n"
          @"        // Up Row 0\n"
          @"        device const block_q4_K* bu0 = blk_u0 + ib;\n"
          @"        device const uint16_t* sc_u0 = (device const uint16_t*)bu0->scales + iq;\n"
          @"        device const uint16_t* q1_u0 = (device const uint16_t*)bu0->qs + 16u * iq + 4u * ir;\n"
          @"        device const half* dh_u0 = (device const half*)&bu0->dm;\n"
          @"        sc16_u0[0] = sc_u0[0] & kmask1;\n"
          @"        sc16_u0[1] = sc_u0[2] & kmask1;\n"
          @"        sc16_u0[2] = ((sc_u0[4] >> 0) & kmask2) | ((sc_u0[0] & kmask3) >> 2);\n"
          @"        sc16_u0[3] = ((sc_u0[4] >> 4) & kmask2) | ((sc_u0[2] & kmask3) >> 2);\n"
          @"        device const uint16_t* q2_u0 = q1_u0 + 32;\n"
          @"        float4 q1_u0_lo = {float(q1_u0[0]&0x000Fu), float(q1_u0[1]&0x000Fu), float(q1_u0[2]&0x000Fu), float(q1_u0[3]&0x000Fu)};\n"
          @"        float4 q1_u0_hi = {float(q1_u0[0]&0x0F00u), float(q1_u0[1]&0x0F00u), float(q1_u0[2]&0x0F00u), float(q1_u0[3]&0x0F00u)};\n"
          @"        float4 q1_u0_m8 = {float(q1_u0[0]&0x00F0u), float(q1_u0[1]&0x00F0u), float(q1_u0[2]&0x00F0u), float(q1_u0[3]&0x00F0u)};\n"
          @"        float4 q1_u0_h8 = {float(q1_u0[0]&0xF000u), float(q1_u0[1]&0xF000u), float(q1_u0[2]&0xF000u), float(q1_u0[3]&0xF000u)};\n"
          @"        float4 q2_u0_lo = {float(q2_u0[0]&0x000Fu), float(q2_u0[1]&0x000Fu), float(q2_u0[2]&0x000Fu), float(q2_u0[3]&0x000Fu)};\n"
          @"        float4 q2_u0_hi = {float(q2_u0[0]&0x0F00u), float(q2_u0[1]&0x0F00u), float(q2_u0[2]&0x0F00u), float(q2_u0[3]&0x0F00u)};\n"
          @"        float4 q2_u0_m8 = {float(q2_u0[0]&0x00F0u), float(q2_u0[1]&0x00F0u), float(q2_u0[2]&0x00F0u), float(q2_u0[3]&0x00F0u)};\n"
          @"        float4 q2_u0_h8 = {float(q2_u0[0]&0xF000u), float(q2_u0[1]&0xF000u), float(q2_u0[2]&0xF000u), float(q2_u0[3]&0xF000u)};\n"
          @"        float du0_0 = float(dh_u0[0]);\n"
          @"        float du0_1 = float(dh_u0[1]);\n"
          @"        float sc8_u0_0 = float(sc8_u0[0]);\n"
          @"        float sc8_u0_1 = float(sc8_u0[1]) * (1.f/16.f);\n"
          @"        float sc8_u0_4 = float(sc8_u0[4]);\n"
          @"        float sc8_u0_5 = float(sc8_u0[5]) * (1.f/16.f);\n"
          @"        float sc8_u0_2 = float(sc8_u0[2]);\n"
          @"        float sc8_u0_3 = float(sc8_u0[3]);\n"
          @"        float sc8_u0_6 = float(sc8_u0[6]);\n"
          @"        float sc8_u0_7 = float(sc8_u0[7]);\n"
          @"        float4 a1_u0_0 = {\n"
          @"            dot(yl0_even, q1_u0_lo), dot(yl0_odd, q1_u0_hi), dot(yl0_m8, q1_u0_m8), dot(yl0_h8, q1_u0_h8)\n"
          @"        };\n"
          @"        float4 a2_u0_0 = {\n"
          @"            dot(yh0_even, q2_u0_lo), dot(yh0_odd, q2_u0_hi), dot(yh0_m8, q2_u0_m8), dot(yh0_h8, q2_u0_h8)\n"
          @"        };\n"
          @"        sum_up0_0 += du0_0 * ((a1_u0_0[0] + (1.f/256.f) * a1_u0_0[1]) * sc8_u0_0 +\n"
          @"                              (a1_u0_0[2] + (1.f/256.f) * a1_u0_0[3]) * sc8_u0_1 +\n"
          @"                              (a2_u0_0[0] + (1.f/256.f) * a2_u0_0[1]) * sc8_u0_4 +\n"
          @"                              (a2_u0_0[2] + (1.f/256.f) * a2_u0_0[3]) * sc8_u0_5) -\n"
          @"                     du0_1 * (sumy0[0] * sc8_u0_2 + sumy0[1] * sc8_u0_3 + sumy0[2] * sc8_u0_6 + sumy0[3] * sc8_u0_7);\n"
          @"        float4 a1_u0_1 = {\n"
          @"            dot(yl1_even, q1_u0_lo), dot(yl1_odd, q1_u0_hi), dot(yl1_m8, q1_u0_m8), dot(yl1_h8, q1_u0_h8)\n"
          @"        };\n"
          @"        float4 a2_u0_1 = {\n"
          @"            dot(yh1_even, q2_u0_lo), dot(yh1_odd, q2_u0_hi), dot(yh1_m8, q2_u0_m8), dot(yh1_h8, q2_u0_h8)\n"
          @"        };\n"
          @"        sum_up0_1 += du0_0 * ((a1_u0_1[0] + (1.f/256.f) * a1_u0_1[1]) * sc8_u0_0 +\n"
          @"                              (a1_u0_1[2] + (1.f/256.f) * a1_u0_1[3]) * sc8_u0_1 +\n"
          @"                              (a2_u0_1[0] + (1.f/256.f) * a2_u0_1[1]) * sc8_u0_4 +\n"
          @"                              (a2_u0_1[2] + (1.f/256.f) * a2_u0_1[3]) * sc8_u0_5) -\n"
          @"                     du0_1 * (sumy1[0] * sc8_u0_2 + sumy1[1] * sc8_u0_3 + sumy1[2] * sc8_u0_6 + sumy1[3] * sc8_u0_7);\n"
          @"        // Row 1\n"
          @"        if (blk_g1 != nullptr) {\n"
          @"            device const block_q4_K* bg1 = blk_g1 + ib;\n"
          @"            device const uint16_t* sc_g1 = (device const uint16_t*)bg1->scales + iq;\n"
          @"            device const uint16_t* q1_g1 = (device const uint16_t*)bg1->qs + 16u * iq + 4u * ir;\n"
          @"            device const half* dh_g1 = (device const half*)&bg1->dm;\n"
          @"            sc16_g1[0] = sc_g1[0] & kmask1;\n"
          @"            sc16_g1[1] = sc_g1[2] & kmask1;\n"
          @"            sc16_g1[2] = ((sc_g1[4] >> 0) & kmask2) | ((sc_g1[0] & kmask3) >> 2);\n"
          @"            sc16_g1[3] = ((sc_g1[4] >> 4) & kmask2) | ((sc_g1[2] & kmask3) >> 2);\n"
          @"            device const uint16_t* q2_g1 = q1_g1 + 32;\n"
          @"            float4 q1_g1_lo = {float(q1_g1[0]&0x000Fu), float(q1_g1[1]&0x000Fu), float(q1_g1[2]&0x000Fu), float(q1_g1[3]&0x000Fu)};\n"
          @"            float4 q1_g1_hi = {float(q1_g1[0]&0x0F00u), float(q1_g1[1]&0x0F00u), float(q1_g1[2]&0x0F00u), float(q1_g1[3]&0x0F00u)};\n"
          @"            float4 q1_g1_m8 = {float(q1_g1[0]&0x00F0u), float(q1_g1[1]&0x00F0u), float(q1_g1[2]&0x00F0u), float(q1_g1[3]&0x00F0u)};\n"
          @"            float4 q1_g1_h8 = {float(q1_g1[0]&0xF000u), float(q1_g1[1]&0xF000u), float(q1_g1[2]&0xF000u), float(q1_g1[3]&0xF000u)};\n"
          @"            float4 q2_g1_lo = {float(q2_g1[0]&0x000Fu), float(q2_g1[1]&0x000Fu), float(q2_g1[2]&0x000Fu), float(q2_g1[3]&0x000Fu)};\n"
          @"            float4 q2_g1_hi = {float(q2_g1[0]&0x0F00u), float(q2_g1[1]&0x0F00u), float(q2_g1[2]&0x0F00u), float(q2_g1[3]&0x0F00u)};\n"
          @"            float4 q2_g1_m8 = {float(q2_g1[0]&0x00F0u), float(q2_g1[1]&0x00F0u), float(q2_g1[2]&0x00F0u), float(q2_g1[3]&0x00F0u)};\n"
          @"            float4 q2_g1_h8 = {float(q2_g1[0]&0xF000u), float(q2_g1[1]&0xF000u), float(q2_g1[2]&0xF000u), float(q2_g1[3]&0xF000u)};\n"
          @"            float dg1_0 = float(dh_g1[0]);\n"
          @"            float dg1_1 = float(dh_g1[1]);\n"
          @"            float sc8_g1_0 = float(sc8_g1[0]);\n"
          @"            float sc8_g1_1 = float(sc8_g1[1]) * (1.f/16.f);\n"
          @"            float sc8_g1_4 = float(sc8_g1[4]);\n"
          @"            float sc8_g1_5 = float(sc8_g1[5]) * (1.f/16.f);\n"
          @"            float sc8_g1_2 = float(sc8_g1[2]);\n"
          @"            float sc8_g1_3 = float(sc8_g1[3]);\n"
          @"            float sc8_g1_6 = float(sc8_g1[6]);\n"
          @"            float sc8_g1_7 = float(sc8_g1[7]);\n"
          @"            float4 a1_g1_0 = {\n"
          @"                dot(yl0_even, q1_g1_lo), dot(yl0_odd, q1_g1_hi), dot(yl0_m8, q1_g1_m8), dot(yl0_h8, q1_g1_h8)\n"
          @"            };\n"
          @"            float4 a2_g1_0 = {\n"
          @"                dot(yh0_even, q2_g1_lo), dot(yh0_odd, q2_g1_hi), dot(yh0_m8, q2_g1_m8), dot(yh0_h8, q2_g1_h8)\n"
          @"            };\n"
          @"            sum_gate1_0 += dg1_0 * ((a1_g1_0[0] + (1.f/256.f) * a1_g1_0[1]) * sc8_g1_0 +\n"
          @"                                    (a1_g1_0[2] + (1.f/256.f) * a1_g1_0[3]) * sc8_g1_1 +\n"
          @"                                    (a2_g1_0[0] + (1.f/256.f) * a2_g1_0[1]) * sc8_g1_4 +\n"
          @"                                    (a2_g1_0[2] + (1.f/256.f) * a2_g1_0[3]) * sc8_g1_5) -\n"
          @"                           dg1_1 * (sumy0[0] * sc8_g1_2 + sumy0[1] * sc8_g1_3 + sumy0[2] * sc8_g1_6 + sumy0[3] * sc8_g1_7);\n"
          @"            float4 a1_g1_1 = {\n"
          @"                dot(yl1_even, q1_g1_lo), dot(yl1_odd, q1_g1_hi), dot(yl1_m8, q1_g1_m8), dot(yl1_h8, q1_g1_h8)\n"
          @"            };\n"
          @"            float4 a2_g1_1 = {\n"
          @"                dot(yh1_even, q2_g1_lo), dot(yh1_odd, q2_g1_hi), dot(yh1_m8, q2_g1_m8), dot(yh1_h8, q2_g1_h8)\n"
          @"            };\n"
          @"            sum_gate1_1 += dg1_0 * ((a1_g1_1[0] + (1.f/256.f) * a1_g1_1[1]) * sc8_g1_0 +\n"
          @"                                    (a1_g1_1[2] + (1.f/256.f) * a1_g1_1[3]) * sc8_g1_1 +\n"
          @"                                    (a2_g1_1[0] + (1.f/256.f) * a2_g1_1[1]) * sc8_g1_4 +\n"
          @"                                    (a2_g1_1[2] + (1.f/256.f) * a2_g1_1[3]) * sc8_g1_5) -\n"
          @"                           dg1_1 * (sumy1[0] * sc8_g1_2 + sumy1[1] * sc8_g1_3 + sumy1[2] * sc8_g1_6 + sumy1[3] * sc8_g1_7);\n"
          @"            device const block_q4_K* bu1 = blk_u1 + ib;\n"
          @"            device const uint16_t* sc_u1 = (device const uint16_t*)bu1->scales + iq;\n"
          @"            device const uint16_t* q1_u1 = (device const uint16_t*)bu1->qs + 16u * iq + 4u * ir;\n"
          @"            device const half* dh_u1 = (device const half*)&bu1->dm;\n"
          @"            sc16_u1[0] = sc_u1[0] & kmask1;\n"
          @"            sc16_u1[1] = sc_u1[2] & kmask1;\n"
          @"            sc16_u1[2] = ((sc_u1[4] >> 0) & kmask2) | ((sc_u1[0] & kmask3) >> 2);\n"
          @"            sc16_u1[3] = ((sc_u1[4] >> 4) & kmask2) | ((sc_u1[2] & kmask3) >> 2);\n"
          @"            device const uint16_t* q2_u1 = q1_u1 + 32;\n"
          @"            float4 q1_u1_lo = {float(q1_u1[0]&0x000Fu), float(q1_u1[1]&0x000Fu), float(q1_u1[2]&0x000Fu), float(q1_u1[3]&0x000Fu)};\n"
          @"            float4 q1_u1_hi = {float(q1_u1[0]&0x0F00u), float(q1_u1[1]&0x0F00u), float(q1_u1[2]&0x0F00u), float(q1_u1[3]&0x0F00u)};\n"
          @"            float4 q1_u1_m8 = {float(q1_u1[0]&0x00F0u), float(q1_u1[1]&0x00F0u), float(q1_u1[2]&0x00F0u), float(q1_u1[3]&0x00F0u)};\n"
          @"            float4 q1_u1_h8 = {float(q1_u1[0]&0xF000u), float(q1_u1[1]&0xF000u), float(q1_u1[2]&0xF000u), float(q1_u1[3]&0xF000u)};\n"
          @"            float4 q2_u1_lo = {float(q2_u1[0]&0x000Fu), float(q2_u1[1]&0x000Fu), float(q2_u1[2]&0x000Fu), float(q2_u1[3]&0x000Fu)};\n"
          @"            float4 q2_u1_hi = {float(q2_u1[0]&0x0F00u), float(q2_u1[1]&0x0F00u), float(q2_u1[2]&0x0F00u), float(q2_u1[3]&0x0F00u)};\n"
          @"            float4 q2_u1_m8 = {float(q2_u1[0]&0x00F0u), float(q2_u1[1]&0x00F0u), float(q2_u1[2]&0x00F0u), float(q2_u1[3]&0x00F0u)};\n"
          @"            float4 q2_u1_h8 = {float(q2_u1[0]&0xF000u), float(q2_u1[1]&0xF000u), float(q2_u1[2]&0xF000u), float(q2_u1[3]&0xF000u)};\n"
          @"            float du1_0 = float(dh_u1[0]);\n"
          @"            float du1_1 = float(dh_u1[1]);\n"
          @"            float sc8_u1_0 = float(sc8_u1[0]);\n"
          @"            float sc8_u1_1 = float(sc8_u1[1]) * (1.f/16.f);\n"
          @"            float sc8_u1_4 = float(sc8_u1[4]);\n"
          @"            float sc8_u1_5 = float(sc8_u1[5]) * (1.f/16.f);\n"
          @"            float sc8_u1_2 = float(sc8_u1[2]);\n"
          @"            float sc8_u1_3 = float(sc8_u1[3]);\n"
          @"            float sc8_u1_6 = float(sc8_u1[6]);\n"
          @"            float sc8_u1_7 = float(sc8_u1[7]);\n"
          @"            float4 a1_u1_0 = {\n"
          @"                dot(yl0_even, q1_u1_lo), dot(yl0_odd, q1_u1_hi), dot(yl0_m8, q1_u1_m8), dot(yl0_h8, q1_u1_h8)\n"
          @"            };\n"
          @"            float4 a2_u1_0 = {\n"
          @"                dot(yh0_even, q2_u1_lo), dot(yh0_odd, q2_u1_hi), dot(yh0_m8, q2_u1_m8), dot(yh0_h8, q2_u1_h8)\n"
          @"            };\n"
          @"            sum_up1_0 += du1_0 * ((a1_u1_0[0] + (1.f/256.f) * a1_u1_0[1]) * sc8_u1_0 +\n"
          @"                                  (a1_u1_0[2] + (1.f/256.f) * a1_u1_0[3]) * sc8_u1_1 +\n"
          @"                                  (a2_u1_0[0] + (1.f/256.f) * a2_u1_0[1]) * sc8_u1_4 +\n"
          @"                                  (a2_u1_0[2] + (1.f/256.f) * a2_u1_0[3]) * sc8_u1_5) -\n"
          @"                         du1_1 * (sumy0[0] * sc8_u1_2 + sumy0[1] * sc8_u1_3 + sumy0[2] * sc8_u1_6 + sumy0[3] * sc8_u1_7);\n"
          @"            float4 a1_u1_1 = {\n"
          @"                dot(yl1_even, q1_u1_lo), dot(yl1_odd, q1_u1_hi), dot(yl1_m8, q1_u1_m8), dot(yl1_h8, q1_u1_h8)\n"
          @"            };\n"
          @"            float4 a2_u1_1 = {\n"
          @"                dot(yh1_even, q2_u1_lo), dot(yh1_odd, q2_u1_hi), dot(yh1_m8, q2_u1_m8), dot(yh1_h8, q2_u1_h8)\n"
          @"            };\n"
          @"            sum_up1_1 += du1_0 * ((a1_u1_1[0] + (1.f/256.f) * a1_u1_1[1]) * sc8_u1_0 +\n"
          @"                                  (a1_u1_1[2] + (1.f/256.f) * a1_u1_1[3]) * sc8_u1_1 +\n"
          @"                                  (a2_u1_1[0] + (1.f/256.f) * a2_u1_1[1]) * sc8_u1_4 +\n"
          @"                                  (a2_u1_1[2] + (1.f/256.f) * a2_u1_1[3]) * sc8_u1_5) -\n"
          @"                         du1_1 * (sumy1[0] * sc8_u1_2 + sumy1[1] * sc8_u1_3 + sumy1[2] * sc8_u1_6 + sumy1[3] * sc8_u1_7);\n"
          @"        }\n"
          @"        y4_0 += 4u * 256u;\n"
          @"        y4_1 += 4u * 256u;\n"
          @"    }\n"
          @"    sum_gate0_0 = simd_sum(sum_gate0_0);\n"
          @"    sum_gate0_1 = simd_sum(sum_gate0_1);\n"
          @"    sum_up0_0   = simd_sum(sum_up0_0);\n"
          @"    sum_up0_1   = simd_sum(sum_up0_1);\n"
          @"    sum_gate1_0 = simd_sum(sum_gate1_0);\n"
          @"    sum_gate1_1 = simd_sum(sum_gate1_1);\n"
          @"    sum_up1_0   = simd_sum(sum_up1_0);\n"
          @"    sum_up1_1   = simd_sum(sum_up1_1);\n"
          @"    if (tiisg == 0) {\n"
          @"        if (t_base + 0u < bSz) {\n"
          @"            float act0 = (activationKind == 2u)\n"
          @"                ? (0.5f * sum_gate0_0 * (1.0f + precise::tanh(0.7978845608f * (sum_gate0_0 + 0.044715f * sum_gate0_0 * sum_gate0_0 * sum_gate0_0))))\n"
          @"                : (sum_gate0_0 / (1.0f + precise::exp(-sum_gate0_0)));\n"
          @"            hb[(t_base + 0u) * N + first_row] = act0 * sum_up0_0;\n"
          @"            if (first_row + 1u < N) {\n"
          @"                float act1 = (activationKind == 2u)\n"
          @"                    ? (0.5f * sum_gate1_0 * (1.0f + precise::tanh(0.7978845608f * (sum_gate1_0 + 0.044715f * sum_gate1_0 * sum_gate1_0 * sum_gate1_0))))\n"
          @"                    : (sum_gate1_0 / (1.0f + precise::exp(-sum_gate1_0)));\n"
          @"                hb[(t_base + 0u) * N + first_row + 1u] = act1 * sum_up1_0;\n"
          @"            }\n"
          @"        }\n"
          @"        if (t_base + 1u < bSz) {\n"
          @"            float act0 = (activationKind == 2u)\n"
          @"                ? (0.5f * sum_gate0_1 * (1.0f + precise::tanh(0.7978845608f * (sum_gate0_1 + 0.044715f * sum_gate0_1 * sum_gate0_1 * sum_gate0_1))))\n"
          @"                : (sum_gate0_1 / (1.0f + precise::exp(-sum_gate0_1)));\n"
          @"            hb[(t_base + 1u) * N + first_row] = act0 * sum_up0_1;\n"
          @"            if (first_row + 1u < N) {\n"
          @"                float act1 = (activationKind == 2u)\n"
          @"                    ? (0.5f * sum_gate1_1 * (1.0f + precise::tanh(0.7978845608f * (sum_gate1_1 + 0.044715f * sum_gate1_1 * sum_gate1_1 * sum_gate1_1))))\n"
          @"                    : (sum_gate1_1 / (1.0f + precise::exp(-sum_gate1_1)));\n"
          @"                hb[(t_base + 1u) * N + first_row + 1u] = act1 * sum_up1_1;\n"
          @"            }\n"
          @"        }\n"
          @"    }\n"
          @"}\n"
          @"\n"
          @"kernel void aljabr_matvec_tb_q6_k_kernel(\n"
          @"    device float* C [[buffer(0)]],\n"
          @"    device const float* A [[buffer(1)]],\n"
          @"    device const block_q6_K* B [[buffer(2)]],\n"
          @"    constant uint& K [[buffer(3)]],\n"
          @"    constant uint& N [[buffer(4)]],\n"
          @"    uint gid [[threadgroup_position_in_grid]],\n"
          @"    ushort tid [[thread_position_in_threadgroup]]) {\n"
          @"    if (gid >= N) return;\n"
          @"    const uint nb = K >> 8u;\n"
          @"    device const block_q6_K* x = B + gid * nb;\n"
          @"    float sum = 0.0f;\n"
          @"    const uint elem_start = tid << 3u;\n"
          @"    const uint h = elem_start >> 7u;\n"
          @"    const uint grp = (elem_start & 127u) >> 5u;\n"
          @"    const uint idx_base = elem_start & 31u;\n"
          @"    const uint sc_idx = elem_start >> 4u;\n"
          @"    const uint ql_base = (h << 6u) + ((grp & 1u) << 5u) + idx_base;\n"
          @"    const uint qh_base = (h << 5u) + idx_base;\n"
          @"    const uint shift_grp = grp << 1u;\n"
          @"    const bool is_low_ql = (grp < 2u);\n"
          @"\n"
          @"    for (uint ib = 0; ib < nb; ++ib) {\n"
          @"        const float d = float(x[ib].d);\n"
          @"        const float sc = float(x[ib].scales[sc_idx]);\n"
          @"        device const float* a = A + (ib << 8u) + elem_start;\n"
          @"\n"
          @"        float block_sum = 0.0f;\n"
          @"        for (uint i = 0; i < 8u; ++i) {\n"
          @"            const uint8_t ql_val = x[ib].ql[ql_base + i];\n"
          @"            const uint8_t lo = is_low_ql ? (ql_val & 0x0Fu) : (ql_val >> 4u);\n"
          @"            const uint8_t qh_val = x[ib].qh[qh_base + i];\n"
          @"            const uint8_t hi = (qh_val >> shift_grp) & 0x03u;\n"
          @"            const int8_t q = (int8_t)((lo | (hi << 4u)) - 32);\n"
          @"            block_sum += float(q) * a[i];\n"
          @"        }\n"
          @"        sum += d * sc * block_sum;\n"
          @"    }\n"
          @"    sum = simd_sum(sum);\n"
          @"    if (tid == 0) C[gid] = sum;\n"
          @"}\n"
          @"\n"
          @"kernel void aljabr_matvec_tb_q6_k_mr4_kernel(\n"
          @"    device float* C [[buffer(0)]],\n"
          @"    device const float* A [[buffer(1)]],\n"
          @"    device const block_q6_K* B [[buffer(2)]],\n"
          @"    constant uint& K [[buffer(3)]],\n"
          @"    constant uint& N [[buffer(4)]],\n"
          @"    uint2 tgid [[threadgroup_position_in_grid]],\n"
          @"    ushort2 tid [[thread_position_in_threadgroup]]) {\n"
          @"    const uint nb = K >> 8u;\n"
          @"    const uint sgitg = (uint)tid.x >> 5u;\n"
          @"    const ushort tiisg = tid.x & 31u;\n"
          @"    const uint first_row = tgid.x * 4u + sgitg * 2u;\n"
          @"    if (first_row >= N) return;\n"
          @"    device const float* A_t = A + (uint)tgid.y * K;\n"
          @"    device const block_q6_K* x0 = B + first_row * nb;\n"
          @"    device const block_q6_K* x1 = (first_row + 1u < N) ? (x0 + nb) : nullptr;\n"
          @"    constexpr uint8_t kmask1 = 0x03;\n"
          @"    constexpr uint8_t kmask2 = 0x0C;\n"
          @"    constexpr uint8_t kmask3 = 0x30;\n"
          @"    constexpr uint8_t kmask4 = 0xC0;\n"
          @"    const short s_tid = tiisg / 2;\n"
          @"    const short ix    = tiisg %% 2;\n"
          @"    const short ip    = s_tid / 8;\n"
          @"    const short il    = s_tid %% 8;\n"
          @"    const short l0    = 4 * il;\n"
          @"    const short is    = 8 * ip + l0 / 16;\n"
          @"    const short y_offset   = 128 * ip + l0;\n"
          @"    const short q_offset_l =  64 * ip + l0;\n"
          @"    const short q_offset_h =  32 * ip + l0;\n"
          @"    float sum0 = 0.0f;\n"
          @"    float sum1 = 0.0f;\n"
          @"    for (uint i = ix; i < nb; i += 2u) {\n"
          @"        device const float* y = A_t + i * 256u + y_offset;\n"
          @"        device const block_q6_K* blk0 = x0 + i;\n"
          @"        device const uint8_t* q1_0 = blk0->ql + q_offset_l;\n"
          @"        device const uint8_t* q2_0 = q1_0 + 32;\n"
          @"        device const uint8_t* qh_0 = blk0->qh + q_offset_h;\n"
          @"        device const int8_t*  sc_0 = blk0->scales + is;\n"
          @"        const float d0 = float(blk0->d);\n"
          @"        device const block_q6_K* blk1 = (x1 != nullptr) ? (x1 + i) : nullptr;\n"
          @"        device const uint8_t* q1_1 = blk1 ? (blk1->ql + q_offset_l) : nullptr;\n"
          @"        device const uint8_t* q2_1 = blk1 ? (q1_1 + 32) : nullptr;\n"
          @"        device const uint8_t* qh_1 = blk1 ? (blk1->qh + q_offset_h) : nullptr;\n"
          @"        device const int8_t*  sc_1 = blk1 ? (blk1->scales + is) : nullptr;\n"
          @"        const float d1 = blk1 ? float(blk1->d) : 0.0f;\n"
          @"        float4 sums0 = {0.f, 0.f, 0.f, 0.f};\n"
          @"        float4 sums1 = {0.f, 0.f, 0.f, 0.f};\n"
          @"        for (short l = 0; l < 4; ++l) {\n"
          @"            const float y_0 = y[l + 0];\n"
          @"            const float y_1 = y[l + 32];\n"
          @"            const float y_2 = y[l + 64];\n"
          @"            const float y_3 = y[l + 96];\n"
          @"            const uint8_t q1_0_l = q1_0[l], q2_0_l = q2_0[l], qh_0_l = qh_0[l];\n"
          @"            sums0[0] += y_0 * float((int8_t)((q1_0_l & 0xF) | ((qh_0_l & kmask1) << 4)) - 32);\n"
          @"            sums0[1] += y_1 * float((int8_t)((q2_0_l & 0xF) | ((qh_0_l & kmask2) << 2)) - 32);\n"
          @"            sums0[2] += y_2 * float((int8_t)((q1_0_l >> 4)  | ((qh_0_l & kmask3) << 0)) - 32);\n"
          @"            sums0[3] += y_3 * float((int8_t)((q2_0_l >> 4)  | ((qh_0_l & kmask4) >> 2)) - 32);\n"
          @"            if (blk1 != nullptr) {\n"
          @"                const uint8_t q1_1_l = q1_1[l], q2_1_l = q2_1[l], qh_1_l = qh_1[l];\n"
          @"                sums1[0] += y_0 * float((int8_t)((q1_1_l & 0xF) | ((qh_1_l & kmask1) << 4)) - 32);\n"
          @"                sums1[1] += y_1 * float((int8_t)((q2_1_l & 0xF) | ((qh_1_l & kmask2) << 2)) - 32);\n"
          @"                sums1[2] += y_2 * float((int8_t)((q1_1_l >> 4)  | ((qh_1_l & kmask3) << 0)) - 32);\n"
          @"                sums1[3] += y_3 * float((int8_t)((q2_1_l >> 4)  | ((qh_1_l & kmask4) >> 2)) - 32);\n"
          @"            }\n"
          @"        }\n"
          @"        sum0 += d0 * (sums0[0] * float(sc_0[0]) + sums0[1] * float(sc_0[2]) + sums0[2] * float(sc_0[4]) + sums0[3] * float(sc_0[6]));\n"
          @"        if (blk1 != nullptr) {\n"
          @"            sum1 += d1 * (sums1[0] * float(sc_1[0]) + sums1[1] * float(sc_1[2]) + sums1[2] * float(sc_1[4]) + sums1[3] * float(sc_1[6]));\n"
          @"        }\n"
          @"    }\n"
          @"    sum0 = simd_sum(sum0);\n"
          @"    sum1 = simd_sum(sum1);\n"
          @"    if (tiisg == 0) {\n"
          @"        C[(uint)tgid.y * N + first_row] = sum0;\n"
          @"        if (first_row + 1u < N) C[(uint)tgid.y * N + first_row + 1u] = sum1;\n"
          @"    }\n"
          @"}\n"
          @"\n"
          @"kernel void aljabr_matvec_tb_q6_k_mr8_kernel(\n"
          @"    device float* C [[buffer(0)]],\n"
          @"    device const float* A [[buffer(1)]],\n"
          @"    device const block_q6_K* B [[buffer(2)]],\n"
          @"    constant uint& K [[buffer(3)]],\n"
          @"    constant uint& N [[buffer(4)]],\n"
          @"    uint2 tgid [[threadgroup_position_in_grid]],\n"
          @"    ushort2 tid [[thread_position_in_threadgroup]]) {\n"
          @"    const uint nb = K >> 8u;\n"
          @"    const uint sgitg = (uint)tid.x >> 5u;\n"
          @"    const ushort tiisg = tid.x & 31u;\n"
          @"    const uint first_row = tgid.x * 8u + sgitg * 2u;\n"
          @"    if (first_row >= N) return;\n"
          @"    device const float* A_t = A + (uint)tgid.y * K;\n"
          @"    device const block_q6_K* x0 = B + first_row * nb;\n"
          @"    device const block_q6_K* x1 = (first_row + 1u < N) ? (x0 + nb) : nullptr;\n"
          @"    constexpr uint8_t kmask1 = 0x03;\n"
          @"    constexpr uint8_t kmask2 = 0x0C;\n"
          @"    constexpr uint8_t kmask3 = 0x30;\n"
          @"    constexpr uint8_t kmask4 = 0xC0;\n"
          @"    const short s_tid = tiisg / 2;\n"
          @"    const short ix    = tiisg %% 2;\n"
          @"    const short ip    = s_tid / 8;\n"
          @"    const short il    = s_tid %% 8;\n"
          @"    const short l0    = 4 * il;\n"
          @"    const short is    = 8 * ip + l0 / 16;\n"
          @"    const short y_offset   = 128 * ip + l0;\n"
          @"    const short q_offset_l =  64 * ip + l0;\n"
          @"    const short q_offset_h =  32 * ip + l0;\n"
          @"    float sum0 = 0.0f;\n"
          @"    float sum1 = 0.0f;\n"
          @"    for (uint i = ix; i < nb; i += 2u) {\n"
          @"        device const float* y = A_t + i * 256u + y_offset;\n"
          @"        device const block_q6_K* blk0 = x0 + i;\n"
          @"        device const uint8_t* q1_0 = blk0->ql + q_offset_l;\n"
          @"        device const uint8_t* q2_0 = q1_0 + 32;\n"
          @"        device const uint8_t* qh_0 = blk0->qh + q_offset_h;\n"
          @"        device const int8_t*  sc_0 = blk0->scales + is;\n"
          @"        const float d0 = float(blk0->d);\n"
          @"        device const block_q6_K* blk1 = (x1 != nullptr) ? (x1 + i) : nullptr;\n"
          @"        device const uint8_t* q1_1 = blk1 ? (blk1->ql + q_offset_l) : nullptr;\n"
          @"        device const uint8_t* q2_1 = blk1 ? (q1_1 + 32) : nullptr;\n"
          @"        device const uint8_t* qh_1 = blk1 ? (blk1->qh + q_offset_h) : nullptr;\n"
          @"        device const int8_t*  sc_1 = blk1 ? (blk1->scales + is) : nullptr;\n"
          @"        const float d1 = blk1 ? float(blk1->d) : 0.0f;\n"
          @"        float4 sums0 = {0.f, 0.f, 0.f, 0.f};\n"
          @"        float4 sums1 = {0.f, 0.f, 0.f, 0.f};\n"
          @"        for (short l = 0; l < 4; ++l) {\n"
          @"            const float y_0 = y[l + 0];\n"
          @"            const float y_1 = y[l + 32];\n"
          @"            const float y_2 = y[l + 64];\n"
          @"            const float y_3 = y[l + 96];\n"
          @"            const uint8_t q1_0_l = q1_0[l], q2_0_l = q2_0[l], qh_0_l = qh_0[l];\n"
          @"            sums0[0] += y_0 * float((int8_t)((q1_0_l & 0xF) | ((qh_0_l & kmask1) << 4)) - 32);\n"
          @"            sums0[1] += y_1 * float((int8_t)((q2_0_l & 0xF) | ((qh_0_l & kmask2) << 2)) - 32);\n"
          @"            sums0[2] += y_2 * float((int8_t)((q1_0_l >> 4)  | ((qh_0_l & kmask3) << 0)) - 32);\n"
          @"            sums0[3] += y_3 * float((int8_t)((q2_0_l >> 4)  | ((qh_0_l & kmask4) >> 2)) - 32);\n"
          @"            if (blk1 != nullptr) {\n"
          @"                const uint8_t q1_1_l = q1_1[l], q2_1_l = q2_1[l], qh_1_l = qh_1[l];\n"
          @"                sums1[0] += y_0 * float((int8_t)((q1_1_l & 0xF) | ((qh_1_l & kmask1) << 4)) - 32);\n"
          @"                sums1[1] += y_1 * float((int8_t)((q2_1_l & 0xF) | ((qh_1_l & kmask2) << 2)) - 32);\n"
          @"                sums1[2] += y_2 * float((int8_t)((q1_1_l >> 4)  | ((qh_1_l & kmask3) << 0)) - 32);\n"
          @"                sums1[3] += y_3 * float((int8_t)((q2_1_l >> 4)  | ((qh_1_l & kmask4) >> 2)) - 32);\n"
          @"            }\n"
          @"        }\n"
          @"        sum0 += d0 * (sums0[0] * float(sc_0[0]) + sums0[1] * float(sc_0[2]) + sums0[2] * float(sc_0[4]) + sums0[3] * float(sc_0[6]));\n"
          @"        if (blk1 != nullptr) {\n"
          @"            sum1 += d1 * (sums1[0] * float(sc_1[0]) + sums1[1] * float(sc_1[2]) + sums1[2] * float(sc_1[4]) + sums1[3] * float(sc_1[6]));\n"
          @"        }\n"
          @"    }\n"
          @"    sum0 = simd_sum(sum0);\n"
          @"    sum1 = simd_sum(sum1);\n"
          @"    if (tiisg == 0) {\n"
          @"        C[(uint)tgid.y * N + first_row] = sum0;\n"
          @"        if (first_row + 1u < N) C[(uint)tgid.y * N + first_row + 1u] = sum1;\n"
          @"    }\n"
          @"}\n"
          @"\n"
          @"// ── 2-Token Batched Q6_K Multi-Row (MR4) MatVec Kernel ───────────────\n"
          @"// Computes 4 output rows x 2 tokens per threadgroup (64 threads / 2 simdgroups).\n"
          @"// Register-resident design (<64 registers) ensures 100%% hardware occupancy and 2x bandwidth reduction.\n"
          @"kernel void aljabr_matvec_tb_q6_k_b4_mr4_kernel(\n"
          @"    device float* C [[buffer(0)]],\n"
          @"    device const float* A [[buffer(1)]],\n"
          @"    device const block_q6_K* B [[buffer(2)]],\n"
          @"    constant uint& K [[buffer(3)]],\n"
          @"    constant uint& N [[buffer(4)]],\n"
          @"    constant uint& bSz [[buffer(5)]],\n"
          @"    uint2 tgid [[threadgroup_position_in_grid]],\n"
          @"    ushort2 tid [[thread_position_in_threadgroup]]) {\n"
          @"    const uint nb = K >> 8u;\n"
          @"    const uint sgitg = (uint)tid.x >> 5u;\n"
          @"    const ushort tiisg = tid.x & 31u;\n"
          @"    const uint first_row = tgid.x * 4u + sgitg * 2u;\n"
          @"    if (first_row >= N) return;\n"
          @"    const uint t_base = (uint)tgid.y * 2u;\n"
          @"    if (t_base >= bSz) return;\n"
          @"    const uint t0 = min(t_base + 0u, bSz - 1u);\n"
          @"    const uint t1 = min(t_base + 1u, bSz - 1u);\n"
          @"    device const float* A_0 = A + (uint)t0 * K;\n"
          @"    device const float* A_1 = A + (uint)t1 * K;\n"
          @"    device const block_q6_K* x0 = B + first_row * nb;\n"
          @"    device const block_q6_K* x1 = (first_row + 1u < N) ? (x0 + nb) : nullptr;\n"
          @"    constexpr uint8_t kmask1 = 0x03;\n"
          @"    constexpr uint8_t kmask2 = 0x0C;\n"
          @"    constexpr uint8_t kmask3 = 0x30;\n"
          @"    constexpr uint8_t kmask4 = 0xC0;\n"
          @"    const short s_tid = tiisg / 2;\n"
          @"    const short ix    = tiisg %% 2;\n"
          @"    const short ip    = s_tid / 8;\n"
          @"    const short il    = s_tid %% 8;\n"
          @"    const short l0    = 4 * il;\n"
          @"    const short is    = 8 * ip + l0 / 16;\n"
          @"    const short y_offset   = 128 * ip + l0;\n"
          @"    const short q_offset_l =  64 * ip + l0;\n"
          @"    const short q_offset_h =  32 * ip + l0;\n"
          @"    float sum0_0 = 0.0f, sum0_1 = 0.0f;\n"
          @"    float sum1_0 = 0.0f, sum1_1 = 0.0f;\n"
          @"    for (uint i = ix; i < nb; i += 2u) {\n"
          @"        device const float* y0 = A_0 + i * 256u + y_offset;\n"
          @"        device const float* y1 = A_1 + i * 256u + y_offset;\n"
          @"        device const block_q6_K* blk0 = x0 + i;\n"
          @"        device const uint8_t* q1_0 = blk0->ql + q_offset_l;\n"
          @"        device const uint8_t* q2_0 = q1_0 + 32;\n"
          @"        device const uint8_t* qh_0 = blk0->qh + q_offset_h;\n"
          @"        device const int8_t*  sc_0 = blk0->scales + is;\n"
          @"        const float d0 = float(blk0->d);\n"
          @"        device const block_q6_K* blk1 = (x1 != nullptr) ? (x1 + i) : nullptr;\n"
          @"        device const uint8_t* q1_1 = blk1 ? (blk1->ql + q_offset_l) : nullptr;\n"
          @"        device const uint8_t* q2_1 = blk1 ? (q1_1 + 32) : nullptr;\n"
          @"        device const uint8_t* qh_1 = blk1 ? (blk1->qh + q_offset_h) : nullptr;\n"
          @"        device const int8_t*  sc_1 = blk1 ? (blk1->scales + is) : nullptr;\n"
          @"        const float d1 = blk1 ? float(blk1->d) : 0.0f;\n"
          @"        float4 sums0_0 = {0.f, 0.f, 0.f, 0.f};\n"
          @"        float4 sums0_1 = {0.f, 0.f, 0.f, 0.f};\n"
          @"        float4 sums1_0 = {0.f, 0.f, 0.f, 0.f};\n"
          @"        float4 sums1_1 = {0.f, 0.f, 0.f, 0.f};\n"
          @"        for (short l = 0; l < 4; ++l) {\n"
          @"            const float y0_0 = y0[l + 0];  const float y0_1 = y0[l + 32];  const float y0_2 = y0[l + 64];  const float y0_3 = y0[l + 96];\n"
          @"            const float y1_0 = y1[l + 0];  const float y1_1 = y1[l + 32];  const float y1_2 = y1[l + 64];  const float y1_3 = y1[l + 96];\n"
          @"            const uint8_t q1_l0 = q1_0[l];\n"
          @"            const uint8_t q2_l0 = q2_0[l];\n"
          @"            const uint8_t qh_l0 = qh_0[l];\n"
          @"            const float w0_0 = float((int8_t)((q1_l0 & 0xF) | ((qh_l0 & kmask1) << 4)) - 32);\n"
          @"            const float w1_0 = float((int8_t)((q2_l0 & 0xF) | ((qh_l0 & kmask2) << 2)) - 32);\n"
          @"            const float w2_0 = float((int8_t)((q1_l0 >> 4)  | ((qh_l0 & kmask3) << 0)) - 32);\n"
          @"            const float w3_0 = float((int8_t)((q2_l0 >> 4)  | ((qh_l0 & kmask4) >> 2)) - 32);\n"
          @"            sums0_0[0] += y0_0 * w0_0; sums0_0[1] += y0_1 * w1_0; sums0_0[2] += y0_2 * w2_0; sums0_0[3] += y0_3 * w3_0;\n"
          @"            sums0_1[0] += y1_0 * w0_0; sums0_1[1] += y1_1 * w1_0; sums0_1[2] += y1_2 * w2_0; sums0_1[3] += y1_3 * w3_0;\n"
          @"            if (blk1 != nullptr) {\n"
          @"                const uint8_t q1_l1 = q1_1[l];\n"
          @"                const uint8_t q2_l1 = q2_1[l];\n"
          @"                const uint8_t qh_l1 = qh_1[l];\n"
          @"                const float w0_1 = float((int8_t)((q1_l1 & 0xF) | ((qh_l1 & kmask1) << 4)) - 32);\n"
          @"                const float w1_1 = float((int8_t)((q2_l1 & 0xF) | ((qh_l1 & kmask2) << 2)) - 32);\n"
          @"                const float w2_1 = float((int8_t)((q1_l1 >> 4)  | ((qh_l1 & kmask3) << 0)) - 32);\n"
          @"                const float w3_1 = float((int8_t)((q2_l1 >> 4)  | ((qh_l1 & kmask4) >> 2)) - 32);\n"
          @"                sums1_0[0] += y0_0 * w0_1; sums1_0[1] += y0_1 * w1_1; sums1_0[2] += y0_2 * w2_1; sums1_0[3] += y0_3 * w3_1;\n"
          @"                sums1_1[0] += y1_0 * w0_1; sums1_1[1] += y1_1 * w1_1; sums1_1[2] += y1_2 * w2_1; sums1_1[3] += y1_3 * w3_1;\n"
          @"            }\n"
          @"        }\n"
          @"        const float sc0_0 = float(sc_0[0]), sc2_0 = float(sc_0[2]), sc4_0 = float(sc_0[4]), sc6_0 = float(sc_0[6]);\n"
          @"        sum0_0 += d0 * (sums0_0[0] * sc0_0 + sums0_0[1] * sc2_0 + sums0_0[2] * sc4_0 + sums0_0[3] * sc6_0);\n"
          @"        sum0_1 += d0 * (sums0_1[0] * sc0_0 + sums0_1[1] * sc2_0 + sums0_1[2] * sc4_0 + sums0_1[3] * sc6_0);\n"
          @"        if (blk1 != nullptr) {\n"
          @"            const float sc0_1 = float(sc_1[0]), sc2_1 = float(sc_1[2]), sc4_1 = float(sc_1[4]), sc6_1 = float(sc_1[6]);\n"
          @"            sum1_0 += d1 * (sums1_0[0] * sc0_1 + sums1_0[1] * sc2_1 + sums1_0[2] * sc4_1 + sums1_0[3] * sc6_1);\n"
          @"            sum1_1 += d1 * (sums1_1[0] * sc0_1 + sums1_1[1] * sc2_1 + sums1_1[2] * sc4_1 + sums1_1[3] * sc6_1);\n"
          @"        }\n"
          @"    }\n"
          @"    sum0_0 = simd_sum(sum0_0); sum0_1 = simd_sum(sum0_1);\n"
          @"    sum1_0 = simd_sum(sum1_0); sum1_1 = simd_sum(sum1_1);\n"
          @"    if (tiisg == 0) {\n"
          @"        if (t_base + 0u < bSz) { C[(t_base + 0u) * N + first_row] = sum0_0; if (first_row + 1u < N) C[(t_base + 0u) * N + first_row + 1u] = sum1_0; }\n"
          @"        if (t_base + 1u < bSz) { C[(t_base + 1u) * N + first_row] = sum0_1; if (first_row + 1u < N) C[(t_base + 1u) * N + first_row + 1u] = sum1_1; }\n"
          @"    }\n"
          @"}\n",
          (unsigned long)threads];
  NSMutableString *src = [NSMutableString stringWithString:base];
  aljabr_build_ffn_gate_up_act_q6_k_mr4_src(src, threads);
  aljabr_build_ffn_gate_up_act_q6_k_b4_mr4_src(src, threads);
  aljabr_build_q6_k_softcap_src(src);
  aljabr_build_q4_k_softcap_src(src);
  return src;
}

// ── Fused Q6_K Gate + Up + Activation (SwiGLU / GeGLU) MR4 kernel ──────
// Computes: hb[row] = activation(gate[row]) * up[row]  in one pass.
// Layout  : 64 threads / 2 simdgroups / 4 rows per threadgroup (mr4).
// gate and up are separate block_q6_K weight buffers.
static void aljabr_build_ffn_gate_up_act_q6_k_mr4_src(NSMutableString *src, NSUInteger threads) {
  (void)threads; // Q6_K fused kernel doesn't reference ALJABR_MATVEC_THREADS
  [src appendFormat:
    @"\nkernel void aljabr_ffn_gate_up_act_q6_k_mr4_kernel(\n"
    @"    device float* hb [[buffer(0)]],\n"
    @"    device const float* A [[buffer(1)]],\n"
    @"    device const block_q6_K* B_gate [[buffer(2)]],\n"
    @"    device const block_q6_K* B_up   [[buffer(3)]],\n"
    @"    constant uint& K [[buffer(4)]],\n"
    @"    constant uint& N [[buffer(5)]],\n"
    @"    constant uint& activationKind [[buffer(6)]],\n"
    @"    uint2 tgid [[threadgroup_position_in_grid]],\n"
    @"    ushort2 tid [[thread_position_in_threadgroup]]) {\n"
    @"    const uint nb = K >> 8u;\n"
    @"    const uint sgitg = (uint)tid.x >> 5u;\n"
    @"    const ushort tiisg = tid.x & 31u;\n"
    @"    const uint first_row = tgid.x * 4u + sgitg * 2u;\n"
    @"    if (first_row >= N) return;\n"
    @"    device const float* A_t = A + (uint)tgid.y * K;\n"
    @"    device const block_q6_K* xg0 = B_gate + first_row * nb;\n"
    @"    device const block_q6_K* xg1 = (first_row + 1u < N) ? (xg0 + nb) : nullptr;\n"
    @"    device const block_q6_K* xu0 = B_up + first_row * nb;\n"
    @"    device const block_q6_K* xu1 = (first_row + 1u < N) ? (xu0 + nb) : nullptr;\n"
    @"    constexpr uint8_t kmask1 = 0x03;\n"
    @"    constexpr uint8_t kmask2 = 0x0C;\n"
    @"    constexpr uint8_t kmask3 = 0x30;\n"
    @"    constexpr uint8_t kmask4 = 0xC0;\n"
    @"    const short s_tid = tiisg / 2;\n"
    @"    const short ix    = tiisg %% 2;\n"
    @"    const short ip    = s_tid / 8;\n"
    @"    const short il    = s_tid %% 8;\n"
    @"    const short l0    = 4 * il;\n"
    @"    const short is    = 8 * ip + l0 / 16;\n"
    @"    const short y_offset   = 128 * ip + l0;\n"
    @"    const short q_offset_l =  64 * ip + l0;\n"
    @"    const short q_offset_h =  32 * ip + l0;\n"
    @"    float g0 = 0.0f, g1 = 0.0f;\n"
    @"    float u0 = 0.0f, u1 = 0.0f;\n"
    @"    for (uint i = ix; i < nb; i += 2u) {\n"
    @"        device const float* y = A_t + i * 256u + y_offset;\n"
    @"        device const block_q6_K* blk_g0 = xg0 + i;\n"
    @"        device const uint8_t* q1_g0 = blk_g0->ql + q_offset_l;\n"
    @"        device const uint8_t* q2_g0 = q1_g0 + 32;\n"
    @"        device const uint8_t* qh_g0 = blk_g0->qh + q_offset_h;\n"
    @"        device const int8_t*  sc_g0 = blk_g0->scales + is;\n"
    @"        const float d_g0 = float(blk_g0->d);\n"
    @"        device const block_q6_K* blk_u0 = xu0 + i;\n"
    @"        device const uint8_t* q1_u0 = blk_u0->ql + q_offset_l;\n"
    @"        device const uint8_t* q2_u0 = q1_u0 + 32;\n"
    @"        device const uint8_t* qh_u0 = blk_u0->qh + q_offset_h;\n"
    @"        device const int8_t*  sc_u0 = blk_u0->scales + is;\n"
    @"        const float d_u0 = float(blk_u0->d);\n"
    @"        device const block_q6_K* blk_g1 = (xg1 != nullptr) ? (xg1 + i) : nullptr;\n"
    @"        device const uint8_t* q1_g1 = blk_g1 ? (blk_g1->ql + q_offset_l) : nullptr;\n"
    @"        device const uint8_t* q2_g1 = blk_g1 ? (q1_g1 + 32) : nullptr;\n"
    @"        device const uint8_t* qh_g1 = blk_g1 ? (blk_g1->qh + q_offset_h) : nullptr;\n"
    @"        device const int8_t*  sc_g1 = blk_g1 ? (blk_g1->scales + is) : nullptr;\n"
    @"        const float d_g1 = blk_g1 ? float(blk_g1->d) : 0.0f;\n"
    @"        device const block_q6_K* blk_u1 = (xu1 != nullptr) ? (xu1 + i) : nullptr;\n"
    @"        device const uint8_t* q1_u1 = blk_u1 ? (blk_u1->ql + q_offset_l) : nullptr;\n"
    @"        device const uint8_t* q2_u1 = blk_u1 ? (q1_u1 + 32) : nullptr;\n"
    @"        device const uint8_t* qh_u1 = blk_u1 ? (blk_u1->qh + q_offset_h) : nullptr;\n"
    @"        device const int8_t*  sc_u1 = blk_u1 ? (blk_u1->scales + is) : nullptr;\n"
    @"        const float d_u1 = blk_u1 ? float(blk_u1->d) : 0.0f;\n"
    @"        float4 sg0 = {0.f, 0.f, 0.f, 0.f};\n"
    @"        float4 su0 = {0.f, 0.f, 0.f, 0.f};\n"
    @"        float4 sg1 = {0.f, 0.f, 0.f, 0.f};\n"
    @"        float4 su1 = {0.f, 0.f, 0.f, 0.f};\n"
    @"        for (short l = 0; l < 4; ++l) {\n"
    @"            const float y_0 = y[l + 0];\n"
    @"            const float y_1 = y[l + 32];\n"
    @"            const float y_2 = y[l + 64];\n"
    @"            const float y_3 = y[l + 96];\n"
    @"            const uint8_t q1_g0_l = q1_g0[l], q2_g0_l = q2_g0[l], qh_g0_l = qh_g0[l];\n"
    @"            sg0[0] += y_0 * float((int8_t)((q1_g0_l & 0xF) | ((qh_g0_l & kmask1) << 4)) - 32);\n"
    @"            sg0[1] += y_1 * float((int8_t)((q2_g0_l & 0xF) | ((qh_g0_l & kmask2) << 2)) - 32);\n"
    @"            sg0[2] += y_2 * float((int8_t)((q1_g0_l >> 4)  | ((qh_g0_l & kmask3) << 0)) - 32);\n"
    @"            sg0[3] += y_3 * float((int8_t)((q2_g0_l >> 4)  | ((qh_g0_l & kmask4) >> 2)) - 32);\n"
    @"            const uint8_t q1_u0_l = q1_u0[l], q2_u0_l = q2_u0[l], qh_u0_l = qh_u0[l];\n"
    @"            su0[0] += y_0 * float((int8_t)((q1_u0_l & 0xF) | ((qh_u0_l & kmask1) << 4)) - 32);\n"
    @"            su0[1] += y_1 * float((int8_t)((q2_u0_l & 0xF) | ((qh_u0_l & kmask2) << 2)) - 32);\n"
    @"            su0[2] += y_2 * float((int8_t)((q1_u0_l >> 4)  | ((qh_u0_l & kmask3) << 0)) - 32);\n"
    @"            su0[3] += y_3 * float((int8_t)((q2_u0_l >> 4)  | ((qh_u0_l & kmask4) >> 2)) - 32);\n"
    @"            if (blk_g1 != nullptr) {\n"
    @"                const uint8_t q1_g1_l = q1_g1[l], q2_g1_l = q2_g1[l], qh_g1_l = qh_g1[l];\n"
    @"                sg1[0] += y_0 * float((int8_t)((q1_g1_l & 0xF) | ((qh_g1_l & kmask1) << 4)) - 32);\n"
    @"                sg1[1] += y_1 * float((int8_t)((q2_g1_l & 0xF) | ((qh_g1_l & kmask2) << 2)) - 32);\n"
    @"                sg1[2] += y_2 * float((int8_t)((q1_g1_l >> 4)  | ((qh_g1_l & kmask3) << 0)) - 32);\n"
    @"                sg1[3] += y_3 * float((int8_t)((q2_g1_l >> 4)  | ((qh_g1_l & kmask4) >> 2)) - 32);\n"
    @"                const uint8_t q1_u1_l = q1_u1[l], q2_u1_l = q2_u1[l], qh_u1_l = qh_u1[l];\n"
    @"                su1[0] += y_0 * float((int8_t)((q1_u1_l & 0xF) | ((qh_u1_l & kmask1) << 4)) - 32);\n"
    @"                su1[1] += y_1 * float((int8_t)((q2_u1_l & 0xF) | ((qh_u1_l & kmask2) << 2)) - 32);\n"
    @"                su1[2] += y_2 * float((int8_t)((q1_u1_l >> 4)  | ((qh_u1_l & kmask3) << 0)) - 32);\n"
    @"                su1[3] += y_3 * float((int8_t)((q2_u1_l >> 4)  | ((qh_u1_l & kmask4) >> 2)) - 32);\n"
    @"            }\n"
    @"        }\n"
    @"        g0 += d_g0 * (sg0[0] * float(sc_g0[0]) + sg0[1] * float(sc_g0[2]) + sg0[2] * float(sc_g0[4]) + sg0[3] * float(sc_g0[6]));\n"
    @"        u0 += d_u0 * (su0[0] * float(sc_u0[0]) + su0[1] * float(sc_u0[2]) + su0[2] * float(sc_u0[4]) + su0[3] * float(sc_u0[6]));\n"
    @"        if (blk_g1 != nullptr) {\n"
    @"            g1 += d_g1 * (sg1[0] * float(sc_g1[0]) + sg1[1] * float(sc_g1[2]) + sg1[2] * float(sc_g1[4]) + sg1[3] * float(sc_g1[6]));\n"
    @"            u1 += d_u1 * (su1[0] * float(sc_u1[0]) + su1[1] * float(sc_u1[2]) + su1[2] * float(sc_u1[4]) + su1[3] * float(sc_u1[6]));\n"
    @"        }\n"
    @"    }\n"
    @"    g0 = simd_sum(g0);  u0 = simd_sum(u0);\n"
    @"    g1 = simd_sum(g1);  u1 = simd_sum(u1);\n"
    @"    if (tiisg == 0) {\n"
    @"        float act0;\n"
    @"        if (activationKind == 2u) {\n"
    @"            constexpr float kGelu = 0.7978845608f;\n"
    @"            float g3 = g0 * g0 * g0;\n"
    @"            act0 = 0.5f * g0 * (1.0f + precise::tanh(kGelu * (g0 + 0.044715f * g3)));\n"
    @"        } else {\n"
    @"            act0 = g0 / (1.0f + precise::exp(-g0));\n"
    @"        }\n"
    @"        hb[(uint)tgid.y * N + first_row] = act0 * u0;\n"
    @"        if (first_row + 1u < N) {\n"
    @"            float act1;\n"
    @"            if (activationKind == 2u) {\n"
    @"                constexpr float kGelu = 0.7978845608f;\n"
    @"                float g3 = g1 * g1 * g1;\n"
    @"                act1 = 0.5f * g1 * (1.0f + precise::tanh(kGelu * (g1 + 0.044715f * g3)));\n"
    @"            } else {\n"
    @"                act1 = g1 / (1.0f + precise::exp(-g1));\n"
    @"            }\n"
    @"            hb[(uint)tgid.y * N + first_row + 1u] = act1 * u1;\n"
    @"        }\n"
    @"    }\n"
    @"}\n"];
}

// ── 2-Token Batched Fused Q6_K Gate + Up + Activation (SwiGLU / GeGLU) MR4 kernel ──
static void aljabr_build_ffn_gate_up_act_q6_k_b4_mr4_src(NSMutableString *src, NSUInteger threads) {
  (void)threads;
  [src appendFormat:
    @"\nkernel void aljabr_ffn_gate_up_act_q6_k_b4_mr4_kernel(\n"
    @"    device float* hb [[buffer(0)]],\n"
    @"    device const float* A [[buffer(1)]],\n"
    @"    device const block_q6_K* B_gate [[buffer(2)]],\n"
    @"    device const block_q6_K* B_up   [[buffer(3)]],\n"
    @"    constant uint& K [[buffer(4)]],\n"
    @"    constant uint& N [[buffer(5)]],\n"
    @"    constant uint& activationKind [[buffer(6)]],\n"
    @"    constant uint& bSz [[buffer(7)]],\n"
    @"    uint2 tgid [[threadgroup_position_in_grid]],\n"
    @"    ushort2 tid [[thread_position_in_threadgroup]]) {\n"
    @"    const uint nb = K >> 8u;\n"
    @"    const uint sgitg = (uint)tid.x >> 5u;\n"
    @"    const ushort tiisg = tid.x & 31u;\n"
    @"    const uint first_row = tgid.x * 4u + sgitg * 2u;\n"
    @"    if (first_row >= N) return;\n"
    @"    const uint t_base = (uint)tgid.y * 2u;\n"
    @"    if (t_base >= bSz) return;\n"
    @"    const uint t0 = min(t_base + 0u, bSz - 1u);\n"
    @"    const uint t1 = min(t_base + 1u, bSz - 1u);\n"
    @"    device const float* A_0 = A + (uint)t0 * K;\n"
    @"    device const float* A_1 = A + (uint)t1 * K;\n"
    @"    device const block_q6_K* xg0 = B_gate + first_row * nb;\n"
    @"    device const block_q6_K* xg1 = (first_row + 1u < N) ? (xg0 + nb) : nullptr;\n"
    @"    device const block_q6_K* xu0 = B_up   + first_row * nb;\n"
    @"    device const block_q6_K* xu1 = (first_row + 1u < N) ? (xu0 + nb) : nullptr;\n"
    @"    constexpr uint8_t kmask1 = 0x03;\n"
    @"    constexpr uint8_t kmask2 = 0x0C;\n"
    @"    constexpr uint8_t kmask3 = 0x30;\n"
    @"    constexpr uint8_t kmask4 = 0xC0;\n"
    @"    const short s_tid = tiisg / 2;\n"
    @"    const short ix    = tiisg %% 2;\n"
    @"    const short ip    = s_tid / 8;\n"
    @"    const short il    = s_tid %% 8;\n"
    @"    const short l0    = 4 * il;\n"
    @"    const short is    = 8 * ip + l0 / 16;\n"
    @"    const short y_offset   = 128 * ip + l0;\n"
    @"    const short q_offset_l =  64 * ip + l0;\n"
    @"    const short q_offset_h =  32 * ip + l0;\n"
    @"    float g0_0 = 0.0f, g0_1 = 0.0f;\n"
    @"    float u0_0 = 0.0f, u0_1 = 0.0f;\n"
    @"    float g1_0 = 0.0f, g1_1 = 0.0f;\n"
    @"    float u1_0 = 0.0f, u1_1 = 0.0f;\n"
    @"    for (uint i = ix; i < nb; i += 2u) {\n"
    @"        device const float* y0 = A_0 + i * 256u + y_offset;\n"
    @"        device const float* y1 = A_1 + i * 256u + y_offset;\n"
    @"        device const block_q6_K* blk_g0 = xg0 + i;\n"
    @"        device const uint8_t* q1_g0 = blk_g0->ql + q_offset_l;\n"
    @"        device const uint8_t* q2_g0 = q1_g0 + 32;\n"
    @"        device const uint8_t* qh_g0 = blk_g0->qh + q_offset_h;\n"
    @"        device const int8_t*  sc_g0 = blk_g0->scales + is;\n"
    @"        const float d_g0 = float(blk_g0->d);\n"
    @"        device const block_q6_K* blk_u0 = xu0 + i;\n"
    @"        device const uint8_t* q1_u0 = blk_u0->ql + q_offset_l;\n"
    @"        device const uint8_t* q2_u0 = q1_u0 + 32;\n"
    @"        device const uint8_t* qh_u0 = blk_u0->qh + q_offset_h;\n"
    @"        device const int8_t*  sc_u0 = blk_u0->scales + is;\n"
    @"        const float d_u0 = float(blk_u0->d);\n"
    @"        device const block_q6_K* blk_g1 = xg1 ? (xg1 + i) : nullptr;\n"
    @"        device const uint8_t* q1_g1 = blk_g1 ? (blk_g1->ql + q_offset_l) : nullptr;\n"
    @"        device const uint8_t* q2_g1 = blk_g1 ? (q1_g1 + 32) : nullptr;\n"
    @"        device const uint8_t* qh_g1 = blk_g1 ? (blk_g1->qh + q_offset_h) : nullptr;\n"
    @"        device const int8_t*  sc_g1 = blk_g1 ? (blk_g1->scales + is) : nullptr;\n"
    @"        const float d_g1 = blk_g1 ? float(blk_g1->d) : 0.0f;\n"
    @"        device const block_q6_K* blk_u1 = xu1 ? (xu1 + i) : nullptr;\n"
    @"        device const uint8_t* q1_u1 = blk_u1 ? (blk_u1->ql + q_offset_l) : nullptr;\n"
    @"        device const uint8_t* q2_u1 = blk_u1 ? (q1_u1 + 32) : nullptr;\n"
    @"        device const uint8_t* qh_u1 = blk_u1 ? (blk_u1->qh + q_offset_h) : nullptr;\n"
    @"        device const int8_t*  sc_u1 = blk_u1 ? (blk_u1->scales + is) : nullptr;\n"
    @"        const float d_u1 = blk_u1 ? float(blk_u1->d) : 0.0f;\n"
    @"        float4 sg0_0 = {0.f, 0.f, 0.f, 0.f}, sg0_1 = {0.f, 0.f, 0.f, 0.f};\n"
    @"        float4 su0_0 = {0.f, 0.f, 0.f, 0.f}, su0_1 = {0.f, 0.f, 0.f, 0.f};\n"
    @"        float4 sg1_0 = {0.f, 0.f, 0.f, 0.f}, sg1_1 = {0.f, 0.f, 0.f, 0.f};\n"
    @"        float4 su1_0 = {0.f, 0.f, 0.f, 0.f}, su1_1 = {0.f, 0.f, 0.f, 0.f};\n"
    @"        for (short l = 0; l < 4; ++l) {\n"
    @"            const float y0_0 = y0[l + 0];  const float y0_1 = y0[l + 32];  const float y0_2 = y0[l + 64];  const float y0_3 = y0[l + 96];\n"
    @"            const float y1_0 = y1[l + 0];  const float y1_1 = y1[l + 32];  const float y1_2 = y1[l + 64];  const float y1_3 = y1[l + 96];\n"
    @"            const uint8_t q1_g0_l = q1_g0[l], q2_g0_l = q2_g0[l], qh_g0_l = qh_g0[l];\n"
    @"            const float wg0_0 = float((int8_t)((q1_g0_l & 0xF) | ((qh_g0_l & kmask1) << 4)) - 32);\n"
    @"            const float wg0_1 = float((int8_t)((q2_g0_l & 0xF) | ((qh_g0_l & kmask2) << 2)) - 32);\n"
    @"            const float wg0_2 = float((int8_t)((q1_g0_l >> 4)  | ((qh_g0_l & kmask3) << 0)) - 32);\n"
    @"            const float wg0_3 = float((int8_t)((q2_g0_l >> 4)  | ((qh_g0_l & kmask4) >> 2)) - 32);\n"
    @"            sg0_0[0] += y0_0 * wg0_0; sg0_0[1] += y0_1 * wg0_1; sg0_0[2] += y0_2 * wg0_2; sg0_0[3] += y0_3 * wg0_3;\n"
    @"            sg0_1[0] += y1_0 * wg0_0; sg0_1[1] += y1_1 * wg0_1; sg0_1[2] += y1_2 * wg0_2; sg0_1[3] += y1_3 * wg0_3;\n"
    @"            const uint8_t q1_u0_l = q1_u0[l], q2_u0_l = q2_u0[l], qh_u0_l = qh_u0[l];\n"
    @"            const float wu0_0 = float((int8_t)((q1_u0_l & 0xF) | ((qh_u0_l & kmask1) << 4)) - 32);\n"
    @"            const float wu0_1 = float((int8_t)((q2_u0_l & 0xF) | ((qh_u0_l & kmask2) << 2)) - 32);\n"
    @"            const float wu0_2 = float((int8_t)((q1_u0_l >> 4)  | ((qh_u0_l & kmask3) << 0)) - 32);\n"
    @"            const float wu0_3 = float((int8_t)((q2_u0_l >> 4)  | ((qh_u0_l & kmask4) >> 2)) - 32);\n"
    @"            su0_0[0] += y0_0 * wu0_0; su0_0[1] += y0_1 * wu0_1; su0_0[2] += y0_2 * wu0_2; su0_0[3] += y0_3 * wu0_3;\n"
    @"            su0_1[0] += y1_0 * wu0_0; su0_1[1] += y1_1 * wu0_1; su0_1[2] += y1_2 * wu0_2; su0_1[3] += y1_3 * wu0_3;\n"
    @"            if (blk_g1 != nullptr) {\n"
    @"                const uint8_t q1_g1_l = q1_g1[l], q2_g1_l = q2_g1[l], qh_g1_l = qh_g1[l];\n"
    @"                const float wg1_0 = float((int8_t)((q1_g1_l & 0xF) | ((qh_g1_l & kmask1) << 4)) - 32);\n"
    @"                const float wg1_1 = float((int8_t)((q2_g1_l & 0xF) | ((qh_g1_l & kmask2) << 2)) - 32);\n"
    @"                const float wg1_2 = float((int8_t)((q1_g1_l >> 4)  | ((qh_g1_l & kmask3) << 0)) - 32);\n"
    @"                const float wg1_3 = float((int8_t)((q2_g1_l >> 4)  | ((qh_g1_l & kmask4) >> 2)) - 32);\n"
    @"                sg1_0[0] += y0_0 * wg1_0; sg1_0[1] += y0_1 * wg1_1; sg1_0[2] += y0_2 * wg1_2; sg1_0[3] += y0_3 * wg1_3;\n"
    @"                sg1_1[0] += y1_0 * wg1_0; sg1_1[1] += y1_1 * wg1_1; sg1_1[2] += y1_2 * wg1_2; sg1_1[3] += y1_3 * wg1_3;\n"
    @"                const uint8_t q1_u1_l = q1_u1[l], q2_u1_l = q2_u1[l], qh_u1_l = qh_u1[l];\n"
    @"                const float wu1_0 = float((int8_t)((q1_u1_l & 0xF) | ((qh_u1_l & kmask1) << 4)) - 32);\n"
    @"                const float wu1_1 = float((int8_t)((q2_u1_l & 0xF) | ((qh_u1_l & kmask2) << 2)) - 32);\n"
    @"                const float wu1_2 = float((int8_t)((q1_u1_l >> 4)  | ((qh_u1_l & kmask3) << 0)) - 32);\n"
    @"                const float wu1_3 = float((int8_t)((q2_u1_l >> 4)  | ((qh_u1_l & kmask4) >> 2)) - 32);\n"
    @"                su1_0[0] += y0_0 * wu1_0; su1_0[1] += y0_1 * wu1_0; su1_0[2] += y0_2 * wu1_2; su1_0[3] += y0_3 * wu1_3;\n"
    @"                su1_1[0] += y1_0 * wu1_0; su1_1[1] += y1_1 * wu1_1; su1_1[2] += y1_2 * wu1_2; su1_1[3] += y1_3 * wu1_3;\n"
    @"            }\n"
    @"        }\n"
    @"        const float sc0_g0 = float(sc_g0[0]), sc2_g0 = float(sc_g0[2]), sc4_g0 = float(sc_g0[4]), sc6_g0 = float(sc_g0[6]);\n"
    @"        g0_0 += d_g0 * (sg0_0[0] * sc0_g0 + sg0_0[1] * sc2_g0 + sg0_0[2] * sc4_g0 + sg0_0[3] * sc6_g0);\n"
    @"        g0_1 += d_g0 * (sg0_1[0] * sc0_g0 + sg0_1[1] * sc2_g0 + sg0_1[2] * sc4_g0 + sg0_1[3] * sc6_g0);\n"
    @"        const float sc0_u0 = float(sc_u0[0]), sc2_u0 = float(sc_u0[2]), sc4_u0 = float(sc_u0[4]), sc6_u0 = float(sc_u0[6]);\n"
    @"        u0_0 += d_u0 * (su0_0[0] * sc0_u0 + su0_0[1] * sc2_u0 + su0_0[2] * sc4_u0 + su0_0[3] * sc6_u0);\n"
    @"        u0_1 += d_u0 * (su0_1[0] * sc0_u0 + su0_1[1] * sc2_u0 + su0_1[2] * sc4_u0 + su0_1[3] * sc6_u0);\n"
    @"        if (blk_g1 != nullptr) {\n"
    @"            const float sc0_g1 = float(sc_g1[0]), sc2_g1 = float(sc_g1[2]), sc4_g1 = float(sc_g1[4]), sc6_g1 = float(sc_g1[6]);\n"
    @"            g1_0 += d_g1 * (sg1_0[0] * sc0_g1 + sg1_0[1] * sc2_g1 + sg1_0[2] * sc4_g1 + sg1_0[3] * sc6_g1);\n"
    @"            g1_1 += d_g1 * (sg1_1[0] * sc0_g1 + sg1_1[1] * sc2_g1 + sg1_1[2] * sc4_g1 + sg1_1[3] * sc6_g1);\n"
    @"            const float sc0_u1 = float(sc_u1[0]), sc2_u1 = float(sc_u1[2]), sc4_u1 = float(sc_u1[4]), sc6_u1 = float(sc_u1[6]);\n"
    @"            u1_0 += d_u1 * (su1_0[0] * sc0_u1 + su1_0[1] * sc2_u1 + su1_0[2] * sc4_u1 + su1_0[3] * sc6_u1);\n"
    @"            u1_1 += d_u1 * (su1_1[0] * sc0_u1 + su1_1[1] * sc2_u1 + su1_1[2] * sc4_u1 + su1_1[3] * sc6_u1);\n"
    @"        }\n"
    @"    }\n"
    @"    g0_0 = simd_sum(g0_0); u0_0 = simd_sum(u0_0);\n"
    @"    g0_1 = simd_sum(g0_1); u0_1 = simd_sum(u0_1);\n"
    @"    g1_0 = simd_sum(g1_0); u1_0 = simd_sum(u1_0);\n"
    @"    g1_1 = simd_sum(g1_1); u1_1 = simd_sum(u1_1);\n"
    @"    if (tiisg == 0) {\n"
    @"        constexpr float kGelu = 0.7978845608f;\n"
    @"        if (t_base + 0u < bSz) {\n"
    @"            float act0 = (activationKind == 2u)\n"
    @"                ? (0.5f * g0_0 * (1.0f + precise::tanh(kGelu * (g0_0 + 0.044715f * g0_0 * g0_0 * g0_0))))\n"
    @"                : (g0_0 / (1.0f + precise::exp(-g0_0)));\n"
    @"            hb[(t_base + 0u) * N + first_row] = act0 * u0_0;\n"
    @"            if (first_row + 1u < N) {\n"
    @"                float act1 = (activationKind == 2u)\n"
    @"                    ? (0.5f * g1_0 * (1.0f + precise::tanh(kGelu * (g1_0 + 0.044715f * g1_0 * g1_0 * g1_0))))\n"
    @"                    : (g1_0 / (1.0f + precise::exp(-g1_0)));\n"
    @"                hb[(t_base + 0u) * N + first_row + 1u] = act1 * u1_0;\n"
    @"            }\n"
    @"        }\n"
    @"        if (t_base + 1u < bSz) {\n"
    @"            float act0 = (activationKind == 2u)\n"
    @"                ? (0.5f * g0_1 * (1.0f + precise::tanh(kGelu * (g0_1 + 0.044715f * g0_1 * g0_1 * g0_1))))\n"
    @"                : (g0_1 / (1.0f + precise::exp(-g0_1)));\n"
    @"            hb[(t_base + 1u) * N + first_row] = act0 * u0_1;\n"
    @"            if (first_row + 1u < N) {\n"
    @"                float act1 = (activationKind == 2u)\n"
    @"                    ? (0.5f * g1_1 * (1.0f + precise::tanh(kGelu * (g1_1 + 0.044715f * g1_1 * g1_1 * g1_1))))\n"
    @"                    : (g1_1 / (1.0f + precise::exp(-g1_1)));\n"
    @"                hb[(t_base + 1u) * N + first_row + 1u] = act1 * u1_1;\n"
    @"            }\n"
    @"        }\n"
    @"    }\n"
    @"}\n"];
}

// ── Fused Q6_K MR4 Matvec with In-Kernel Softcap (Logit projection) ─────────
static void aljabr_build_q6_k_softcap_src(NSMutableString *src) {
  [src appendString:
    @"\nkernel void aljabr_matvec_tb_q6_k_mr4_softcap_kernel(\n"
    @"    device float* C [[buffer(0)]],\n"
    @"    device const float* A [[buffer(1)]],\n"
    @"    device const block_q6_K* B [[buffer(2)]],\n"
    @"    constant uint& K [[buffer(3)]],\n"
    @"    constant uint& N [[buffer(4)]],\n"
    @"    constant float& cap [[buffer(5)]],\n"
    @"    uint2 tgid [[threadgroup_position_in_grid]],\n"
    @"    ushort2 tid [[thread_position_in_threadgroup]]) {\n"
    @"    const uint nb = K >> 8u;\n"
    @"    const uint sgitg = (uint)tid.x >> 5u;\n"
    @"    const ushort tiisg = tid.x & 31u;\n"
    @"    const uint first_row = tgid.x * 4u + sgitg * 2u;\n"
    @"    if (first_row >= N) return;\n"
    @"    device const float* A_t = A + (uint)tgid.y * K;\n"
    @"    device const block_q6_K* x0 = B + first_row * nb;\n"
    @"    device const block_q6_K* x1 = (first_row + 1u < N) ? (x0 + nb) : nullptr;\n"
    @"    constexpr uint8_t kmask1 = 0x03;\n"
    @"    constexpr uint8_t kmask2 = 0x0C;\n"
    @"    constexpr uint8_t kmask3 = 0x30;\n"
    @"    constexpr uint8_t kmask4 = 0xC0;\n"
    @"    const short s_tid = tiisg / 2;\n"
    @"    const short ix    = tiisg % 2;\n"
    @"    const short ip    = s_tid / 8;\n"
    @"    const short il    = s_tid % 8;\n"
    @"    const short l0    = 4 * il;\n"
    @"    const short is    = 8 * ip + l0 / 16;\n"
    @"    const short y_offset   = 128 * ip + l0;\n"
    @"    const short q_offset_l =  64 * ip + l0;\n"
    @"    const short q_offset_h =  32 * ip + l0;\n"
    @"    float sum0 = 0.0f;\n"
    @"    float sum1 = 0.0f;\n"
    @"    for (uint i = ix; i < nb; i += 2u) {\n"
    @"        device const float* y = A_t + i * 256u + y_offset;\n"
    @"        float yl[16];\n"
    @"        for (short l = 0; l < 4; ++l) {\n"
    @"            yl[4 * l + 0] = y[l + 0];\n"
    @"            yl[4 * l + 1] = y[l + 32];\n"
    @"            yl[4 * l + 2] = y[l + 64];\n"
    @"            yl[4 * l + 3] = y[l + 96];\n"
    @"        }\n"
    @"        {\n"
    @"            device const block_q6_K* blk0 = x0 + i;\n"
    @"            device const uint8_t* q1 = blk0->ql + q_offset_l;\n"
    @"            device const uint8_t* q2 = q1 + 32;\n"
    @"            device const uint8_t* qh = blk0->qh + q_offset_h;\n"
    @"            device const int8_t*  sc = blk0->scales + is;\n"
    @"            const float d = float(blk0->d);\n"
    @"            float4 sums = {0.f, 0.f, 0.f, 0.f};\n"
    @"            for (short l = 0; l < 4; ++l) {\n"
    @"                const uint8_t q1_l = q1[l];\n"
    @"                const uint8_t q2_l = q2[l];\n"
    @"                const uint8_t qh_l = qh[l];\n"
    @"                sums[0] += yl[4*l + 0] * float((int8_t)((q1_l & 0xF) | ((qh_l & kmask1) << 4)) - 32);\n"
    @"                sums[1] += yl[4*l + 1] * float((int8_t)((q2_l & 0xF) | ((qh_l & kmask2) << 2)) - 32);\n"
    @"                sums[2] += yl[4*l + 2] * float((int8_t)((q1_l >> 4) | ((qh_l & kmask3) << 0)) - 32);\n"
    @"                sums[3] += yl[4*l + 3] * float((int8_t)((q2_l >> 4) | ((qh_l & kmask4) >> 2)) - 32);\n"
    @"            }\n"
    @"            sum0 += d * (sums[0] * float(sc[0]) + sums[1] * float(sc[2]) + sums[2] * float(sc[4]) + sums[3] * float(sc[6]));\n"
    @"        }\n"
    @"        if (x1 != nullptr) {\n"
    @"            device const block_q6_K* blk1 = x1 + i;\n"
    @"            device const uint8_t* q1 = blk1->ql + q_offset_l;\n"
    @"            device const uint8_t* q2 = q1 + 32;\n"
    @"            device const uint8_t* qh = blk1->qh + q_offset_h;\n"
    @"            device const int8_t*  sc = blk1->scales + is;\n"
    @"            const float d = float(blk1->d);\n"
    @"            float4 sums = {0.f, 0.f, 0.f, 0.f};\n"
    @"            for (short l = 0; l < 4; ++l) {\n"
    @"                const uint8_t q1_l = q1[l];\n"
    @"                const uint8_t q2_l = q2[l];\n"
    @"                const uint8_t qh_l = qh[l];\n"
    @"                sums[0] += yl[4*l + 0] * float((int8_t)((q1_l & 0xF) | ((qh_l & kmask1) << 4)) - 32);\n"
    @"                sums[1] += yl[4*l + 1] * float((int8_t)((q2_l & 0xF) | ((qh_l & kmask2) << 2)) - 32);\n"
    @"                sums[2] += yl[4*l + 2] * float((int8_t)((q1_l >> 4) | ((qh_l & kmask3) << 0)) - 32);\n"
    @"                sums[3] += yl[4*l + 3] * float((int8_t)((q2_l >> 4) | ((qh_l & kmask4) >> 2)) - 32);\n"
    @"            }\n"
    @"            sum1 += d * (sums[0] * float(sc[0]) + sums[1] * float(sc[2]) + sums[2] * float(sc[4]) + sums[3] * float(sc[6]));\n"
    @"        }\n"
    @"    }\n"
    @"    sum0 = simd_sum(sum0);\n"
    @"    sum1 = simd_sum(sum1);\n"
    @"    if (tiisg == 0) {\n"
    @"        if (cap > 0.0f) {\n"
    @"            sum0 = cap * precise::tanh(sum0 / cap);\n"
    @"            sum1 = cap * precise::tanh(sum1 / cap);\n"
    @"        }\n"
    @"        C[(uint)tgid.y * N + first_row] = sum0;\n"
    @"        if (first_row + 1u < N) C[(uint)tgid.y * N + first_row + 1u] = sum1;\n"
    @"    }\n"
    @"}\n"];
}

// ── Fused Q4_K MR4 Matvec with In-Kernel Softcap (Logit projection) ─────────
static void aljabr_build_q4_k_softcap_src(NSMutableString *src) {
  [src appendString:
    @"\nkernel void aljabr_matvec_tb_q4_k_mr4_softcap_kernel(\n"
    @"    device float* C [[buffer(0)]],\n"
    @"    device const float* A [[buffer(1)]],\n"
    @"    device const block_q4_K* B [[buffer(2)]],\n"
    @"    constant uint& K [[buffer(3)]],\n"
    @"    constant uint& N [[buffer(4)]],\n"
    @"    constant float& cap [[buffer(5)]],\n"
    @"    uint2 tgid [[threadgroup_position_in_grid]],\n"
    @"    ushort2 tid [[thread_position_in_threadgroup]]) {\n"
    @"    const uint nb = K >> 8u;\n"
    @"    const uint sgitg = (uint)tid.x >> 5u;\n"
    @"    const ushort tiisg = tid.x & 31u;\n"
    @"    const uint first_row = tgid.x * 4u + sgitg * 2u;\n"
    @"    if (first_row >= N) return;\n"
    @"    device const float* A_t = A + (uint)tgid.y * K;\n"
    @"    device const block_q4_K* blk_row0 = B + first_row * nb;\n"
    @"    device const block_q4_K* blk_row1 = (first_row + 1u < N) ? (blk_row0 + nb) : nullptr;\n"
    @"    constexpr uint16_t kmask1 = 0x3f3f;\n"
    @"    constexpr uint16_t kmask2 = 0x0f0f;\n"
    @"    constexpr uint16_t kmask3 = 0xc0c0;\n"
    @"    const ushort ix = tiisg / 8u;\n"
    @"    const ushort it = tiisg % 8u;\n"
    @"    const ushort iq = it / 4u;\n"
    @"    const ushort ir = it % 4u;\n"
    @"    device const float* y4 = A_t + (uint)ix * 256u + 64u * (uint)iq + 8u * (uint)ir;\n"
    @"    uint16_t sc16_0[4];\n"
    @"    thread const uint8_t* sc8_0 = (thread const uint8_t*)sc16_0;\n"
    @"    uint16_t sc16_1[4];\n"
    @"    thread const uint8_t* sc8_1 = (thread const uint8_t*)sc16_1;\n"
    @"    float sum0 = 0.0f;\n"
    @"    float sum1 = 0.0f;\n"
    @"    for (uint ib = ix; ib < nb; ib += 4u) {\n"
    @"        float yl[16];\n"
    @"        float yh[16];\n"
    @"        float4 sumy = {0.f, 0.f, 0.f, 0.f};\n"
    @"        yl[0] = y4[0];   sumy[0] += yl[0];  yl[8]  = y4[32];  sumy[1] += yl[8];\n"
    @"        yl[1] = y4[1];   sumy[0] += yl[1];  yl[9]  = y4[33];  sumy[1] += yl[9];\n"
    @"        yl[2] = y4[2];   sumy[0] += yl[2];  yl[10] = y4[34];  sumy[1] += yl[10];\n"
    @"        yl[3] = y4[3];   sumy[0] += yl[3];  yl[11] = y4[35];  sumy[1] += yl[11];\n"
    @"        yl[4] = y4[4];   sumy[0] += yl[4];  yl[12] = y4[36];  sumy[1] += yl[12];\n"
    @"        yl[5] = y4[5];   sumy[0] += yl[5];  yl[13] = y4[37];  sumy[1] += yl[13];\n"
    @"        yl[6] = y4[6];   sumy[0] += yl[6];  yl[14] = y4[38];  sumy[1] += yl[14];\n"
    @"        yl[7] = y4[7];   sumy[0] += yl[7];  yl[15] = y4[39];  sumy[1] += yl[15];\n"
    @"        yh[0] = y4[128]; sumy[2] += yh[0];  yh[8]  = y4[160]; sumy[3] += yh[8];\n"
    @"        yh[1] = y4[129]; sumy[2] += yh[1];  yh[9]  = y4[161]; sumy[3] += yh[9];\n"
    @"        yh[2] = y4[130]; sumy[2] += yh[2];  yh[10] = y4[162]; sumy[3] += yh[10];\n"
    @"        yh[3] = y4[131]; sumy[2] += yh[3];  yh[11] = y4[163]; sumy[3] += yh[11];\n"
    @"        yh[4] = y4[132]; sumy[2] += yh[4];  yh[12] = y4[164]; sumy[3] += yh[12];\n"
    @"        yh[5] = y4[133]; sumy[2] += yh[5];  yh[13] = y4[165]; sumy[3] += yh[13];\n"
    @"        yh[6] = y4[134]; sumy[2] += yh[6];  yh[14] = y4[166]; sumy[3] += yh[14];\n"
    @"        yh[7] = y4[135]; sumy[2] += yh[7];  yh[15] = y4[167]; sumy[3] += yh[15];\n"
    @"        device const block_q4_K* blk0 = blk_row0 + ib;\n"
    @"        device const uint16_t* sc0 = (device const uint16_t*)blk0->scales + iq;\n"
    @"        device const uint16_t* q1_0 = (device const uint16_t*)blk0->qs + 16u * iq + 4u * ir;\n"
    @"        device const half* dh0 = (device const half*)&blk0->dm;\n"
    @"        sc16_0[0] = sc0[0] & kmask1;\n"
    @"        sc16_0[1] = sc0[2] & kmask1;\n"
    @"        sc16_0[2] = ((sc0[4] >> 0) & kmask2) | ((sc0[0] & kmask3) >> 2);\n"
    @"        sc16_0[3] = ((sc0[4] >> 4) & kmask2) | ((sc0[2] & kmask3) >> 2);\n"
    @"        device const uint16_t* q2_0 = q1_0 + 32;\n"
    @"        float4 acc1_0 = {0.f, 0.f, 0.f, 0.f};\n"
    @"        float4 acc2_0 = {0.f, 0.f, 0.f, 0.f};\n"
    @"        acc1_0[0] = yl[0]*float(q1_0[0]&0x000Fu) + yl[2]*float(q1_0[1]&0x000Fu) + yl[4]*float(q1_0[2]&0x000Fu) + yl[6]*float(q1_0[3]&0x000Fu);\n"
    @"        acc1_0[1] = yl[1]*float(q1_0[0]&0x0F00u) + yl[3]*float(q1_0[1]&0x0F00u) + yl[5]*float(q1_0[2]&0x0F00u) + yl[7]*float(q1_0[3]&0x0F00u);\n"
    @"        acc1_0[2] = yl[8]*float(q1_0[0]&0x00F0u) + yl[10]*float(q1_0[1]&0x00F0u) + yl[12]*float(q1_0[2]&0x00F0u) + yl[14]*float(q1_0[3]&0x00F0u);\n"
    @"        acc1_0[3] = yl[9]*float(q1_0[0]&0xF000u) + yl[11]*float(q1_0[1]&0xF000u) + yl[13]*float(q1_0[2]&0xF000u) + yl[15]*float(q1_0[3]&0xF000u);\n"
    @"        acc2_0[0] = yh[0]*float(q2_0[0]&0x000Fu) + yh[2]*float(q2_0[1]&0x000Fu) + yh[4]*float(q2_0[2]&0x000Fu) + yh[6]*float(q2_0[3]&0x000Fu);\n"
    @"        acc2_0[1] = yh[1]*float(q2_0[0]&0x0F00u) + yh[3]*float(q2_0[1]&0x0F00u) + yh[5]*float(q2_0[2]&0x0F00u) + yh[7]*float(q2_0[3]&0x0F00u);\n"
    @"        acc2_0[2] = yh[8]*float(q2_0[0]&0x00F0u) + yh[10]*float(q2_0[1]&0x00F0u) + yh[12]*float(q2_0[2]&0x00F0u) + yh[14]*float(q2_0[3]&0x00F0u);\n"
    @"        acc2_0[3] = yh[9]*float(q2_0[0]&0xF000u) + yh[11]*float(q2_0[1]&0xF000u) + yh[13]*float(q2_0[2]&0xF000u) + yh[15]*float(q2_0[3]&0xF000u);\n"
    @"        sum0 += float(dh0[0]) * ((acc1_0[0] + (1.f/256.f) * acc1_0[1]) * float(sc8_0[0]) +\n"
    @"                                 (acc1_0[2] + (1.f/256.f) * acc1_0[3]) * float(sc8_0[1]) * (1.f/16.f) +\n"
    @"                                 (acc2_0[0] + (1.f/256.f) * acc2_0[1]) * float(sc8_0[4]) +\n"
    @"                                 (acc2_0[2] + (1.f/256.f) * acc2_0[3]) * float(sc8_0[5]) * (1.f/16.f)) -\n"
    @"                float(dh0[1]) * (sumy[0] * float(sc8_0[2]) + sumy[1] * float(sc8_0[3]) + sumy[2] * float(sc8_0[6]) + sumy[3] * float(sc8_0[7]));\n"
    @"        if (blk_row1 != nullptr) {\n"
    @"            device const block_q4_K* blk1 = blk_row1 + ib;\n"
    @"            device const uint16_t* sc1 = (device const uint16_t*)blk1->scales + iq;\n"
    @"            device const uint16_t* q1_1 = (device const uint16_t*)blk1->qs + 16u * iq + 4u * ir;\n"
    @"            device const half* dh1 = (device const half*)&blk1->dm;\n"
    @"            sc16_1[0] = sc1[0] & kmask1;\n"
    @"            sc16_1[1] = sc1[2] & kmask1;\n"
    @"            sc16_1[2] = ((sc1[4] >> 0) & kmask2) | ((sc1[0] & kmask3) >> 2);\n"
    @"            sc16_1[3] = ((sc1[4] >> 4) & kmask2) | ((sc1[2] & kmask3) >> 2);\n"
    @"            device const uint16_t* q2_1 = q1_1 + 32;\n"
    @"            float4 acc1_1 = {0.f, 0.f, 0.f, 0.f};\n"
    @"            float4 acc2_1 = {0.f, 0.f, 0.f, 0.f};\n"
    @"            acc1_1[0] = yl[0]*float(q1_1[0]&0x000Fu) + yl[2]*float(q1_1[1]&0x000Fu) + yl[4]*float(q1_1[2]&0x000Fu) + yl[6]*float(q1_1[3]&0x000Fu);\n"
    @"            acc1_1[1] = yl[1]*float(q1_1[0]&0x0F00u) + yl[3]*float(q1_1[1]&0x0F00u) + yl[5]*float(q1_1[2]&0x0F00u) + yl[7]*float(q1_1[3]&0x0F00u);\n"
    @"            acc1_1[2] = yl[8]*float(q1_1[0]&0x00F0u) + yl[10]*float(q1_1[1]&0x00F0u) + yl[12]*float(q1_1[2]&0x00F0u) + yl[14]*float(q1_1[3]&0x00F0u);\n"
    @"            acc1_1[3] = yl[9]*float(q1_1[0]&0xF000u) + yl[11]*float(q1_1[1]&0xF000u) + yl[13]*float(q1_1[2]&0xF000u) + yl[15]*float(q1_1[3]&0xF000u);\n"
    @"            acc2_1[0] = yh[0]*float(q2_1[0]&0x000Fu) + yh[2]*float(q2_1[1]&0x000Fu) + yh[4]*float(q2_1[2]&0x000Fu) + yh[6]*float(q2_1[3]&0x000Fu);\n"
    @"            acc2_1[1] = yh[1]*float(q2_1[0]&0x0F00u) + yh[3]*float(q2_1[1]&0x0F00u) + yh[5]*float(q2_1[2]&0x0F00u) + yh[7]*float(q2_1[3]&0x0F00u);\n"
    @"            acc2_1[2] = yh[8]*float(q2_1[0]&0x00F0u) + yh[10]*float(q2_1[1]&0x00F0u) + yh[12]*float(q2_1[2]&0x00F0u) + yh[14]*float(q2_1[3]&0x00F0u);\n"
    @"            acc2_1[3] = yh[9]*float(q2_1[0]&0xF000u) + yh[11]*float(q2_1[1]&0xF000u) + yh[13]*float(q2_1[2]&0xF000u) + yh[15]*float(q2_1[3]&0xF000u);\n"
    @"            sum1 += float(dh1[0]) * ((acc1_1[0] + (1.f/256.f) * acc1_1[1]) * float(sc8_1[0]) +\n"
    @"                                     (acc1_1[2] + (1.f/256.f) * acc1_1[3]) * float(sc8_1[1]) * (1.f/16.f) +\n"
    @"                                     (acc2_1[0] + (1.f/256.f) * acc2_1[1]) * float(sc8_1[4]) +\n"
    @"                                     (acc2_1[2] + (1.f/256.f) * acc2_1[3]) * float(sc8_1[5]) * (1.f/16.f)) -\n"
    @"                    float(dh1[1]) * (sumy[0] * float(sc8_1[2]) + sumy[1] * float(sc8_1[3]) + sumy[2] * float(sc8_1[6]) + sumy[3] * float(sc8_1[7]));\n"
    @"        }\n"
    @"        y4 += 4u * 256u;\n"
    @"    }\n"
    @"    sum0 = simd_sum(sum0);\n"
    @"    sum1 = simd_sum(sum1);\n"
    @"    if (tiisg == 0) {\n"
    @"        if (cap > 0.0f) {\n"
    @"            sum0 = cap * precise::tanh(sum0 / cap);\n"
    @"            sum1 = cap * precise::tanh(sum1 / cap);\n"
    @"        }\n"
    @"        C[(uint)tgid.y * N + first_row] = sum0;\n"
    @"        if (first_row + 1u < N) C[(uint)tgid.y * N + first_row + 1u] = sum1;\n"
    @"    }\n"
    @"}\n"];
}
